  init();

  function init() {
    if (!window.crypto || !window.crypto.subtle) {
      showStatus("Ta przeglądarka nie obsługuje Web Crypto. Wybierz nowszą przeglądarkę.", true);
      toggleApplicationAvailability(false);
      return;
    }

    applyUiScale(state.uiScale, { persist: false, announce: false });
    registerPwaServiceWorker();
    removeChartsView();
    removeMicrocycleView();
    reorganizeTrainingLayout();
    bindEvents();
    updateInstallAppUi();
    enhanceInlineHelp();
    populateExerciseSuggestions();
    renderHabitWeekdayPicker();
    renderTrainingGeneratorState();
    renderAiExercisePicker();
    renderAiModeRecommendations();
    syncExerciseTemplateInput("workout");
    syncExerciseTemplateInput("template");
    resetEntryForm();
    resetCustomGoalForm();
    updateVaultControls();
    syncLockableState();
    applyActiveTab();
    renderDashboard();
    updateSyncUi();
    hydrateCloudSyncState();
    updateCloudSyncUi();
    initializeLeagueClient();

    const storedVault = readStoredVault();
    if (storedVault) {
      const hasAnyRecovery = hasRecoveryConfig(storedVault) || Boolean(readEmailRecoveryConfig(storedVault));
      showStatus(hasAnyRecovery
        ? "Wykryto lokalne konto. Zaloguj się hasłem albo skorzystaj z pytania pomocniczego."
        : "Wykryto lokalne konto. Zaloguj się hasłem, aby wczytać dane.");
      attemptLocalSessionRestore(storedVault);
    } else {
      showStatus("Utwórz konto lokalne, aby bezpiecznie zapisywać postępy fitness.");
      clearLocalSession();
    }

    syncCommandDeckOrder();
    processPendingLeagueInviteFromLocation();
    processAccountLinkFromLocation();
    hydrateEmailRecoveryLinkState();
  }

  function registerPwaServiceWorker() {
    if (!("serviceWorker" in navigator) || window.location.protocol === "file:") {
      updateInstallAppUi();
      return;
    }

    navigator.serviceWorker.addEventListener("controllerchange", () => {
      if (state.version.reloading) {
        return;
      }
      state.version.reloading = true;
      window.location.reload();
    });

    window.addEventListener("load", () => {
      navigator.serviceWorker.register("sw.js", { scope: "./" })
        .then((registration) => {
          state.version.registration = registration;

          if (registration.waiting && navigator.serviceWorker.controller) {
            markServiceWorkerUpdateReady(registration.waiting);
          }

          registration.addEventListener("updatefound", () => {
            const worker = registration.installing;
            if (!worker) {
              return;
            }
            worker.addEventListener("statechange", () => {
              if (worker.state === "installed" && navigator.serviceWorker.controller) {
                markServiceWorkerUpdateReady(worker);
              }
            });
          });

          registration.update().catch(() => {});
          updateInstallAppUi();
        })
        .catch(() => {
          showStatus("Nie udało się uruchomić trybu PWA. Aplikacja nadal działa lokalnie w przeglądarce.", true);
          updateInstallAppUi();
        });
    }, { once: true });
  }

  function isRunningStandalone() {
    return Boolean(
      (window.matchMedia && window.matchMedia("(display-mode: standalone)").matches)
        || window.navigator.standalone === true
    );
  }

  function isLikelyIosDevice() {
    const userAgent = window.navigator.userAgent || "";
    const platform = window.navigator.platform || "";
    return /iphone|ipad|ipod/i.test(userAgent)
      || (platform === "MacIntel" && window.navigator.maxTouchPoints > 1);
  }

  function isLikelyMobileDevice() {
    return /android|iphone|ipad|ipod|mobile/i.test(window.navigator.userAgent || "");
  }

  function getInstallFallbackMessage() {
    if (window.location.protocol !== "https:" && !LOCAL_ONLY_HOSTS.has(window.location.hostname)) {
      return "Instalacja PWA wymaga HTTPS. Otwórz BeTheOne z adresu GitHub Pages zaczynającego się od https://.";
    }

    if (isLikelyIosDevice()) {
      return "Na iPhonie lub iPadzie otwórz aplikację w Safari, kliknij Udostępnij, a potem wybierz „Do ekranu początkowego”. iOS nie udostępnia aplikacjom webowym takiego samego okna instalacji jak Android i desktop.";
    }

    if (isLikelyMobileDevice()) {
      return "Jeśli okno instalacji nie pojawiło się automatycznie, otwórz menu przeglądarki na telefonie i wybierz „Zainstaluj aplikację” albo „Dodaj do ekranu głównego”.";
    }

    return "Jeśli okno instalacji jeszcze się nie pojawia, odśwież stronę po wdrożeniu GitHub Pages i sprawdź menu przeglądarki: „Zainstaluj aplikację” lub „Aplikacje”.";
  }

  function updateInstallAppUi() {
    if (!elements.installAppButton || !elements.installAppHint) {
      return;
    }

    const standalone = isRunningStandalone() || state.installPrompt.installed;
    elements.installAppButton.disabled = false;
    elements.installAppButton.classList.toggle("is-installed", standalone);
    elements.installAppButton.textContent = standalone ? "Aplikacja pobrana" : "Pobierz aplikację";

    if (standalone) {
      elements.installAppHint.textContent = "BeTheOne działa już jak zainstalowana aplikacja na tym urządzeniu.";
      return;
    }

    elements.installAppHint.textContent = state.installPrompt.promptReady
      ? "PWA jest gotowe. Kliknij przycisk, aby otworzyć okno instalacji."
      : "Przycisk działa na komputerze i telefonie. Jeśli przeglądarka nie pokaże okna instalacji, wyświetlimy instrukcję dla urządzenia.";
  }

  function handleBeforeInstallPrompt(event) {
    event.preventDefault();
    state.installPrompt.deferredPrompt = event;
    state.installPrompt.promptReady = true;
    updateInstallAppUi();
  }

  function handleAppInstalled() {
    state.installPrompt.deferredPrompt = null;
    state.installPrompt.promptReady = false;
    state.installPrompt.installed = true;
    updateInstallAppUi();
    showStatus("BeTheOne zostało pobrane jako aplikacja PWA.");
  }

  async function handleInstallAppClick() {
    if (isRunningStandalone() || state.installPrompt.installed) {
      showStatus("BeTheOne jest już uruchomione jako aplikacja na tym urządzeniu.");
      updateInstallAppUi();
      return;
    }

    const promptEvent = state.installPrompt.deferredPrompt;
    if (!promptEvent) {
      showStatus(getInstallFallbackMessage());
      updateInstallAppUi();
      return;
    }

    try {
      promptEvent.prompt();
      const choice = await promptEvent.userChoice;
      state.installPrompt.deferredPrompt = null;
      state.installPrompt.promptReady = false;

      if (choice && choice.outcome === "accepted") {
        state.installPrompt.installed = true;
        showStatus("Instalacja BeTheOne została rozpoczęta.");
      } else {
        showStatus("Instalacja została anulowana. Przycisk zostaje dostępny, więc możesz wrócić do niej później.");
      }
    } catch (_error) {
      showStatus(getInstallFallbackMessage());
    } finally {
      updateInstallAppUi();
    }
  }

  function getInitialUiScale() {
    try {
      const stored = localStorage.getItem(UI_SCALE_STORAGE_KEY);
      if (UI_SCALE_VALUES.includes(stored)) {
        return stored;
      }
    } catch (_error) {
      // UI density is only a local preference.
    }

    return window.matchMedia && window.matchMedia("(max-width: 760px)").matches
      ? "compact"
      : "medium";
  }

  function applyUiScale(value, options = {}) {
    const nextScale = UI_SCALE_VALUES.includes(value) ? value : "medium";
    state.uiScale = nextScale;
    document.documentElement.dataset.uiScale = nextScale;

    if (elements.uiScaleSelect) {
      elements.uiScaleSelect.value = nextScale;
    }

    if (options.persist !== false) {
      try {
        localStorage.setItem(UI_SCALE_STORAGE_KEY, nextScale);
      } catch (_error) {
        // Losing this preference is harmless; the app will fall back on next start.
      }
    }

    if (options.announce !== false) {
      const label = UI_SCALE_OPTIONS.find((item) => item.value === nextScale)?.label || "Średni";
      showStatus(`Ustawiono rozmiar GUI: ${label}.`);
    }
  }

  function handleUiScaleChange() {
    applyUiScale(elements.uiScaleSelect.value);
  }

  function getActiveVerifiedEmailRecoveryConfig() {
    const storedVault = readStoredVault();
    const storedConfig = readEmailRecoveryConfig(storedVault);
    const sessionConfig = state.session && state.session.emailRecoveryConfig
      ? state.session.emailRecoveryConfig
      : null;
    return isVerifiedEmailRecoveryConfig(sessionConfig)
      ? sessionConfig
      : isVerifiedEmailRecoveryConfig(storedConfig)
        ? storedConfig
        : null;
  }

  function buildAccountLink(email) {
    const url = new URL(window.location.href);
    url.searchParams.delete("error");
    url.searchParams.delete("error_code");
    url.searchParams.delete("error_description");
    url.hash = `${ACCOUNT_LINK_HASH_KEY}=${encodeURIComponent(normalizeEmailAddress(email))}`;
    return url.toString();
  }

  function readAccountLinkEmailFromLocation() {
    try {
      const hash = (window.location.hash || "").replace(/^#/, "");
      if (!hash) {
        return "";
      }
      const hashParams = new URLSearchParams(hash);
      return normalizeEmailAddress(hashParams.get(ACCOUNT_LINK_HASH_KEY) || "");
    } catch (_error) {
      return "";
    }
  }

  function processAccountLinkFromLocation() {
    const email = readAccountLinkEmailFromLocation();
    if (!email) {
      return;
    }

    if (elements.recoveryEmailInput) {
      elements.recoveryEmailInput.value = email;
    }
    state.activeTab = "login";
    applyActiveTab();
    showStatus("Wczytano link konta. Wyślij kod do tego emaila, wpisz kod z wiadomości i pobierz zaszyfrowane dane z Supabase.");
  }

  async function handleCopyAccountLink() {
    try {
      const config = getActiveVerifiedEmailRecoveryConfig();
      if (!config || !config.email) {
        throw new Error("Najpierw zweryfikuj email odzyskiwania. Dopiero wtedy można wygenerować bezpieczny link konta.");
      }

      const localVault = readStoredVault();
      if (!localVault) {
        throw new Error("Brak lokalnego vaulta do powiązania z kontem.");
      }

      await copyTextValue(buildAccountLink(config.email), "Skopiowano bezpieczny link konta. Otwórz go na drugim urządzeniu i potwierdź email kodem.");
    } catch (error) {
      showStatus(error.message || "Nie udało się wygenerować linku konta.", true);
    }
  }

  async function handleSendAccountSyncEmail() {
    try {
      const email = readRecoveryEmailInput() || readAccountLinkEmailFromLocation();
      if (!email) {
        throw new Error("Wpisz email konta, które chcesz połączyć z tym urządzeniem.");
      }
      if (!navigator.onLine) {
        throw new Error("Połączenie konta przez email wymaga internetu.");
      }

      state.emailRecovery.loading = true;
      storePendingEmailRecovery(email, "account_sync");
      runSafeUiStep("updateVaultControls.accountSyncStart", updateVaultControls);
      await sendSupabaseEmailOtp(email, { shouldCreateUser: false });
      showStatus("Wysłano kod do konta. Wpisz kod z maila i kliknij „Pobierz konto z Supabase”.");
    } catch (error) {
      clearPendingEmailRecovery();
      showStatus(formatEmailRecoveryError(error, "Nie udało się wysłać kodu do konta."), true);
    } finally {
      state.emailRecovery.loading = false;
      runSafeUiStep("updateVaultControls.accountSyncEnd", updateVaultControls);
    }
  }

  async function handleImportAccountFromSupabase() {
    try {
      const email = readRecoveryEmailInput() || state.emailRecovery.pendingEmail || readAccountLinkEmailFromLocation();
      const token = elements.recoveryEmailOtpInput ? normalizeEmailOtpCode(elements.recoveryEmailOtpInput.value) : "";
      if (!email) {
        throw new Error("Wpisz email konta, z którego chcesz pobrać dane.");
      }
      if (token.length < 4) {
        throw new Error("Wpisz kod z maila, aby potwierdzić dostęp do konta.");
      }

      state.emailRecovery.loading = true;
      state.cloudSync.loading = true;
      runSafeUiStep("updateVaultControls.accountImportStart", updateVaultControls);
      updateCloudSyncUi();

      const session = await verifySupabaseEmailOtp(email, token);
      state.cloudSync.client = ensureEmailRecoveryClient();
      state.cloudSync.accountEmail = normalizeEmailAddress(email);
      state.cloudSync.accountUserId = session.user.id;
      const remoteRecord = await fetchCloudVaultRecord(session.user.id);
      if (!remoteRecord) {
        throw new Error("To konto email nie ma jeszcze zaszyfrowanej kopii w Supabase. Najpierw zsynchronizuj dane z głównego urządzenia.");
      }

      importCloudVaultRecord(remoteRecord);
      clearPendingEmailRecovery();
      showStatus("Pobrano zaszyfrowane konto z Supabase. Zaloguj się lokalnym hasłem z głównego urządzenia, aby je odblokować.");
    } catch (error) {
      state.cloudSync.error = formatCloudSyncError(error);
      showStatus(formatEmailRecoveryError(error, state.cloudSync.error || "Nie udało się pobrać konta z Supabase."), true);
    } finally {
      state.emailRecovery.loading = false;
      state.cloudSync.loading = false;
      runSafeUiStep("updateVaultControls.accountImportEnd", updateVaultControls);
      updateCloudSyncUi();
    }
  }

  function markServiceWorkerUpdateReady(worker) {
    state.version.waitingWorker = worker;
    showAppUpdateNotice("Nowa wersja jest pobrana i gotowa do bezpiecznego przeładowania.");
  }

  function showAppUpdateNotice(message) {
    if (!elements.appUpdateNotice || state.version.updateDismissed) {
      return;
    }

    if (elements.appVersionText) {
      elements.appVersionText.textContent = `${message} Dane pozostają zaszyfrowane lokalnie.`;
    }
    elements.appUpdateNotice.classList.remove("is-hidden");
  }

  function dismissAppUpdateNotice() {
    state.version.updateDismissed = true;
    if (elements.appUpdateNotice) {
      elements.appUpdateNotice.classList.add("is-hidden");
    }
  }

  function applyAppUpdate() {
    const worker = state.version.waitingWorker || (state.version.registration && state.version.registration.waiting);
    if (worker) {
      worker.postMessage({ type: "SKIP_WAITING" });
      return;
    }
    window.location.reload();
  }

