    const workoutSupport = workoutHeader ? workoutHeader.querySelector(".panel-support") : null;
    const dailyWorkoutBlock = elements.workoutForm ? elements.workoutForm.closest(".insights-layout") : null;
    const workoutFormPanel = elements.workoutForm ? elements.workoutForm.parentElement : null;
    const workoutReviewPanel = elements.workoutBody && elements.workoutBody.closest(".table-wrap")
      ? elements.workoutBody.closest(".table-wrap").parentElement
      : null;
    const workoutReviewHeading = workoutReviewPanel ? workoutReviewPanel.querySelector("h3") : null;
    const workoutFilterToolbar = elements.workoutSearchInput ? elements.workoutSearchInput.closest(".filter-toolbar") : null;
    const workoutImportInput = elements.importWorkoutsCsvInput || null;
    const templateBlock = elements.templateSelect ? elements.templateSelect.closest(".planner-block") : null;
    const templateActionRow = elements.applyTemplateButton ? elements.applyTemplateButton.closest(".action-row") : null;
    const templateExerciseBlock = elements.templateExerciseBody ? elements.templateExerciseBody.closest(".planner-block") : null;
    const microcycleBlock = elements.programForm ? elements.programForm.closest(".planner-block") : null;
    const sessionBlock = elements.sessionBody ? elements.sessionBody.closest(".planner-block") : null;
    const exerciseSummaryBlock = elements.exerciseSummaryBody ? elements.exerciseSummaryBody.closest(".planner-block") : null;
    const historyHeader = historySection.querySelector(".panel-heading");
    const historyEyebrow = historyHeader ? historyHeader.querySelector(".eyebrow") : null;
    const historyTitle = historyHeader ? historyHeader.querySelector("h2") : null;
    const historySupport = historyHeader ? historyHeader.querySelector(".panel-support") : null;
    const historyAnalysisAnchor = elements.exerciseHistorySelect ? elements.exerciseHistorySelect.closest(".form-grid") : null;
    const historySummary = elements.exerciseHistorySummary || null;
    const historyToolbar = elements.exerciseHistoryDateFromInput ? elements.exerciseHistoryDateFromInput.closest(".filter-toolbar") : null;
    const historyCards = elements.exerciseHistoryCards || null;
    const historyCharts = elements.exerciseWeightChart ? elements.exerciseWeightChart.closest(".chart-grid") : null;
    const prPanel = elements.exercisePrList ? elements.exercisePrList.closest(".insights-layout > div, .insights-layout div") : null;
    const historyLayout = prPanel ? prPanel.parentElement : null;
    const historyTablePanel = elements.exerciseHistoryBody && elements.exerciseHistoryBody.closest(".table-wrap")
      ? elements.exerciseHistoryBody.closest(".table-wrap").parentElement
      : null;
    const sessionToolbar = elements.sessionDateFromInput ? elements.sessionDateFromInput.closest(".filter-toolbar") : null;
    const sessionHeader = sessionBlock ? sessionBlock.querySelector("h3") : null;
    const sessionHeadRow = sessionBlock ? sessionBlock.querySelector("thead tr") : null;
    const sessionApplyButton = document.getElementById("sessionApplyFiltersButton");

    if (workoutHeader && workoutIntro) {
      workoutSection.insertBefore(workoutHeader, workoutIntro);
    }

    if (workoutIntro) {
      workoutIntro.textContent = "Wybierz szablon, wpisz realne serie albo dodaj pojedyncza aktywność bez planu. Minimum przewijania, maksimum tempa podczas treningu.";
    }

