  function syncCustomGoalUnitForType() {
    const type = safeSelectValue(elements.customGoalTypeInput.value, CUSTOM_GOAL_TYPE_VALUES, "strength_reps");
    elements.customGoalUnitInput.value = getDefaultCustomGoalUnit(type);
  }

  function getPreparationModeDefaultDays(mode) {
    if (mode === "vacation") {
      return 56;
    }
    if (mode === "competition") {
      return 84;
    }
    if (mode === "test_5k") {
      return 42;
    }
    return null;
  }

  function handleCustomGoalPrepModeChange() {
    if (!elements.customGoalPrepModeInput || !elements.customGoalDueDateInput || elements.customGoalDueDateInput.value) {
      return;
    }
    const mode = safeSelectValue(elements.customGoalPrepModeInput.value, PREPARATION_MODE_VALUES, "none");
    const days = getPreparationModeDefaultDays(mode);
    if (!Number.isFinite(days)) {
      return;
    }
    elements.customGoalDueDateInput.value = addDaysToIsoDate(toISODate(new Date()), days);
    showStatus(`Ustawiono domyslny termin przygotowania: ${formatDisplayDate(elements.customGoalDueDateInput.value)}.`);
  }

  function syncCustomGoalFormMode() {
    const editing = Boolean(state.editingCustomGoalId);
    elements.saveCustomGoalButton.textContent = editing ? "Zapisz cel" : "Dodaj cel";
    elements.customGoalModeBadge.textContent = editing ? "Tryb edycji" : "Tryb dodawania";
    elements.customGoalModeBadge.className = `status-pill ${editing ? "status-unlocked" : "status-locked"}`;
  }

  function resetCustomGoalForm() {
    state.editingCustomGoalId = null;
    elements.customGoalForm.reset();
    elements.customGoalTypeInput.value = "strength_reps";
    elements.customGoalUnitInput.value = getDefaultCustomGoalUnit("strength_reps");
    if (elements.customGoalPrepModeInput) {
      elements.customGoalPrepModeInput.value = "none";
    }
    syncCustomGoalFormMode();
  }

  function readCustomGoalFromForm() {
    const type = safeSelectValue(elements.customGoalTypeInput.value, CUSTOM_GOAL_TYPE_VALUES, "strength_reps");
    const name = sanitizePlainText(elements.customGoalNameInput.value, 90);
    const metric = sanitizePlainText(elements.customGoalMetricInput.value, 80);
    const unit = safeSelectValue(elements.customGoalUnitInput.value, CUSTOM_GOAL_UNIT_VALUES, getDefaultCustomGoalUnit(type));
    const targetValue = parseOptionalNumber(elements.customGoalTargetInput.value, { label: "Wartość docelowa celu", min: 0.1, max: 10000 });
    const startValue = parseOptionalNumber(elements.customGoalStartInput.value, { label: "Punkt startowy celu", min: 0, max: 10000 });
    const dueDate = sanitizePlainText(elements.customGoalDueDateInput.value, 16);
    const prepMode = safeSelectValue(elements.customGoalPrepModeInput ? elements.customGoalPrepModeInput.value : "none", PREPARATION_MODE_VALUES, "none");

    if (!name) {
      throw new Error("Podaj nazwę celu, np. Podciągnąć się 10 razy.");
    }
    if (!Number.isFinite(targetValue)) {
      throw new Error("Podaj wartość docelową celu.");
    }
    if (["strength_reps", "strength_weight", "cardio_distance", "body_measurement"].includes(type) && !metric) {
      throw new Error("Podaj ćwiczenie albo metrykę, z której aplikacja ma liczyć progres.");
    }

    const previous = state.editingCustomGoalId
      ? state.data.customGoals.find((goal) => goal.id === state.editingCustomGoalId)
      : null;

    return normalizeCustomGoal({
      id: state.editingCustomGoalId || createCustomGoalId(),
      type,
      name,
      metric,
      targetValue,
      startValue,
      unit,
      dueDate: /^\d{4}-\d{2}-\d{2}$/.test(dueDate) ? dueDate : "",
      prepMode,
      notes: sanitizePlainText(elements.customGoalNotesInput.value, 220),
      createdAt: previous && previous.createdAt ? previous.createdAt : new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      archived: false,
    });
  }

  async function handleCustomGoalSubmit(event) {
    event.preventDefault();
    if (!requireUnlocked()) {
      return;
    }

    try {
      const goal = readCustomGoalFromForm();
      if (!goal) {
        throw new Error("Nie udało się przygotować celu do zapisu.");
      }

      if (!Array.isArray(state.data.customGoals)) {
        state.data.customGoals = [];
      }

      const existingIndex = state.data.customGoals.findIndex((item) => item.id === goal.id);
      if (existingIndex >= 0) {
        state.data.customGoals[existingIndex] = goal;
      } else {
        state.data.customGoals.push(goal);
      }

      state.data.customGoals = state.data.customGoals
        .map(normalizeCustomGoal)
        .filter(Boolean)
        .slice(-80);
      await persistVault();
      resetCustomGoalForm();
      renderDashboard();
      showStatus(existingIndex >= 0 ? "Zapisano zmiany celu." : "Dodano nowy cel użytkownika.");
    } catch (error) {
      showStatus(error.message || "Nie udało się zapisać celu.", true);
    }
  }

  function handleCustomGoalTableAction(event) {
    const actionButton = event.target.closest("button[data-custom-goal-id][data-custom-goal-action]");
    if (!actionButton || !state.unlocked) {
      return;
    }

    const goalId = actionButton.getAttribute("data-custom-goal-id");
    const goal = state.data.customGoals.find((item) => item.id === goalId);
    if (!goal) {
      return;
    }

    const action = actionButton.getAttribute("data-custom-goal-action");
    if (action === "edit") {
      populateCustomGoalForm(goal);
      return;
    }

    if (action === "delete") {
      deleteCustomGoal(goal);
    }
  }

  function populateCustomGoalForm(goal) {
    const normalized = normalizeCustomGoal(goal);
    if (!normalized) {
      return;
    }

    state.editingCustomGoalId = normalized.id;
    elements.customGoalTypeInput.value = normalized.type;
    elements.customGoalNameInput.value = normalized.name;
    elements.customGoalMetricInput.value = normalized.metric;
    elements.customGoalTargetInput.value = toInputValue(normalized.targetValue);
    elements.customGoalUnitInput.value = normalized.unit;
    elements.customGoalStartInput.value = toInputValue(normalized.startValue);
    elements.customGoalDueDateInput.value = normalized.dueDate || "";
    if (elements.customGoalPrepModeInput) {
      elements.customGoalPrepModeInput.value = normalized.prepMode || "none";
    }
    elements.customGoalNotesInput.value = normalized.notes || "";
    syncCustomGoalFormMode();
    elements.customGoalForm.scrollIntoView({ behavior: "smooth", block: "start" });
    showStatus(`Wczytano cel "${normalized.name}" do edycji.`);
  }

  async function deleteCustomGoal(goal) {
    if (!window.confirm(`Usunąć cel "${goal.name}"? Dane dziennika i treningów zostaną zachowane.`)) {
      return;
    }

    try {
      state.data.customGoals = state.data.customGoals.filter((item) => item.id !== goal.id);
      if (state.editingCustomGoalId === goal.id) {
        resetCustomGoalForm();
      }
      await persistVault();
      renderDashboard();
      showStatus(`Usunięto cel "${goal.name}".`);
    } catch (error) {
      showStatus(error.message || "Nie udało się usuńąć celu.", true);
    }
  }

  async function handleGenerateDemoData() {
    if (!requireUnlocked()) {
      return;
    }

    try {
      const settings = getCurrentSettingsFromForm();
      const demoEntries = createDemoEntries(settings.goal);
      const demoWorkouts = createDemoWorkouts(settings.goal, demoEntries);
      const demoTemplates = createDemoTemplates(demoWorkouts);
      const demoPrograms = createDemoTrainingPrograms(demoTemplates);
      const latestDemoWeight = demoEntries.length ? demoEntries[demoEntries.length - 1].weightKg : settings.currentWeightKg;
      state.data.settings = {
        ...settings,
        currentWeightKg: Number.isFinite(settings.currentWeightKg) ? settings.currentWeightKg : latestDemoWeight,
        heightCm: Number.isFinite(settings.heightCm) ? settings.heightCm : 178,
      };
      state.data.entries = demoEntries;
      state.data.workouts = demoWorkouts;
      state.data.templates = demoTemplates;
      state.data.trainingPrograms = demoPrograms;
      state.data.activeProgramId = demoPrograms.length ? demoPrograms[0].id : null;
      await persistVault();
      resetEntryForm();
      resetWorkoutForm();
      resetTemplateExerciseForm();
      resetTrainingProgramForm();
      state.selectedExerciseName = null;
      state.selectedProgramId = demoPrograms.length ? demoPrograms[0].id : null;
      elements.templateNameInput.value = "";
      elements.templateSelect.value = "";
      renderDashboard();
      showStatus("Wygenerowano przykładowe dane demo wraz z treningami, bilansem energii i planem tygodniowym.");
    } catch (error) {
      showStatus(error.message || "Nie udało się wygenerować danych demo.", true);
    }
  }
  function getSavedMealById(id) {
    return (state.data.savedMeals || []).find((meal) => meal.id === id) || null;
  }

  function renderSavedMealSelect() {
    if (!elements.savedMealSelect) {
      return;
    }
    const currentValue = elements.savedMealSelect.value;
    const meals = sortSavedMeals((state.data.savedMeals || []).map(normalizeSavedMeal).filter(Boolean));
    elements.savedMealSelect.replaceChildren();

    const placeholder = document.createElement("option");
    placeholder.value = "";
    placeholder.textContent = meals.length ? "Wybierz z zapisanych" : "Brak zapisanych posiłków";
    elements.savedMealSelect.appendChild(placeholder);

    meals.forEach((meal) => {
      const option = document.createElement("option");
      option.value = meal.id;
      option.textContent = `${meal.name} · ${round(meal.calories, 0)} kcal`;
      elements.savedMealSelect.appendChild(option);
    });

    if (meals.some((meal) => meal.id === currentValue)) {
      elements.savedMealSelect.value = currentValue;
    }
  }

  function fillMealForm(meal) {
    const normalized = normalizeSavedMeal(meal) || normalizeEntryMeal(meal);
    if (!normalized) {
      return;
    }
    elements.mealNameInput.value = normalized.name;
    elements.mealCaloriesInput.value = toInputValue(normalized.calories);
    elements.mealProteinInput.value = toInputValue(normalized.proteinG);
    elements.mealFatInput.value = toInputValue(normalized.fatG);
    elements.mealCarbsInput.value = toInputValue(normalized.carbsG);
    elements.mealPortionsInput.value = "1";
  }

  function clearMealForm() {
    if (elements.savedMealSelect) {
      elements.savedMealSelect.value = "";
    }
    elements.mealNameInput.value = "";
    elements.mealCaloriesInput.value = "";
    elements.mealProteinInput.value = "";
    elements.mealFatInput.value = "";
    elements.mealCarbsInput.value = "";
    elements.mealPortionsInput.value = "1";
  }

  function readMealFormBase() {
    const name = sanitizePlainText(elements.mealNameInput.value, 80);
    const calories = parseOptionalNumber(elements.mealCaloriesInput.value, { label: "Kalorie posiłku", min: 1, max: 5000 });
    if (!name) {
      throw new Error("Wpisz nazwę posiłku.");
    }
    if (!Number.isFinite(calories)) {
      throw new Error("Kalorie posiłku są wymagane.");
    }
    return {
      name,
      calories,
      proteinG: parseOptionalNumber(elements.mealProteinInput.value, { label: "Białko posiłku", min: 0, max: 250 }),
      fatG: parseOptionalNumber(elements.mealFatInput.value, { label: "Tłuszcze posiłku", min: 0, max: 200 }),
      carbsG: parseOptionalNumber(elements.mealCarbsInput.value, { label: "Węgle posiłku", min: 0, max: 400 }),
    };
  }

  function createEntryMealFromForm() {
    const base = readMealFormBase();
    const portions = parseOptionalNumber(elements.mealPortionsInput.value, { label: "Porcje", min: 0.1, max: 10 }) || 1;
    const sourceMealId = elements.savedMealSelect && getSavedMealById(elements.savedMealSelect.value) ? elements.savedMealSelect.value : "";
    const multiplyOptional = (value) => Number.isFinite(value) ? round(value * portions, 0) : null;
    return normalizeEntryMeal({
      id: createMealId("entry-meal"),
      sourceMealId,
      name: base.name,
      portions,
      calories: round(base.calories * portions, 0),
      proteinG: multiplyOptional(base.proteinG),
      fatG: multiplyOptional(base.fatG),
      carbsG: multiplyOptional(base.carbsG),
      createdAt: new Date().toISOString(),
    });
  }

  function syncEntryNutritionFromMealDrafts() {
    const totals = summarizeMeals(state.entryMealDrafts);
    if (!totals.count) {
      if (state.entryNutritionSyncedFromMeals) {
        elements.caloriesInput.value = "";
        elements.proteinInput.value = "";
        elements.fatInput.value = "";
        elements.carbsInput.value = "";
      }
      state.entryNutritionSyncedFromMeals = false;
      return;
    }
    elements.caloriesInput.value = toInputValue(totals.calories);
    elements.proteinInput.value = toInputValue(totals.proteinG);
    elements.fatInput.value = toInputValue(totals.fatG);
    elements.carbsInput.value = toInputValue(totals.carbsG);
    state.entryNutritionSyncedFromMeals = true;
  }

  function formatMealMacroSummary(meal) {
    const parts = [];
    if (Number.isFinite(meal.proteinG)) {
      parts.push(`B ${round(meal.proteinG, 0)}`);
    }
    if (Number.isFinite(meal.fatG)) {
      parts.push(`T ${round(meal.fatG, 0)}`);
    }
    if (Number.isFinite(meal.carbsG)) {
      parts.push(`W ${round(meal.carbsG, 0)}`);
    }
    return parts.length ? parts.join(" / ") : "opcjonalne";
  }

  function renderEntryMealsTable() {
    if (!elements.entryMealsBody || !elements.entryMealSummary) {
      return;
    }
    const meals = (state.entryMealDrafts || []).map(normalizeEntryMeal).filter(Boolean);
    const totals = summarizeMeals(meals);
    elements.entryMealsBody.replaceChildren();

    if (!state.unlocked) {
      elements.entryMealsBody.appendChild(createEmptyTableRow("Zaloguj się, aby korzystac z wlasnych posiłków.", 5));
      elements.entryMealSummary.textContent = "Zablokowane";
      elements.entryMealSummary.className = "status-pill status-locked";
      return;
    }

    elements.entryMealSummary.textContent = totals.count ? `${totals.count} pos. · ${round(totals.calories, 0)} kcal` : "Brak posiłków";
    elements.entryMealSummary.className = `status-pill ${totals.count ? "status-unlocked" : "status-locked"}`;

    if (!meals.length) {
      elements.entryMealsBody.appendChild(createEmptyTableRow("Brak posiłków w tym dniu. Dodaj posiłek albo wpisz dzienne kalorie ręcznie.", 5));
      return;
    }

    meals.forEach((meal) => {
      const row = document.createElement("tr");
      row.appendChild(createCell(meal.name));
      row.appendChild(createCell(`${round(meal.portions || 1, 1)}x`));
      row.appendChild(createCell(`${round(meal.calories, 0)} kcal`));
      row.appendChild(createCell(formatMealMacroSummary(meal)));

      const actionCell = document.createElement("td");
      const actionWrap = document.createElement("div");
      actionWrap.className = "table-actions";

      const saveButton = document.createElement("button");
      saveButton.type = "button";
      saveButton.className = "edit-button";
      saveButton.setAttribute("data-entry-meal-id", meal.id);
      saveButton.setAttribute("data-entry-meal-action", "save");
      saveButton.textContent = "Zapisz";

      const removeButton = document.createElement("button");
      removeButton.type = "button";
      removeButton.className = "delete-button";
      removeButton.setAttribute("data-entry-meal-id", meal.id);
      removeButton.setAttribute("data-entry-meal-action", "remove");
      removeButton.textContent = "Usuń";

      actionWrap.append(saveButton, removeButton);
      actionCell.appendChild(actionWrap);
      row.appendChild(actionCell);
      elements.entryMealsBody.appendChild(row);
    });
  }

  function handleSavedMealSelectChange() {
    const meal = getSavedMealById(elements.savedMealSelect.value);
    if (meal) {
      fillMealForm(meal);
    }
  }

  function handleAddMealToEntry() {
    try {
      const meal = createEntryMealFromForm();
      state.entryMealDrafts = (state.entryMealDrafts || []).concat(meal).slice(0, MAX_ENTRY_MEALS);
      syncEntryNutritionFromMealDrafts();
      renderEntryMealsTable();
      showStatus(`Dodano posiłek "${meal.name}" do dnia.`);
    } catch (error) {
      showStatus(error.message || "Nie udało się dodać posiłku.", true);
    }
  }

  async function saveMealTemplate(mealLike, statusMessage) {
    const normalized = normalizeSavedMeal(mealLike);
    if (!normalized) {
      throw new Error("Do zapisania stalego posiłku potrzebna jest nazwa i kalorie.");
    }
    if (!Array.isArray(state.data.savedMeals)) {
      state.data.savedMeals = [];
    }
    const selectedId = elements.savedMealSelect ? elements.savedMealSelect.value : "";
    const existingIndex = state.data.savedMeals.findIndex((meal) => meal.id === selectedId || meal.name.toLowerCase() === normalized.name.toLowerCase());
    const finalMeal = {
      ...normalized,
      id: existingIndex >= 0 ? state.data.savedMeals[existingIndex].id : normalized.id,
      createdAt: existingIndex >= 0 ? state.data.savedMeals[existingIndex].createdAt : normalized.createdAt,
      updatedAt: new Date().toISOString(),
    };
    if (existingIndex >= 0) {
      state.data.savedMeals[existingIndex] = finalMeal;
    } else {
      state.data.savedMeals.push(finalMeal);
    }
    state.data.savedMeals = sortSavedMeals(state.data.savedMeals.map(normalizeSavedMeal).filter(Boolean)).slice(0, MAX_SAVED_MEALS);
    await persistVault();
    renderSavedMealSelect();
    elements.savedMealSelect.value = finalMeal.id;
    showStatus(statusMessage || `Zapisano posiłek "${finalMeal.name}".`);
  }

  async function handleSaveMealTemplate() {
    try {
      const base = readMealFormBase();
      await saveMealTemplate({
        id: elements.savedMealSelect ? elements.savedMealSelect.value : "",
        ...base,
        createdAt: new Date().toISOString(),
      });
    } catch (error) {
      showStatus(error.message || "Nie udało się zapisać posiłku.", true);
    }
  }

  async function handleDeleteSavedMeal() {
    const meal = getSavedMealById(elements.savedMealSelect.value);
    if (!meal) {
      showStatus("Najpierw wybierz zapisany posiłek do usunięcia.", true);
      return;
    }
    if (!window.confirm(`Usunąć zapisany posiłek "${meal.name}"? Wpisy dzienne zostaną zachowane.`)) {
      return;
    }
    state.data.savedMeals = (state.data.savedMeals || []).filter((item) => item.id !== meal.id);
    await persistVault();
    clearMealForm();
    renderSavedMealSelect();
    showStatus(`Usunięto zapisany posiłek "${meal.name}".`);
  }

  async function handleEntryMealTableAction(event) {
    const button = event.target.closest("button[data-entry-meal-id][data-entry-meal-action]");
    if (!button || !state.unlocked) {
      return;
    }
    const mealId = button.getAttribute("data-entry-meal-id");
    const action = button.getAttribute("data-entry-meal-action");
    const meal = (state.entryMealDrafts || []).find((item) => item.id === mealId);
    if (!meal) {
      return;
    }
    if (action === "remove") {
      state.entryMealDrafts = state.entryMealDrafts.filter((item) => item.id !== mealId);
      syncEntryNutritionFromMealDrafts();
      renderEntryMealsTable();
      showStatus(`Usunięto posiłek "${meal.name}" z dnia.`);
      return;
    }
    if (action === "save") {
      const portions = Number.isFinite(meal.portions) && meal.portions > 0 ? meal.portions : 1;
      try {
        if (elements.savedMealSelect) {
          elements.savedMealSelect.value = meal.sourceMealId || "";
        }
        await saveMealTemplate({
          name: meal.name,
          calories: round(meal.calories / portions, 0),
          proteinG: Number.isFinite(meal.proteinG) ? round(meal.proteinG / portions, 0) : null,
          fatG: Number.isFinite(meal.fatG) ? round(meal.fatG / portions, 0) : null,
          carbsG: Number.isFinite(meal.carbsG) ? round(meal.carbsG / portions, 0) : null,
          createdAt: new Date().toISOString(),
        }, `Zapisano "${meal.name}" jako stały posiłek.`);
      } catch (error) {
        showStatus(error.message || "Nie udało się zapisać posiłku.", true);
      }
    }
  }

  async function handleEntrySubmit(event) {
    event.preventDefault();
    if (!requireUnlocked()) {
      return;
    }

    try {
      const entry = buildEntryFromForm();
      const duplicateByDate = state.data.entries.find((item) => item.date === entry.date && item.id !== entry.id);
      if (duplicateByDate) {
        throw new Error("Dla tej daty istnieje już wpis. Przejdź do jego edycji albo wybierz inną datę.");
      }

      const existingIndex = state.data.entries.findIndex((item) => item.id === entry.id);
      if (existingIndex >= 0) {
        state.data.entries[existingIndex] = entry;
      } else {
        state.data.entries.push(entry);
      }

      state.data.entries = sortEntries(state.data.entries).slice(-MAX_ENTRIES);
      syncCurrentWeightFromEntries();
      await persistVault();
      renderDashboard();
      resetEntryForm();
      showStatus(existingIndex >= 0 ? "Zapisano zmiany wpisu." : "Dodano nowy wpis do analizy.");
    } catch (error) {
      showStatus(error.message || "Nie udało się zapisać wpisu.", true);
    }
  }

  function handleEntryTableAction(event) {
    const actionButton = event.target.closest("button[data-entry-id][data-entry-action]");
    if (!actionButton || !state.unlocked) {
      return;
    }

    const entryId = actionButton.getAttribute("data-entry-id");
    const entry = state.data.entries.find((item) => item.id === entryId);
    if (!entry) {
      return;
    }

    const action = actionButton.getAttribute("data-entry-action");
    if (action === "edit") {
      startEditingEntry(entry);
      return;
    }

    if (action === "delete") {
      deleteEntry(entry);
    }
  }

  async function deleteEntry(entry) {
    if (!window.confirm("Usuńąć wybrany wpis?")) {
      return;
    }

    try {
      state.data.entries = state.data.entries.filter((item) => item.id !== entry.id);
      if (state.editingEntryId === entry.id) {
        resetEntryForm();
      }
      syncCurrentWeightFromEntries();
      await persistVault();
      renderDashboard();
      showStatus(`Usunięto wpis z dnia ${formatDisplayDate(entry.date)}.`);
    } catch (error) {
      showStatus(error.message || "Nie udało się usuńąć wpisu.", true);
    }
  }

  function startEditingEntry(entry) {
    state.editingEntryId = entry.id;
    elements.dateInput.value = entry.date;
    elements.weightInput.value = toInputValue(entry.weightKg);
    elements.bodyFatInput.value = toInputValue(entry.bodyFatPct);
    elements.caloriesInput.value = toInputValue(entry.calories);
    elements.proteinInput.value = toInputValue(entry.proteinG);
    elements.fatInput.value = toInputValue(entry.fatG);
    elements.carbsInput.value = toInputValue(entry.carbsG);
    state.entryMealDrafts = Array.isArray(entry.meals) ? entry.meals.map(normalizeEntryMeal).filter(Boolean) : [];
    state.entryNutritionSyncedFromMeals = Boolean(state.entryMealDrafts.length);
    renderEntryMealsTable();
    elements.waistInput.value = toInputValue(entry.waistCm);
    elements.hipsInput.value = toInputValue(entry.hipsCm);
    elements.chestInput.value = toInputValue(entry.chestCm);
    elements.armInput.value = toInputValue(entry.armCm);
    elements.thighInput.value = toInputValue(entry.thighCm);
    elements.stepsInput.value = toInputValue(entry.steps);
    elements.sleepInput.value = toInputValue(entry.sleepHours);
    elements.restingHrInput.value = toInputValue(entry.restingHr);
    elements.notesInput.value = entry.notes || "";
    state.entryPhotoDrafts = Array.isArray(entry.progressPhotos)
      ? entry.progressPhotos.map((photo) => normalizeProgressPhoto(photo)).filter(Boolean)
      : [];
    if (elements.entryPhotoInput) {
      elements.entryPhotoInput.value = "";
    }
    renderEntryPhotoDrafts();
    syncEntryFormMode();
    elements.entryForm.scrollIntoView({ behavior: "smooth", block: "start" });
    showStatus(`Wczytano wpis z dnia ${formatDisplayDate(entry.date)} do edycji.`);
  }
  function buildEntryFromForm() {
    const date = elements.dateInput.value;
    if (!date) {
      throw new Error("Wybierz datę wpisu.");
    }

    const entry = {
      id: state.editingEntryId || (window.crypto.randomUUID ? window.crypto.randomUUID() : `entry-${Date.now()}`),
      date,
      weightKg: parseOptionalNumber(elements.weightInput.value, { label: "Masa ciała", min: 25, max: 400 }),
      bodyFatPct: parseOptionalNumber(elements.bodyFatInput.value, { label: "Tkanka tłuszczowa", min: 3, max: 70 }),
      calories: parseOptionalNumber(elements.caloriesInput.value, { label: "Kalorie", min: 0, max: 12000 }),
      proteinG: parseOptionalNumber(elements.proteinInput.value, { label: "Białko", min: 0, max: 400 }),
      fatG: parseOptionalNumber(elements.fatInput.value, { label: "Tłuszcze", min: 0, max: 250 }),
      carbsG: parseOptionalNumber(elements.carbsInput.value, { label: "Węgle", min: 0, max: 1000 }),
      waistCm: parseOptionalNumber(elements.waistInput.value, { label: "Pas", min: 40, max: 200 }),
      hipsCm: parseOptionalNumber(elements.hipsInput.value, { label: "Biodra", min: 50, max: 220 }),
      chestCm: parseOptionalNumber(elements.chestInput.value, { label: "Klatka", min: 50, max: 220 }),
      armCm: parseOptionalNumber(elements.armInput.value, { label: "Ramię", min: 15, max: 80 }),
      thighCm: parseOptionalNumber(elements.thighInput.value, { label: "Udo", min: 25, max: 120 }),
      steps: parseOptionalNumber(elements.stepsInput.value, { label: "Kroki", min: 0, max: 50000 }),
      sleepHours: parseOptionalNumber(elements.sleepInput.value, { label: "Sen", min: 0, max: 24 }),
      restingHr: parseOptionalNumber(elements.restingHrInput.value, { label: "Tętno spoczynkowe", min: 25, max: 220 }),
      meals: (state.entryMealDrafts || []).map(normalizeEntryMeal).filter(Boolean).slice(0, MAX_ENTRY_MEALS),
      progressPhotos: state.entryPhotoDrafts.slice(0, MAX_ENTRY_PROGRESS_PHOTOS),
      notes: sanitizePlainText(elements.notesInput.value, 180),
    };

    const mealTotals = summarizeMeals(entry.meals);
    if (mealTotals.count) {
      entry.calories = mealTotals.calories;
      entry.proteinG = mealTotals.proteinG;
      entry.fatG = mealTotals.fatG;
      entry.carbsG = mealTotals.carbsG;
    }

    const hasAtLeastOneMetric = [
      entry.weightKg,
      entry.bodyFatPct,
      entry.calories,
      entry.proteinG,
      entry.fatG,
      entry.carbsG,
      entry.waistCm,
      entry.hipsCm,
      entry.chestCm,
      entry.armCm,
      entry.thighCm,
      entry.steps,
      entry.sleepHours,
      entry.restingHr,
      mealTotals.count ? entry.calories : null,
    ].some((value) => Number.isFinite(value));

    if (!hasAtLeastOneMetric && !entry.notes && !entry.progressPhotos.length) {
      throw new Error("Dodaj co najmniej jedną metrykę, zdjęcie progresu albo krótką notatkę.");
    }

    return entry;
  }
  function renderDashboard() {
    populateSettingsForm();
    renderAvatarHub();
    renderLeaguePanel();
    syncCommandDeckOrder();
    syncEntryFormMode();
    syncWorkoutFormMode();
    applyActiveTab();
    const analytics = computeAnalytics(state.data);
    renderSavedMealSelect();
    renderEntryMealsTable();
    renderMainDashboard(analytics);
    renderOnboarding(analytics);
    renderCalculatorPanel(analytics);
    renderMetricCards(analytics);
    renderLocalAiModel(analytics);
    renderCoachPlan(analytics);
    renderProgressCards(analytics);
    renderPreparationPlan(analytics);
    renderCustomGoalTable(analytics);
    renderWeeklyPlan(analytics);
    renderRiskAlerts(analytics);
    renderWeeklyReport(analytics);
    renderInsights(analytics);
    renderEntriesTable(analytics.entrySnapshots);
    renderPhysiquePanel(analytics.physiqueSummary);
    populateAiPreparationGoalSelect(analytics);
    renderAiExercisePicker();
    populateTemplateSelect();
    renderTrainingProgramPlanner();
    renderTemplateExecutionPanel(getSelectedTemplate());
    renderTemplateExerciseEditor(getSelectedTemplate());
    renderTemplateTable(state.data.templates);
    renderSessionTable(analytics.sessionSummaries);
    renderWorkoutTable(analytics.workouts);
    renderPostWorkoutCoach(analytics);
    renderExerciseSummary(analytics.exerciseSummaries);
    renderExerciseHistory(analytics.exerciseHistory);
    renderCharts(analytics);
    applyActiveTab();
  }

  function renderAvatarHub() {
    const avatar = normalizeAvatarProfile(state.data.avatar);
    const unlocked = Boolean(state.unlocked);

    if (elements.heroAvatar) {
      elements.heroAvatar.classList.remove("is-hidden");
      elements.heroAvatar.classList.toggle("hero-avatar-locked", !unlocked);
    }

    if (!elements.avatarPreviewName) {
      return;
    }

    elements.heroAvatarName.textContent = avatar.nickname;
    elements.avatarPreviewName.textContent = avatar.nickname;
    if (elements.heroAvatarStage) {
      elements.heroAvatarStage.dataset.avatarSpeciesCurrent = avatar.species;
      elements.heroAvatarStage.dataset.avatarMoodCurrent = avatar.mood;
      elements.heroAvatarStage.dataset.avatarEffectCurrent = avatar.effect;
    }
    if (elements.avatarPreviewStage) {
      elements.avatarPreviewStage.dataset.avatarSpeciesCurrent = avatar.species;
      elements.avatarPreviewStage.dataset.avatarMoodCurrent = avatar.mood;
      elements.avatarPreviewStage.dataset.avatarEffectCurrent = avatar.effect;
    }
    if (elements.heroAvatarImage) {
      elements.heroAvatarImage.src = resolveAvatarArtSource(avatar);
      elements.heroAvatarImage.alt = formatAvatarArtAlt(avatar);
    }
    if (elements.avatarPreviewImage) {
      elements.avatarPreviewImage.src = resolveAvatarArtSource(avatar);
      elements.avatarPreviewImage.alt = formatAvatarArtAlt(avatar);
    }
    elements.avatarPreviewRace.textContent = formatAvatarSpeciesLabel(avatar.species);
    elements.avatarPreviewLoadout.textContent = formatAvatarLoadoutLabel(avatar);
    elements.avatarStatus.textContent = unlocked ? "Avatar aktywny" : "Tryb startowy";
    elements.avatarStatus.className = `status-pill ${unlocked ? "status-unlocked" : "status-locked"}`;
    elements.avatarNicknameInput.value = avatar.nickname;
    elements.avatarSpeciesCards.forEach((card) => {
      const species = card.getAttribute("data-avatar-species-card");
      card.classList.toggle("avatar-option-card-active", species === avatar.species);
    });
    elements.avatarSpeciesChips.forEach((chip) => {
      const species = chip.getAttribute("data-avatar-species-chip");
      const isActive = species === avatar.species;
      chip.classList.toggle("avatar-chip-active", isActive);
      chip.textContent = isActive ? "Aktywna" : "Dostępna";
    });
    elements.avatarSpeciesButtons.forEach((button) => {
      const species = button.getAttribute("data-avatar-species");
      const isActive = species === avatar.species;
      button.disabled = !unlocked || isActive;
      button.textContent = isActive
        ? "Rasa aktywna"
        : `Wybierz ${formatAvatarSpeciesLabel(species)}`;
    });
    elements.avatarMoodCards.forEach((card) => {
      const mood = card.getAttribute("data-avatar-mood-card");
      card.classList.toggle("avatar-option-card-active", mood === avatar.mood);
    });
    elements.avatarMoodChips.forEach((chip) => {
      const mood = chip.getAttribute("data-avatar-mood-chip");
      const isActive = mood === avatar.mood;
      chip.classList.toggle("avatar-chip-active", isActive);
      chip.textContent = isActive ? "Aktywny" : "Dostępny";
    });
    elements.avatarMoodButtons.forEach((button) => {
      const mood = button.getAttribute("data-avatar-mood");
      const isActive = mood === avatar.mood;
      button.disabled = !unlocked || isActive;
      button.textContent = isActive
        ? "Tryb aktywny"
        : `Wybierz ${formatAvatarMoodLabel(mood).toLowerCase()}`;
    });
    elements.avatarEffectCards.forEach((card) => {
      const effect = card.getAttribute("data-avatar-effect-card");
      card.classList.toggle("avatar-option-card-active", effect === avatar.effect);
    });
    elements.avatarEffectChips.forEach((chip) => {
      const effect = chip.getAttribute("data-avatar-effect-chip");
      const isActive = effect === avatar.effect;
      chip.classList.toggle("avatar-chip-active", isActive);
      chip.textContent = isActive ? "Aktywny" : "Dostępny";
    });
    elements.avatarEffectButtons.forEach((button) => {
      const effect = button.getAttribute("data-avatar-effect");
      const isActive = effect === avatar.effect;
      button.disabled = !unlocked || isActive;
      button.textContent = isActive
        ? "Efekt aktywny"
        : `Wybierz ${formatAvatarEffectLabel(effect).toLowerCase()}`;
    });
    applyAvatarStoreTab();
  }

  function createMetricCardElement(card) {
    const article = document.createElement("article");
    article.className = `metric-card ${card.tone ? `metric-card-${card.tone}` : ""}`.trim();

    const label = document.createElement("span");
    label.className = "metric-label";
    label.textContent = card.label;

    const value = document.createElement("p");
    value.className = `metric-value ${card.tone ? `metric-tone-${card.tone}` : ""}`.trim();
    value.textContent = card.value;

    const support = document.createElement("p");
    support.className = "metric-support";
    support.textContent = card.support;

    article.append(label, value, support);
    return article;
  }

  function renderMetricCardCollection(container, cards, emptyMessage) {
    if (!container) {
      return;
    }

    container.replaceChildren();
    if (!cards || !cards.length) {
      container.appendChild(createMutedParagraph(emptyMessage));
      return;
    }

    cards.forEach((card) => container.appendChild(createMetricCardElement(card)));
  }

  function renderTextList(container, items, emptyMessage) {
    if (!container) {
      return;
    }

    container.replaceChildren();
    const listItems = Array.isArray(items) ? items.filter(Boolean) : [];
    if (!listItems.length) {
      const item = document.createElement("li");
      item.textContent = emptyMessage;
      container.appendChild(item);
      return;
    }

    listItems.forEach((message) => {
      const item = document.createElement("li");
      if (message && typeof message === "object") {
        item.textContent = message.text || "";
        if (message.tone) {
          item.classList.add(`list-tone-${message.tone}`);
        }
      } else {
        item.textContent = message;
      }
      container.appendChild(item);
    });
  }

  function renderHabitWeekdayPicker() {
    if (!elements.habitWeekdayPicker) {
      return;
    }

    elements.habitWeekdayPicker.replaceChildren();
    WEEKDAY_OPTIONS.forEach((day) => {
      const label = document.createElement("label");
      label.className = "weekday-chip";

      const input = document.createElement("input");
      input.type = "checkbox";
      input.value = String(day.value);
      input.checked = true;

      const text = document.createElement("span");
      text.textContent = day.shortLabel;

      label.append(input, text);
      elements.habitWeekdayPicker.appendChild(label);
    });
  }

  function setHabitWeekdayPickerValues(weekdays) {
    if (!elements.habitWeekdayPicker) {
      return;
    }
    const selected = new Set((Array.isArray(weekdays) && weekdays.length ? weekdays : WEEKDAY_OPTIONS.map((day) => day.value))
      .map((value) => String(value)));
    elements.habitWeekdayPicker.querySelectorAll("input").forEach((input) => {
      input.checked = selected.has(input.value);
    });
  }

  function resetHabitEditorDraft() {
    state.editingHabitId = null;
    if (elements.habitNameInput) {
      elements.habitNameInput.value = "";
    }
    if (elements.habitColorInput) {
      elements.habitColorInput.value = "ruby";
    }
    setHabitWeekdayPickerValues(WEEKDAY_OPTIONS.map((day) => day.value));
    if (elements.saveHabitButton) {
      elements.saveHabitButton.textContent = "Dodaj checkbox";
    }
    if (elements.cancelHabitEditButton) {
      elements.cancelHabitEditButton.textContent = "Zamknij edycję";
    }
  }

  function fillHabitEditorForm(habit) {
    if (!habit) {
      resetHabitEditorDraft();
      return;
    }
    state.editingHabitId = habit.id;
    elements.habitNameInput.value = habit.name;
    if (elements.habitColorInput) {
      elements.habitColorInput.value = normalizeHabitColor(habit.color);
    }
    setHabitWeekdayPickerValues(habit.weekdays);
    if (elements.saveHabitButton) {
      elements.saveHabitButton.textContent = "Zapisz zmiany";
    }
    if (elements.cancelHabitEditButton) {
      elements.cancelHabitEditButton.textContent = "Anuluj edycję";
    }
  }

  function toggleHabitEditor(forceState) {
    if (!elements.habitEditorForm) {
      return;
    }

    const shouldShow = typeof forceState === "boolean"
      ? forceState
      : elements.habitEditorForm.classList.contains("is-hidden");
    elements.habitEditorForm.classList.toggle("is-hidden", !shouldShow);
    elements.toggleHabitEditorButton.textContent = shouldShow ? "Zamknij" : "Edytuj";
    if (!shouldShow) {
      resetHabitEditorDraft();
      if (state.unlocked && elements.habitManagementList) {
        renderHabitManagementList();
      }
    }
    if (shouldShow) {
      elements.habitNameInput.focus();
    }
  }

  async function handleHabitSubmit(event) {
    event.preventDefault();
    if (!requireUnlocked()) {
      return;
    }

    try {
      const name = sanitizePlainText(elements.habitNameInput.value, 80);
      if (!name) {
        throw new Error("Wpisz nazwę checkboxa, np. Pull day albo 10k kroków.");
      }

      const weekdays = Array.from(elements.habitWeekdayPicker.querySelectorAll("input:checked"))
        .map((input) => Number(input.value))
        .filter((value) => value >= 1 && value <= 7);

      if (!weekdays.length) {
        throw new Error("Zaznacz co najmniej jeden dzień tygodnia dla tego nawyku.");
      }

      const color = normalizeHabitColor(elements.habitColorInput ? elements.habitColorInput.value : "ruby");
      state.data = normalizeData(state.data);
      const editingHabitId = state.editingHabitId;
      const existingIndex = editingHabitId
        ? state.data.habits.findIndex((habit) => habit.id === editingHabitId)
        : -1;
      const existingHabit = existingIndex >= 0 ? state.data.habits[existingIndex] : null;
      const normalizedHabit = normalizeHabit({
        id: existingHabit ? existingHabit.id : createHabitId(),
        name,
        weekdays,
        color,
        createdAt: existingHabit && existingHabit.createdAt ? existingHabit.createdAt : new Date().toISOString(),
      });

      if (existingIndex >= 0) {
        state.data.habits[existingIndex] = normalizedHabit;
      } else {
        state.data.habits.push(normalizedHabit);
      }
      state.data.habits = state.data.habits.filter(Boolean).slice(-80);
      resetHabitEditorDraft();
      await persistVault();
      renderDashboard();
      showStatus(existingIndex >= 0 ? "Zapisano zmiany checkboxa dnia." : "Dodano nowy punkt do dzisiejszego systemu nawyków.");
    } catch (error) {
      showStatus(error.message || "Nie udało się zapisać checkboxa.", true);
    }
  }

  async function handleHabitChecklistChange(event) {
    const checkbox = event.target;
    if (!checkbox || checkbox.type !== "checkbox" || !checkbox.dataset.habitId) {
      return;
    }
    if (!requireUnlocked()) {
      checkbox.checked = !checkbox.checked;
      return;
    }

    try {
      const today = toISODate(new Date());
      state.data = normalizeData(state.data);
      setHabitManualCompletion(today, checkbox.dataset.habitId, checkbox.checked);
      await persistVault();
      renderDashboard();
      showStatus(checkbox.checked ? "Odhaczono punkt dnia." : "Cofnięto ręczne odhaczenie punktu dnia.");
    } catch (error) {
      showStatus(error.message || "Nie udało się zapisać checklisty.", true);
    }
  }

  async function handleHabitManagementAction(event) {
    const editButton = event.target.closest("[data-edit-habit]");
    const deleteButton = event.target.closest("[data-delete-habit]");
    if (!editButton && !deleteButton) {
      return;
    }
    if (!requireUnlocked()) {
      return;
    }

    try {
      state.data = normalizeData(state.data);
      if (editButton) {
        const habitId = editButton.getAttribute("data-edit-habit");
        const habit = state.data.habits.find((item) => item.id === habitId);
        if (!habit) {
          throw new Error("Nie znaleziono checkboxa do edycji.");
        }
        fillHabitEditorForm(habit);
        toggleHabitEditor(true);
        renderHabitManagementList();
        showStatus("Wczytano checkbox do edycji. Możesz zmienić nazwę, kolor albo dni tygodnia.");
        return;
      }

      const habitId = deleteButton.getAttribute("data-delete-habit");
      state.data.habits = state.data.habits.filter((habit) => habit.id !== habitId);
      Object.keys(state.data.habitCompletions || {}).forEach((date) => {
        delete state.data.habitCompletions[date][habitId];
        if (!Object.keys(state.data.habitCompletions[date]).length) {
          delete state.data.habitCompletions[date];
        }
      });
      if (state.editingHabitId === habitId) {
        resetHabitEditorDraft();
      }
      await persistVault();
      renderDashboard();
      showStatus("Usunięto checkbox z grafiku tygodnia.");
    } catch (error) {
      showStatus(error.message || "Nie udało się usunąć checkboxa.", true);
    }
  }

  function setHabitManualCompletion(date, habitId, done) {
    if (!state.data.habitCompletions || typeof state.data.habitCompletions !== "object") {
      state.data.habitCompletions = {};
    }
    if (!state.data.habitCompletions[date]) {
      state.data.habitCompletions[date] = {};
    }

    if (done) {
      state.data.habitCompletions[date][habitId] = true;
      return;
    }

    delete state.data.habitCompletions[date][habitId];
    if (!Object.keys(state.data.habitCompletions[date]).length) {
      delete state.data.habitCompletions[date];
    }
  }

  function summarizeTodayHabits(data, context) {
    const normalized = normalizeData(data);
    const today = context.today || toISODate(new Date());
    const weekday = getIsoWeekday(today);
    const scheduled = normalized.habits.filter((habit) => habit.weekdays.includes(weekday));
    const items = scheduled.map((habit) => buildHabitDisplayModel(habit, normalized, context));
    const completed = items.filter((item) => item.done);
    const pending = items.filter((item) => !item.done);

    return {
      date: today,
      scheduled,
      items,
      completed,
      pending,
      total: items.length,
      completedCount: completed.length,
      allDone: items.length > 0 && completed.length === items.length,
    };
  }

  function buildHabitDisplayModel(habit, data, context) {
    const manualDone = Boolean(data.habitCompletions && data.habitCompletions[context.today] && data.habitCompletions[context.today][habit.id]);
    const auto = buildHabitAutoStatus(habit, context);
    const done = manualDone || auto.done;
    return {
      habit,
      done,
      manualDone,
      autoDone: auto.done,
      reason: manualDone && !auto.done ? "Odhaczone ręcznie." : auto.reason,
    };
  }

  function buildHabitAutoStatus(habit, context) {
    const key = normalizeExerciseSearchKey(habit.name, 120);
    const steps = Number.isFinite(context.todaySteps) ? context.todaySteps : NaN;
    const sleep = Number.isFinite(context.todaySleep) ? context.todaySleep : NaN;
    const proteinGap = Number.isFinite(context.proteinGap) ? context.proteinGap : NaN;
    const energyBalance = Number.isFinite(context.energyBalance) ? context.energyBalance : NaN;

    if (/(krok|steps|spacer|marsz)/.test(key)) {
      const target = parseHabitNumberTarget(key, 10000);
      return {
        done: Number.isFinite(steps) && steps >= target,
        reason: Number.isFinite(steps)
          ? `${round(steps, 0)} / ${target} kroków z dziennika.`
          : "Brakuje kroków w dzisiejszym dzienniku.",
      };
    }

    if (/(trening|silow|sila|push|pull|legs|gora|dol|klat|plec|barki|plyw|pływ|rower|bieg|cardio|crossfit|wydoln)/.test(key)) {
      const matchingWorkout = hasWorkoutMatchingHabit(key, context.todayWorkouts, context.activeProgramPreview);
      return {
        done: matchingWorkout,
        reason: matchingWorkout
          ? "Wykryto pasujący trening zapisany dzisiaj."
          : "Nie ma jeszcze pasującego treningu w zakładce Trening.",
      };
    }

    if (/(bial|biał|protein)/.test(key)) {
      return {
        done: Number.isFinite(proteinGap) && proteinGap <= 0,
        reason: Number.isFinite(proteinGap)
          ? proteinGap <= 0
            ? "Cel białka jest domknięty."
            : `Do celu białka brakuje około ${round(proteinGap, 0)} g.`
          : "Brakuje danych o białku w dzienniku.",
      };
    }

    if (/(sen|sleep|regener)/.test(key)) {
      const target = parseHabitNumberTarget(key, 7);
      return {
        done: Number.isFinite(sleep) && sleep >= target,
        reason: Number.isFinite(sleep)
          ? `${round(sleep, 1)} / ${target} h snu.`
          : "Brakuje snu w dzisiejszym dzienniku.",
      };
    }

    if (/(kcal|kalor|deficyt|nadwyz|nadwyż|bilans)/.test(key)) {
      const done = Number.isFinite(energyBalance) && Math.abs(energyBalance) <= 250;
      return {
        done,
        reason: Number.isFinite(energyBalance)
          ? done
            ? `Bilans dnia jest blisko celu (${formatEnergyBalance(energyBalance)}).`
            : `Bilans dnia wymaga decyzji (${formatEnergyBalance(energyBalance)}).`
          : "Brakuje kalorii w dzisiejszym dzienniku.",
      };
    }

    return {
      done: false,
      reason: "Ten punkt wymaga ręcznego odhaczenia.",
    };
  }

  function parseHabitNumberTarget(key, fallback) {
    const compact = key.replace(/\s+/g, "");
    const thousands = compact.match(/(\d+(?:[.,]\d+)?)k/);
    if (thousands) {
      return Math.max(1, Math.round(Number(thousands[1].replace(",", ".")) * 1000));
    }
    const plain = compact.match(/(\d{1,5})/);
    return plain ? Math.max(1, Math.round(Number(plain[1]))) : fallback;
  }

  function hasWorkoutMatchingHabit(key, workouts, activeProgramPreview) {
    const todayWorkouts = Array.isArray(workouts) ? workouts : [];
    if (!todayWorkouts.length) {
      return false;
    }
    const plannedUnitKey = activeProgramPreview && activeProgramPreview.scheduleEntry
      ? normalizeExerciseSearchKey(activeProgramPreview.scheduleEntry.unitName, 120)
      : "";

    if (/(push|pull|legs|gora|dol)/.test(key) && plannedUnitKey && key.split(" ").some((token) => token.length >= 3 && plannedUnitKey.includes(token))) {
      return true;
    }

    if (/trening|silow|sila/.test(key)) {
      return todayWorkouts.some((workout) => workout.loadMode !== "cardio" || workout.activityProfile === "strength");
    }
    if (/cardio|wydoln|crossfit/.test(key)) {
      return todayWorkouts.some((workout) => workout.loadMode === "cardio" || workout.activityProfile === "crossfit" || workout.activityProfile === "endurance");
    }
    if (/plyw|pływ/.test(key)) {
      return todayWorkouts.some((workout) => normalizeExerciseSearchKey(workout.exerciseName, 120).includes("plyw"));
    }
    if (/rower/.test(key)) {
      return todayWorkouts.some((workout) => normalizeExerciseSearchKey(workout.exerciseName, 120).includes("rower") || workout.activityProfile === "cycling");
    }
    if (/bieg/.test(key)) {
      return todayWorkouts.some((workout) => normalizeExerciseSearchKey(workout.exerciseName, 120).includes("bieg") || RUNNING_ATHLETIC_PROFILES.has(workout.activityProfile));
    }

    return todayWorkouts.some((workout) => {
      const exerciseKey = normalizeExerciseSearchKey(workout.exerciseName, 120);
      return key.split(" ").some((token) => token.length >= 4 && exerciseKey.includes(token));
    });
  }

  function buildTodayDecisionCard(context) {
    const hasPlannedTraining = Boolean(context.hasPlannedTraining || (context.activeProgramPreview && context.activeProgramPreview.scheduleEntry));
    const priorityMode = getTodayPriorityMode(context);
    const modeConfig = getPriorityModeConfig(priorityMode);

    if (!context.entryDone) {
      return {
        label: "Decyzja AI",
        value: "Uzupełnij dziennik",
        support: "Najpierw wpisz dzisiejsze kalorie, makro, kroki i sen, bo bez tego decyzja dnia będzie tylko zgadywaniem.",
        tone: "warn",
      };
    }

    if (Number.isFinite(context.todaySleep) && context.todaySleep < 6 && hasPlannedTraining && !context.trainingDone) {
      return {
        label: "Decyzja AI",
        value: "Deload / technika",
        support: "Sen jest niski, więc zrób zaplanowany trening lżej, bez gonienia rekordów i z większym zapasem RPE.",
        tone: "risk",
      };
    }

    if (Number.isFinite(context.energyBalance) && context.energyBalance > 350 && Number.isFinite(context.todaySteps) && context.todaySteps < context.stepGoal) {
      return {
        label: "Decyzja AI",
        value: priorityMode === "cut" ? "Spacer + obetnij kcal" : "Spacer",
        support: `Bilans jest dodatni (${formatEnergyBalance(context.energyBalance)}), a kroki nie są domknięte, więc spacer ma dziś największy zwrot.`,
        tone: priorityMode === "cut" ? "risk" : "warn",
      };
    }

    if ((priorityMode === "mass" || priorityMode === "strength" || priorityMode === "conditioning") && Number.isFinite(context.energyBalance) && context.energyBalance < -300) {
      return {
        label: "Decyzja AI",
        value: "Podbij kcal",
        support: "Jesteś wyraźnie poniżej bilansu, więc dorzuć posiłek, szczególnie jeśli zależy Ci na siłę i regeneracji.",
        tone: "warn",
      };
    }

    if (priorityMode === "cut" && Number.isFinite(context.energyBalance) && context.energyBalance > 300) {
      return {
        label: "Decyzja AI",
        value: "Obetnij kcal",
        support: `Redukcja lubi konsekwencję: bilans jest dziś dodatni (${formatEnergyBalance(context.energyBalance)}), więc nie dokładaj już kalorii.`,
        tone: "risk",
      };
    }

    if (Number.isFinite(context.proteinGap) && context.proteinGap > 30) {
      return {
        label: "Decyzja AI",
        value: "Domknij białko",
        support: `Brakuje około ${round(context.proteinGap, 0)} g białka, więc to najprostsza rzecz do poprawy przed końcem dnia.`,
        tone: "warn",
      };
    }

    if (hasPlannedTraining && !context.trainingDone) {
      return {
        label: "Decyzja AI",
        value: priorityMode === "health" ? "Lekki dzień" : "Trenuj",
        support: `Na dziś wypada ${context.plannedUnit || modeConfig.label}. Tryb ${modeConfig.label.toLowerCase()} sugeruje: ${modeConfig.trainingText}.`,
        tone: "warn",
      };
    }

    if (!hasPlannedTraining && context.trainingDone && context.todayHasCardio) {
      return {
        label: "Decyzja AI",
        value: "Dzień cardio",
        support: "Dzisiejsza aktywność wydolnościowa jest zapisana. Teraz najważniejsze są regeneracja, białko, nawodnienie i domknięcie kroków.",
        tone: "good",
      };
    }

    if (!hasPlannedTraining && !context.trainingDone && Number.isFinite(context.todaySteps) && context.todaySteps < 6500) {
      return {
        label: "Decyzja AI",
        value: "Rest day + spacer",
        support: "Nie ma ciężkiej jednostki, więc zachowaj regenerację, ale dołóż lekki ruch, żeby domknąć aktywność dnia.",
        tone: "warn",
      };
    }

    return {
      label: "Decyzja AI",
      value: priorityMode === "health" ? "Regeneruj mądrze" : "Dzień pod kontrolą",
      support: `Najważniejsze elementy dnia wyglądają spójnie. Tryb ${modeConfig.label.toLowerCase()}: ${modeConfig.cardioText}.`,
      tone: "good",
    };
  }

  function renderDashboardHabits(habitSummary, context) {
    if (!elements.dashboardHabitList || !elements.habitManagementList) {
      return;
    }

    elements.dashboardHabitList.replaceChildren();
    if (!state.unlocked) {
      elements.dashboardHabitList.appendChild(createMutedParagraph("Zaloguj się, aby zobaczyć dzisiejszą checklistę."));
      elements.habitManagementList.replaceChildren();
      renderMonthlyHabitTracker(null, context);
      return;
    }

    if (!habitSummary.items.length) {
      elements.dashboardHabitList.appendChild(createMutedParagraph("Na dziś nie ma zaplanowanych checkboxów. Otwórz edycję i ustaw swój grafik tygodnia."));
    } else {
      habitSummary.items.forEach((item) => {
        const label = document.createElement("label");
        label.className = "habit-check-item";
        label.dataset.state = item.done ? "done" : "pending";
        label.dataset.color = item.habit.color || "ruby";

        const checkbox = document.createElement("input");
        checkbox.type = "checkbox";
        checkbox.dataset.habitId = item.habit.id;
        checkbox.checked = item.done;

        const textWrap = document.createElement("span");
        const title = document.createElement("span");
        title.className = "habit-check-title";
        title.textContent = item.habit.name;
        const meta = document.createElement("span");
        meta.className = "habit-check-meta";
        meta.textContent = `${item.reason} Grafik: ${formatHabitWeekdays(item.habit.weekdays)}.`;

        textWrap.append(title, meta);
        label.append(checkbox, textWrap);
        elements.dashboardHabitList.appendChild(label);
      });
    }

    renderHabitManagementList(context);
    renderMonthlyHabitTracker(state.data, context);
  }

  function renderMonthlyHabitTracker(data, context = {}) {
    if (!elements.dashboardMonthTrackerBody) {
      return;
    }

    const today = context.today || toISODate(new Date());
    const todayDate = parseISODate(today);
    const monthStart = new Date(todayDate.getFullYear(), todayDate.getMonth(), 1);
    const monthEnd = new Date(todayDate.getFullYear(), todayDate.getMonth() + 1, 0);
    const totalDays = monthEnd.getDate();
    const monthLabel = new Intl.DateTimeFormat("pl-PL", { month: "long", year: "numeric" }).format(monthStart);

    elements.dashboardMonthTrackerBody.replaceChildren();
    if (elements.dashboardMonthTrackerTitle) {
      elements.dashboardMonthTrackerTitle.textContent = `Postępy: ${monthLabel}`;
    }

    if (!state.unlocked || !data) {
      if (elements.dashboardMonthTrackerStatus) {
        elements.dashboardMonthTrackerStatus.textContent = "Zablokowany";
        elements.dashboardMonthTrackerStatus.className = "status-pill status-locked";
      }
      if (elements.dashboardMonthTrackerSummary) {
        elements.dashboardMonthTrackerSummary.textContent = "Zaloguj się, aby zobaczyć miesięczny habit tracker.";
      }
      elements.dashboardMonthTrackerBody.appendChild(createMutedParagraph("Tracker miesiąca pojawi się po odblokowaniu aplikacji."));
      return;
    }

    const normalized = normalizeData(data);
    const entriesByDate = new Map(normalized.entries.map((entry) => [entry.date, entry]));
    const workoutsByDate = new Map();
    normalized.workouts.forEach((workout) => {
      if (!workout || !workout.date) {
        return;
      }
      if (!workoutsByDate.has(workout.date)) {
        workoutsByDate.set(workout.date, []);
      }
      workoutsByDate.get(workout.date).push(workout);
    });

    const settings = normalized.settings || {};
    const activeProgram = getActiveTrainingProgram(normalized);
    const currentWeight = getCurrentWeightForCalculations(settings, normalized.entries);
    const macroTargets = summarizeMacroIntake([], settings, currentWeight).targets;
    const stepGoal = 8500;
    const elapsedDays = Math.min(todayDate.getDate(), totalDays);
    let workoutDays = 0;
    let plannedChecklistDays = 0;
    let closedChecklistDays = 0;
    let cleanDays = 0;

    for (let day = 1; day <= totalDays; day += 1) {
      const date = new Date(monthStart.getFullYear(), monthStart.getMonth(), day);
      const isoDate = toISODate(date);
      const isToday = isoDate === today;
      const isFuture = date.getTime() > todayDate.getTime();
      const entry = entriesByDate.get(isoDate) || null;
      const dayWorkouts = workoutsByDate.get(isoDate) || [];
      const activeProgramPreview = activeProgram ? buildTrainingProgramPreview(activeProgram, normalized, isoDate) : null;
      const todayProtein = Number.isFinite(entry && entry.proteinG) ? entry.proteinG : NaN;
      const proteinTarget = Number.isFinite(macroTargets.proteinGrams) ? macroTargets.proteinGrams : NaN;
      const proteinGap = Number.isFinite(todayProtein) && Number.isFinite(proteinTarget)
        ? Math.max(round(proteinTarget - todayProtein, 0), 0)
        : NaN;
      const todaySteps = Number.isFinite(entry && entry.steps) ? entry.steps : NaN;
      const todaySleep = Number.isFinite(entry && entry.sleepHours) ? entry.sleepHours : NaN;
      let energyBalance = Number.isFinite(entry && entry.energyBalance) ? entry.energyBalance : NaN;
      if (!Number.isFinite(energyBalance) && entry && Number.isFinite(entry.calories) && Number.isFinite(entry.totalBurnedCalories)) {
        energyBalance = entry.calories - entry.totalBurnedCalories;
      }

      const dayHasCardio = dayWorkouts.some((workout) => resolveExerciseMeta(workout).loadMode === "cardio");
      const dayContext = {
        today: isoDate,
        settings,
        todayEntry: entry,
        todayWorkouts: dayWorkouts,
        todaySession: dayWorkouts.length ? { exerciseCount: dayWorkouts.length } : null,
        activeProgramPreview,
        todayProtein,
        proteinTarget,
        proteinGap,
        todaySteps,
        stepGoal,
        stepGap: Number.isFinite(todaySteps) ? Math.max(stepGoal - todaySteps, 0) : NaN,
        todaySleep,
        energyBalance,
        plannedUnit: activeProgramPreview && activeProgramPreview.scheduleEntry
          ? activeProgramPreview.scheduleEntry.unitName || formatPriorityModeLabel(activeProgramPreview.priorityMode)
          : dayHasCardio
            ? "Cardio"
            : "Rest / regeneracja",
        todayHasCardio: dayHasCardio,
        trainingDone: Boolean(dayWorkouts.length),
        entryDone: Boolean(entry),
        hasPlannedTraining: Boolean(activeProgramPreview && activeProgramPreview.scheduleEntry),
      };
      const dayHabits = summarizeTodayHabits(normalized, dayContext);
      const trainingDone = dayWorkouts.length > 0;
      const checklistPlanned = dayHabits.total > 0;
      const checklistDone = checklistPlanned && dayHabits.allDone;

      if (!isFuture && trainingDone) {
        workoutDays += 1;
      }
      if (!isFuture && checklistPlanned) {
        plannedChecklistDays += 1;
      }
      if (!isFuture && checklistDone) {
        closedChecklistDays += 1;
      }
      if (!isFuture && trainingDone && (!checklistPlanned || checklistDone)) {
        cleanDays += 1;
      }

      elements.dashboardMonthTrackerBody.appendChild(createMonthTrackerDayCard({
        isoDate,
        day,
        weekdayLabel: getWeekdayMeta(getIsoWeekday(isoDate)).shortLabel,
        isToday,
        isFuture,
        trainingDone,
        workoutCount: dayWorkouts.length,
        checklistPlanned,
        checklistDone,
        habitCount: dayHabits.total,
        completedHabitCount: dayHabits.completedCount,
      }));
    }

    if (elements.dashboardMonthTrackerStatus) {
      elements.dashboardMonthTrackerStatus.textContent = plannedChecklistDays
        ? `${closedChecklistDays}/${plannedChecklistDays} checklist`
        : "Brak checklist";
      elements.dashboardMonthTrackerStatus.className = `status-pill ${closedChecklistDays === plannedChecklistDays && plannedChecklistDays > 0 ? "status-unlocked" : "status-progress"}`;
    }
    if (elements.dashboardMonthTrackerSummary) {
      const checklistText = plannedChecklistDays
        ? `${closedChecklistDays}/${plannedChecklistDays} zaplanowanych checklist`
        : "brak zaplanowanych checklist";
      elements.dashboardMonthTrackerSummary.textContent = `Od 1 dnia miesiąca do dziś: ${workoutDays}/${elapsedDays} dni z treningiem, ${checklistText}, ${cleanDays} dni z treningiem i domkniętą rutyną.`;
    }
  }

  function createMonthTrackerDayCard(dayModel) {
    const card = document.createElement("article");
    card.className = "month-tracker-day";
    card.dataset.today = dayModel.isToday ? "true" : "false";
    card.dataset.future = dayModel.isFuture ? "true" : "false";

    const header = document.createElement("div");
    header.className = "month-tracker-date";
    const number = document.createElement("strong");
    number.textContent = String(dayModel.day).padStart(2, "0");
    const meta = document.createElement("span");
    meta.textContent = dayModel.isToday ? "Dziś" : dayModel.weekdayLabel;
    header.append(number, meta);

    const statusList = document.createElement("div");
    statusList.className = "month-tracker-statuses";
    statusList.append(
      createMonthTrackerStatus(
        "Trening",
        dayModel.trainingDone ? "done" : dayModel.isFuture ? "future" : "missed",
        dayModel.trainingDone ? `${dayModel.workoutCount} aktyw.` : dayModel.isFuture ? "Czeka" : "Brak"
      ),
      createMonthTrackerStatus(
        "Checklista",
        !dayModel.checklistPlanned
          ? "empty"
          : dayModel.checklistDone
            ? "done"
            : dayModel.isFuture
              ? "future"
              : "missed",
        !dayModel.checklistPlanned
          ? "Brak planu"
          : `${dayModel.completedHabitCount}/${dayModel.habitCount}`
      )
    );

    card.append(header, statusList);
    return card;
  }

  function createMonthTrackerStatus(label, stateName, value) {
    const row = document.createElement("div");
    row.className = "month-tracker-status";
    row.dataset.state = stateName;

    const check = document.createElement("span");
    check.className = "month-tracker-check";
    check.textContent = stateName === "done" ? "✓" : "";
    check.setAttribute("aria-hidden", "true");

    const text = document.createElement("span");
    text.className = "month-tracker-status-text";
    const title = document.createElement("strong");
    title.textContent = label;
    const detail = document.createElement("small");
    detail.textContent = value;
    text.append(title, detail);

    row.append(check, text);
    row.setAttribute("aria-label", `${label}: ${value}`);
    return row;
  }

  function renderHabitManagementList(context) {
    const normalized = normalizeData(state.data);
    elements.habitManagementList.replaceChildren();
    normalized.habits.forEach((habit) => {
      const item = document.createElement("div");
      item.className = "habit-management-item";
      item.dataset.color = habit.color || "ruby";
      if (state.editingHabitId === habit.id) {
        item.dataset.editing = "true";
      }

      const text = document.createElement("span");
      const strong = document.createElement("strong");
      strong.textContent = habit.name;
      const days = document.createElement("span");
      days.textContent = `${formatHabitWeekdays(habit.weekdays)} · ${formatHabitColorLabel(habit.color)}`;
      text.append(strong, days);

      const actionWrap = document.createElement("div");
      actionWrap.className = "habit-management-actions";

      const editAction = document.createElement("button");
      editAction.className = "button button-subtle button-small";
      editAction.type = "button";
      editAction.dataset.editHabit = habit.id;
      editAction.textContent = state.editingHabitId === habit.id ? "Edytowany" : "Edytuj";

      const deleteAction = document.createElement("button");
      deleteAction.className = "button button-subtle button-small";
      deleteAction.type = "button";
      deleteAction.dataset.deleteHabit = habit.id;
      deleteAction.textContent = "Usuń";
      actionWrap.append(editAction, deleteAction);

      item.append(text, actionWrap);
      elements.habitManagementList.appendChild(item);
    });

    if (!normalized.habits.length) {
      elements.habitManagementList.appendChild(createMutedParagraph("Nie ma jeszcze żadnych checkboxów w grafiku tygodnia."));
    }
  }

  function formatHabitWeekdays(weekdays) {
    const values = Array.isArray(weekdays) && weekdays.length ? weekdays : WEEKDAY_OPTIONS.map((day) => day.value);
    if (values.length === 7) {
      return "codziennie";
    }
    return values.map((value) => getWeekdayMeta(value).shortLabel).join(", ");
  }

  function formatSessionActivitySummary(session, options = {}) {
    if (!session) {
      return "Sesja policzona";
    }

    const includeCalories = options.includeCalories === true;
    const firstFiniteNumber = (...values) => values.find((value) => Number.isFinite(value));
    const parts = [];
    const exerciseCount = firstFiniteNumber(session.exerciseCount, session.entryCount);
    const totalSets = firstFiniteNumber(session.totalSets);
    const totalDurationMin = firstFiniteNumber(session.totalDurationMin, session.durationMin);
    const totalDistanceKm = firstFiniteNumber(session.distanceKm, session.totalDistanceKm, session.trainingDistanceKm);
    const totalCalories = firstFiniteNumber(session.estimatedCalories, session.totalCalories);

    if (Number.isFinite(exerciseCount) && exerciseCount > 0) {
      parts.push(`${round(exerciseCount, 0)} cw.`);
    } else if (Number.isFinite(totalSets) && totalSets > 0) {
      parts.push(`${round(totalSets, 0)} serii`);
    }

    if (Number.isFinite(totalDurationMin) && totalDurationMin > 0) {
      parts.push(`${round(totalDurationMin, 0)} min`);
    }

    if (Number.isFinite(totalDistanceKm) && totalDistanceKm > 0) {
      parts.push(`${round(totalDistanceKm, 1)} km`);
    }

    if (includeCalories && Number.isFinite(totalCalories) && totalCalories > 0) {
      parts.push(`${round(totalCalories, 0)} kcal`);
    }

    return parts.length ? parts.join(" · ") : "Sesja policzona";
  }

  function renderMainDashboard(analytics) {
    if (!elements.dashboardOverviewCards || !elements.dashboardTrainingCards || !elements.dashboardJournalCards || !elements.dashboardCoachList) {
      return;
    }

    if (!state.unlocked) {
      elements.dashboardStatus.textContent = "Oczekuje";
      elements.dashboardStatus.className = "status-pill status-locked";
      renderMetricCardCollection(elements.dashboardOverviewCards, [], "Zaloguj się, aby włączyć panel główny dnia.");
      renderMetricCardCollection(elements.dashboardTrainingCards, [], "Dzisiejszy plan treningowy pojawi się po zalogowaniu.");
      renderMetricCardCollection(elements.dashboardJournalCards, [], "Stan dziennika dziennego pojawi się po zalogowaniu.");
      renderTextList(elements.dashboardCoachList, [], "Po zalogowaniu zobaczysz konkretne decyzje na dziś.");
      renderDashboardHabits({ items: [], total: 0, completedCount: 0, pending: [], allDone: false }, { today: toISODate(new Date()) });
      return;
    }

    const normalized = normalizeData(state.data);
    const settings = normalized.settings;
    const today = toISODate(new Date());
    const todayEntry = Array.isArray(analytics.entrySnapshots)
      ? analytics.entrySnapshots.find((entry) => entry.date === today)
      : null;
    const todayWorkouts = Array.isArray(analytics.workouts)
      ? analytics.workouts.filter((workout) => workout.date === today)
      : [];
    const todayHasCardio = todayWorkouts.some((workout) => resolveExerciseMeta(workout).loadMode === "cardio");
    const todaySession = Array.isArray(analytics.sessionSummaries)
      ? analytics.sessionSummaries.find((session) => session.date === today)
      : null;
    const currentWeight = getCurrentWeightForCalculations(settings, normalized.entries);
    const macroTargets = summarizeMacroIntake([], settings, currentWeight).targets;
    const activeProgramPreview = buildTrainingProgramPreview(getActiveTrainingProgram(normalized), normalized, today);
    const todayProtein = Number.isFinite(todayEntry && todayEntry.proteinG) ? todayEntry.proteinG : NaN;
    const proteinTarget = Number.isFinite(macroTargets.proteinGrams) ? macroTargets.proteinGrams : NaN;
    const proteinGap = Number.isFinite(todayProtein) && Number.isFinite(proteinTarget)
      ? Math.max(round(proteinTarget - todayProtein, 0), 0)
      : NaN;
    const todaySteps = Number.isFinite(todayEntry && todayEntry.steps) ? todayEntry.steps : NaN;
    const stepGoal = 8500;
    const stepGap = Number.isFinite(todaySteps) ? Math.max(stepGoal - todaySteps, 0) : NaN;
    const todaySleep = Number.isFinite(todayEntry && todayEntry.sleepHours) ? todayEntry.sleepHours : NaN;
    const energyBalance = Number.isFinite(todayEntry && todayEntry.energyBalance) ? todayEntry.energyBalance : NaN;
    const plannedUnit = activeProgramPreview && activeProgramPreview.scheduleEntry
      ? activeProgramPreview.scheduleEntry.unitName || formatPriorityModeLabel(activeProgramPreview.priorityMode)
      : todayHasCardio
        ? "Cardio"
        : "Rest / regeneracja";
    const trainingDone = Boolean(todaySession && todaySession.exerciseCount);
    const entryDone = Boolean(todayEntry);
    const hasPlannedTraining = Boolean(activeProgramPreview && activeProgramPreview.scheduleEntry);
    const dashboardContext = {
      today,
      settings,
      todayEntry,
      todayWorkouts,
      todaySession,
      activeProgramPreview,
      todayProtein,
      proteinTarget,
      proteinGap,
      todaySteps,
      stepGoal,
      stepGap,
      todaySleep,
      energyBalance,
      plannedUnit,
      todayHasCardio,
      trainingDone,
      entryDone,
      hasPlannedTraining,
    };
    const habitSummary = summarizeTodayHabits(normalized, dashboardContext);
    const habitPendingNames = habitSummary.pending.slice(0, 3).map((item) => item.habit.name).join(", ");
    const decisionCard = buildTodayDecisionCard(dashboardContext);

    const overviewCards = [
      decisionCard,
      {
        label: "Checklista dnia",
        value: habitSummary.total ? `${habitSummary.completedCount}/${habitSummary.total}` : "Brak grafiku",
        support: habitSummary.total
          ? habitSummary.allDone
            ? "Wszystkie zaplanowane checkboxy na dziś są domknięte."
            : `Do domknięcia: ${habitPendingNames || "punkty wymagające ręcznego odhaczenia"}.`
          : "Dodaj swoje checkboxy i dni tygodnia, żeby Panel Główny pilnował rutyny.",
        tone: habitSummary.total
          ? habitSummary.allDone
            ? "good"
            : habitSummary.completedCount > 0
              ? "warn"
              : "risk"
          : "warn",
      },
      {
        label: "Dziennik dzisiaj",
        value: entryDone ? "Uzupełniony" : "Brak wpisu",
        support: entryDone
          ? `Masz już wpis na ${formatDisplayDate(today)} wraz z kluczowymi metrykami dnia.`
          : "Dodaj dzisiejszy wpis, aby panel mógł uczciwie ocenić bilans, kroki i regenerację.",
        tone: entryDone ? "good" : "warn",
      },
      {
        label: "Kroki dzisiaj",
        value: Number.isFinite(todaySteps) ? `${round(todaySteps, 0)}` : "Brak danych",
        support: Number.isFinite(todaySteps)
          ? todaySteps >= stepGoal
            ? `Cel ruchu około ${stepGoal} kroków jest już domknięty lub przekroczony.`
            : `Do celu około ${stepGoal} kroków zostało mniej więcej ${round(stepGap, 0)} kroków.`
          : "Jeśli wpiszesz kroki w dzienniku, panel lepiej oceni spacer, NEAT i potrzebę domknięcia ruchu.",
        tone: Number.isFinite(todaySteps) ? (todaySteps >= stepGoal ? "good" : "warn") : "warn",
      },
      {
        label: "Białko dzisiaj",
        value: Number.isFinite(todayProtein) ? `${round(todayProtein, 0)} g` : "Brak danych",
        support: Number.isFinite(todayProtein) && Number.isFinite(proteinTarget)
          ? proteinGap > 0
            ? `Do celu około ${round(proteinTarget, 0)} g brakuje jeszcze mniej więcej ${proteinGap} g białka.`
            : `Cel około ${round(proteinTarget, 0)} g białka jest już domknięty na dziś.`
          : "Po wpisaniu makro panel pokaże, czy trzeba jeszcze domknąć białko pod regenerację.",
        tone: Number.isFinite(todayProtein) && Number.isFinite(proteinTarget)
          ? (proteinGap <= 0 ? "good" : proteinGap <= 30 ? "warn" : "risk")
          : "warn",
      },
    ];

    const trainingCards = [
      {
        label: "Plan bazowy",
        value: plannedUnit,
        support: activeProgramPreview && activeProgramPreview.scheduleEntry
          ? `Faza ${formatProgramPhaseLabel(activeProgramPreview.weekContext.week.phase).toLowerCase()} w aktywnym planie tygodniowym.`
          : "Brak obowiązkowej jednostki siłowej na dziś.",
        tone: "good",
      },
      {
        label: "Wykonane ćwiczenia",
        value: todaySession ? `${todaySession.exerciseCount} ćw.` : hasPlannedTraining ? "0 ćw." : "Rest day",
        support: todaySession
          ? todaySession.executionPreview || todaySession.exercisePreview
          : hasPlannedTraining
            ? "Gdy dodasz pierwsze ćwiczenie dnia, pojawi się tutaj podsumowanie wykonania."
            : "Brak ciężkiej sesji jest dziś zgodny z planem, jeśli trzymasz regenerację, kroki i jedzenie.",
        tone: todaySession || !hasPlannedTraining ? "good" : "warn",
      },
      {
        label: "Kcal treningowe",
        value: todaySession ? `${round(todaySession.estimatedCalories, 0)} kcal` : "Brak",
        support: todaySession
          ? `${formatSessionActivitySummary(todaySession)}. Spalanie z tej sesji weszło już do dziennego bilansu.`
          : hasPlannedTraining
            ? "Po zapisaniu treningu aplikacja doliczy jego koszt do spalonych kalorii dnia."
            : "Na rest day brak kcal treningowych jest normalny. Pilnuj lekkiej aktywności i regeneracji.",
        tone: todaySession || !hasPlannedTraining ? "good" : "warn",
      },
    ];

    const journalCards = [
      {
        label: "Masa dzisiaj",
        value: Number.isFinite(todayEntry && todayEntry.weightKg) ? `${round(todayEntry.weightKg, 1)} kg` : "Brak danych",
        support: Number.isFinite(todayEntry && todayEntry.weightKg)
          ? "To masa wykorzystana do bieżących obliczeń i analiz trendu."
          : "Jeśli wpiszesz dzisiejszą masę, prognozy i ETA będą bardziej aktualne.",
        tone: Number.isFinite(todayEntry && todayEntry.weightKg) ? "good" : "warn",
      },
      {
        label: "Kalorie / bilans",
        value: entryDone ? formatEnergyBalance(energyBalance) : "Brak wpisu",
        support: entryDone
          ? `Spożycie ${Number.isFinite(todayEntry.calories) ? `${round(todayEntry.calories, 0)} kcal` : "brak"} przy spaleniu ${Number.isFinite(todayEntry.totalBurnedCalories) ? `${round(todayEntry.totalBurnedCalories, 0)} kcal` : "brak"}.`
          : "Bez dzisiejszego wpisu panel nie wie, czy jesteś już w nadwyżce, deficycie czy okolicach zera.",
        tone: Number.isFinite(energyBalance) ? (Math.abs(energyBalance) <= 250 ? "good" : "warn") : "warn",
      },
      {
        label: "Sen / regeneracja",
        value: Number.isFinite(todaySleep) ? `${round(todaySleep, 1)} h` : "Brak danych",
        support: Number.isFinite(todaySleep)
          ? todaySleep >= 7
            ? "Sen wygląda sensownie pod dzisiejszy wysiłek i regenerację."
            : "Sen był raczej krótki, więc warto pilnować zapasu i jakości ruchu."
          : "Po wpisaniu snu panel lepiej oceni, czy dziś lepiej docisnąć czy lekko odpuścić.",
        tone: Number.isFinite(todaySleep) ? (todaySleep >= 7 ? "good" : todaySleep >= 6 ? "warn" : "risk") : "warn",
      },
    ];

    const coachItems = [];
    function pushCoachItem(text, tone = "warn") {
      const safeText = sanitizePlainText(text, 260);
      if (safeText) {
        coachItems.push({ text: safeText, tone });
      }
    }

    if (activeProgramPreview && activeProgramPreview.scheduleEntry && !trainingDone) {
      pushCoachItem(`Priorytet treningowy: zrób dziś jednostkę ${activeProgramPreview.scheduleEntry.unitName} i wpisz ją do zakładki Trening.`, "warn");
    }
    if ((!activeProgramPreview || !activeProgramPreview.scheduleEntry) && !trainingDone && !todayHasCardio) {
      pushCoachItem("Dziś wygląda bardziej na rest day albo lekki ruch. Wykorzystaj dzień na regenerację, kroki i uzupełnienie dziennika.", "good");
    }
    if ((!activeProgramPreview || !activeProgramPreview.scheduleEntry) && trainingDone && todayHasCardio) {
      pushCoachItem("Dzień cardio jest zapisany. Teraz domknij białko, kroki i regenerację zamiast dokładać dodatkowy trening siłowy.", "good");
    }
    if (!entryDone) {
      pushCoachItem("Najpierw dodaj dzisiejszy wpis w Dzienniku, bo bez niego panel nie oceni uczciwie kalorii, kroków i regeneracji.", "warn");
    }
    if (Number.isFinite(proteinGap) && proteinGap > 0) {
      pushCoachItem(`Brakuje około ${proteinGap} g białka, więc dołóż jeszcze posiłek lub przekąskę bogatą w białko.`, proteinGap > 35 ? "risk" : "warn");
    }
    if (Number.isFinite(energyBalance) && energyBalance > 250 && Number.isFinite(todaySteps) && todaySteps < stepGoal) {
      pushCoachItem(`Bilans dnia jest dodatni (${formatEnergyBalance(energyBalance)}), a kroki są jeszcze niskie, więc dodatkowy spacer będzie dziś bardzo sensowny.`, "warn");
    }
    if (Number.isFinite(todaySleep) && todaySleep < 6 && activeProgramPreview && activeProgramPreview.scheduleEntry && !trainingDone) {
      pushCoachItem("Sen był niski, więc jeśli dziś trenujesz, pilnuj techniki i zostaw trochę zapasu zamiast ścigać maksima.", "risk");
    }
    if (analytics.todayActionPlan && Array.isArray(analytics.todayActionPlan.cards)) {
      analytics.todayActionPlan.cards.forEach((card) => {
        const text = card && (card.itemText || `${card.label}: ${card.value}.`);
        if (todayHasCardio && /Skoro dziś nie ma jednostki siłowej|Zapisz pierwszy trening/i.test(normalizeExerciseSearchKey(text, 260))) {
          return;
        }
        pushCoachItem(text, card && card.tone ? card.tone : "warn");
      });
    } else if (analytics.todayActionPlan && Array.isArray(analytics.todayActionPlan.items)) {
      analytics.todayActionPlan.items.forEach((item) => pushCoachItem(item, "warn"));
    }
    if (habitSummary.pending.length) {
      pushCoachItem(`Checklista dnia: domknij jeszcze ${habitPendingNames || "zaplanowane punkty"}, zanim uznasz dzień za zamknięty.`, "warn");
    } else if (habitSummary.total) {
      pushCoachItem("Checklista dnia jest zamknięta. Dzisiaj wygrywa prosty, spokojny follow-through.", "good");
    }

    const uniqueCoachItems = Array.from(new Map(coachItems.filter((item) => item && item.text).map((item) => [item.text, item])).values()).slice(0, 7);
    const dashboardStatusGood = entryDone
      && (trainingDone || !(activeProgramPreview && activeProgramPreview.scheduleEntry))
      && (!habitSummary.total || habitSummary.allDone);
    elements.dashboardStatus.textContent = dashboardStatusGood ? "Dzień pod kontrolą" : "Do domknięcia";
    elements.dashboardStatus.className = `status-pill ${dashboardStatusGood ? "status-unlocked" : "status-progress"}`;

    renderDashboardHabits(habitSummary, dashboardContext);
    renderMetricCardCollection(elements.dashboardOverviewCards, overviewCards, "Brak danych do podsumowania dnia.");
    renderMetricCardCollection(elements.dashboardTrainingCards, trainingCards, "Trening dnia pojawi się po zalogowaniu.");
    renderMetricCardCollection(elements.dashboardJournalCards, journalCards, "Dziennik dnia pojawi się po dodaniu wpisu.");
    renderTextList(elements.dashboardCoachList, uniqueCoachItems, "Dodaj pierwszy wpis albo trening, aby panel mógł zaproponować konkretne działania.");
  }

  function guessCalculatorActivityFactor(weeklySessions, steps) {
    if (Number.isFinite(steps) && steps >= 12000 || Number.isFinite(weeklySessions) && weeklySessions >= 6) {
      return "1.8";
    }
    if (Number.isFinite(steps) && steps >= 9000 || Number.isFinite(weeklySessions) && weeklySessions >= 5) {
      return "1.65";
    }
    if (Number.isFinite(steps) && steps >= 7000 || Number.isFinite(weeklySessions) && weeklySessions >= 4) {
      return "1.5";
    }
    if (Number.isFinite(steps) && steps >= 5000 || Number.isFinite(weeklySessions) && weeklySessions >= 2) {
      return "1.35";
    }
    return "1.2";
  }

  function buildCalculatorAutofillData() {
    const normalized = normalizeData(state.data);
    const settings = normalized.settings;
    const latestEntry = sortEntries(normalized.entries).slice(-1)[0] || null;
    const currentWeight = getCurrentWeightForCalculations(settings, normalized.entries);
    const steps = Number.isFinite(latestEntry && latestEntry.steps) ? latestEntry.steps : NaN;
    const weeklySessions = Number.isFinite(settings.weeklyTarget) ? settings.weeklyTarget : NaN;

    return {
      sourceDate: latestEntry ? latestEntry.date : null,
      weightKg: Number.isFinite(latestEntry && latestEntry.weightKg) ? latestEntry.weightKg : currentWeight,
      heightCm: settings.heightCm,
      ageYears: settings.ageYears,
      sex: settings.sex || "unknown",
      waistCm: latestEntry ? latestEntry.waistCm : NaN,
      neckCm: NaN,
      hipsCm: latestEntry ? latestEntry.hipsCm : NaN,
      steps,
      weeklySessions,
      activityFactor: guessCalculatorActivityFactor(weeklySessions, steps),
      knownBodyFatPct: latestEntry ? latestEntry.bodyFatPct : NaN,
    };
  }

  function populateCalculatorInputs(values) {
    elements.calculatorWeightInput.value = toInputValue(values.weightKg);
    elements.calculatorHeightInput.value = toInputValue(values.heightCm);
    elements.calculatorAgeInput.value = toInputValue(values.ageYears);
    elements.calculatorSexInput.value = safeSelectValue(values.sex, ["unknown", "male", "female"], "unknown");
    elements.calculatorWaistInput.value = toInputValue(values.waistCm);
    elements.calculatorNeckInput.value = toInputValue(values.neckCm);
    elements.calculatorHipsInput.value = toInputValue(values.hipsCm);
    elements.calculatorStepsInput.value = toInputValue(values.steps);
    elements.calculatorWeeklySessionsInput.value = toInputValue(values.weeklySessions);
    elements.calculatorActivityInput.value = String(values.activityFactor || "1.2");
  }

  function estimateBodyFatByNavy(data) {
    const heightCm = data.heightCm;
    const waistCm = data.waistCm;
    const neckCm = data.neckCm;
    if (!Number.isFinite(heightCm) || !Number.isFinite(waistCm) || !Number.isFinite(neckCm) || waistCm <= neckCm) {
      return { value: NaN, method: "BMI" };
    }

    if (data.sex === "male") {
      const value = 495 / (1.0324 - 0.19077 * Math.log10(waistCm - neckCm) + 0.15456 * Math.log10(heightCm)) - 450;
      return { value: round(clamp(value, 3, 65), 1), method: "US Navy" };
    }

    if (data.sex === "female" && Number.isFinite(data.hipsCm) && data.hipsCm > 0) {
      const value = 495 / (1.29579 - 0.35004 * Math.log10(waistCm + data.hipsCm - neckCm) + 0.221 * Math.log10(heightCm)) - 450;
      return { value: round(clamp(value, 8, 65), 1), method: "US Navy" };
    }

    return { value: NaN, method: "BMI" };
  }

  function getBmiCategoryLabel(bmi) {
    if (!Number.isFinite(bmi)) {
      return "Brak klasyfikacji";
    }
    if (bmi < 18.5) {
      return "Niedowaga";
    }
    if (bmi < 25) {
      return "Norma";
    }
    if (bmi < 30) {
      return "Nadwaga";
    }
    return "Otyłość";
  }

  function readCalculatorInputs() {
    return {
      weightKg: parseOptionalNumber(elements.calculatorWeightInput.value, { label: "Masa ciała", min: 25, max: 400 }),
      heightCm: parseOptionalNumber(elements.calculatorHeightInput.value, { label: "Wzrost", min: 120, max: 250 }),
      ageYears: parseOptionalNumber(elements.calculatorAgeInput.value, { label: "Wiek", min: 14, max: 100, integer: true }),
      sex: safeSelectValue(elements.calculatorSexInput.value, ["unknown", "male", "female"], "unknown"),
      waistCm: parseOptionalNumber(elements.calculatorWaistInput.value, { label: "Pas", min: 40, max: 200 }),
      neckCm: parseOptionalNumber(elements.calculatorNeckInput.value, { label: "Szyja", min: 20, max: 80 }),
      hipsCm: parseOptionalNumber(elements.calculatorHipsInput.value, { label: "Biodra", min: 50, max: 220 }),
      steps: parseOptionalNumber(elements.calculatorStepsInput.value, { label: "Kroki", min: 0, max: 50000 }),
      weeklySessions: parseOptionalNumber(elements.calculatorWeeklySessionsInput.value, { label: "Treningi / tydzień", min: 0, max: 14, integer: true }),
      activityFactor: Number(elements.calculatorActivityInput.value || 1.2),
    };
  }

  function computeCalculatorResults() {
    const data = readCalculatorInputs();
    const bmi = Number.isFinite(data.weightKg) && Number.isFinite(data.heightCm)
      ? round(data.weightKg / Math.pow(data.heightCm / 100, 2), 1)
      : NaN;
    const bmiCategory = getBmiCategoryLabel(bmi);
    const settingsLike = {
      currentWeightKg: data.weightKg,
      heightCm: data.heightCm,
      ageYears: data.ageYears,
      sex: data.sex,
      goal: normalizeData(state.data).settings.goal,
    };
    const bmr = estimateDailyBMR(settingsLike, data.weightKg);
    const maintenance = Number.isFinite(bmr) ? round(bmr * clamp(data.activityFactor || 1.2, 1.2, 1.95), 0) : NaN;
    const cutCalories = Number.isFinite(maintenance) ? round(maintenance - 300, 0) : NaN;
    const gainCalories = Number.isFinite(maintenance) ? round(maintenance + 250, 0) : NaN;
    const stepCalories = Number.isFinite(data.weightKg)
      ? estimateStepCalories(data.steps, settingsLike, data.weightKg)
      : 0;
    const navyEstimate = estimateBodyFatByNavy(data);
    const bmiEstimate = estimateBodyFatFromBMI(data.weightKg, settingsLike);
    const bodyFatPct = Number.isFinite(navyEstimate.value) ? navyEstimate.value : bmiEstimate;
    const bodyFatMethod = Number.isFinite(navyEstimate.value) ? navyEstimate.method : "BMI";
    const latestEntry = sortEntries(normalizeData(state.data).entries).slice(-1)[0] || null;
    const latestLoggedBodyFat = Number.isFinite(latestEntry && latestEntry.bodyFatPct) ? latestEntry.bodyFatPct : NaN;

    const cards = [
      {
        label: "BMI",
        value: Number.isFinite(bmi) ? `${bmi}` : "Brak danych",
        support: Number.isFinite(bmi) ? `Klasyfikacja: ${bmiCategory}.` : "Wpisz masę i wzrost, aby policzyć BMI.",
        tone: Number.isFinite(bmi) ? (bmi >= 18.5 && bmi < 25 ? "good" : bmi < 30 ? "warn" : "risk") : "warn",
      },
      {
        label: "Kalorie utrzymania",
        value: Number.isFinite(maintenance) ? `${maintenance} kcal` : "Brak danych",
        support: Number.isFinite(maintenance)
          ? `BMR około ${bmr} kcal. Redukcja ~${cutCalories} kcal, masa ~${gainCalories} kcal.`
          : "Wpisz masę, wzrost i wiek, aby policzyć orientacyjne utrzymanie.",
        tone: Number.isFinite(maintenance) ? "good" : "warn",
      },
      {
        label: "Szac. BF%",
        value: Number.isFinite(bodyFatPct) ? `${bodyFatPct}%` : "Brak danych",
        support: Number.isFinite(bodyFatPct)
          ? `Metoda: ${bodyFatMethod}${Number.isFinite(latestLoggedBodyFat) ? ` · ostatni wpis w dzienniku: ${round(latestLoggedBodyFat, 1)}%.` : "."}`
          : "Wpisz podstawowe dane sylwetkowe, aby oszacować poziom tkanki tłuszczowej.",
        tone: Number.isFinite(bodyFatPct) ? "good" : "warn",
      },
      {
        label: "Kroki / ruch",
        value: Number.isFinite(data.steps) ? `${round(data.steps, 0)}` : "Brak danych",
        support: Number.isFinite(data.steps)
          ? `Dzisiejsze kroki to około ${round(stepCalories, 0)} kcal ruchu poza treningiem.`
          : "Jeśli wpiszesz kroki, kalkulator oszacuje też koszt samego ruchu dziennego.",
        tone: Number.isFinite(data.steps) ? "good" : "warn",
      },
    ];

    const notes = [];
    if (Number.isFinite(bmi)) {
      notes.push(`BMI wynosi ${bmi}, co obecnie wpada w zakres: ${bmiCategory.toLowerCase()}.`);
    }
    if (Number.isFinite(maintenance)) {
      notes.push(`Dzienne utrzymanie to około ${maintenance} kcal. Przy redukcji startuj mniej więcej od ${cutCalories} kcal, a przy masie około ${gainCalories} kcal.`);
    }
    if (Number.isFinite(bodyFatPct)) {
      notes.push(`Szacowana tkanka tłuszczowa to około ${bodyFatPct}% liczona metodą ${bodyFatMethod}.`);
    }
    if (Number.isFinite(stepCalories) && stepCalories > 0) {
      notes.push(`Same kroki dokładają dziś około ${round(stepCalories, 0)} kcal ruchu.`);
    }
    if (Number.isFinite(data.weeklySessions)) {
      notes.push(`Aktywność bazowa została ustawiona przy ${data.weeklySessions} treningach tygodniowo i mnożniku ${round(data.activityFactor, 2)}.`);
    }

    return {
      cards,
      notes,
      sourceDate: latestEntry ? latestEntry.date : null,
    };
  }

  function renderCalculatorResults(result) {
    renderMetricCardCollection(elements.calculatorResultCards, result.cards, "Brak wyników do pokazania.");
    renderTextList(elements.calculatorResultList, result.notes, "Dodaj dane, a kalkulator pokaże wnioski.");
  }

  function renderCalculatorPanel() {
    if (!elements.calculatorResultCards || !elements.calculatorResultList) {
      return;
    }

    if (!state.unlocked) {
      elements.calculatorStatus.textContent = "Autofill";
      elements.calculatorStatus.className = "status-pill status-locked";
      renderMetricCardCollection(elements.calculatorResultCards, [], "Zaloguj się, aby pobrać dane z profilu i dziennika.");
      renderTextList(elements.calculatorResultList, [], "Po zalogowaniu kalkulator sam pobierze najświeższe dane z aplikacji.");
      return;
    }

    if (!state.calculatorDirty) {
      populateCalculatorInputs(buildCalculatorAutofillData());
    }

    try {
      const result = computeCalculatorResults();
      elements.calculatorStatus.textContent = state.calculatorDirty ? "Tryb ręczny" : "Autofill";
      elements.calculatorStatus.className = `status-pill ${state.calculatorDirty ? "status-progress" : "status-unlocked"}`;
      renderCalculatorResults(result);
    } catch (error) {
      elements.calculatorStatus.textContent = "Uzupełnij dane";
      elements.calculatorStatus.className = "status-pill status-warn";
      renderMetricCardCollection(elements.calculatorResultCards, [], "Kalkulator potrzebuje kompletu podstawowych danych.");
      renderTextList(elements.calculatorResultList, [error.message || "Nie udało się policzyć kalkulatora."], "Brak danych.");
    }
  }

  function handleCalculatorFieldInput() {
    state.calculatorDirty = true;
    if (elements.calculatorStatus) {
      elements.calculatorStatus.textContent = "Tryb ręczny";
      elements.calculatorStatus.className = "status-pill status-progress";
    }
  }

  function handleCalculatorAutofill() {
    state.calculatorDirty = false;
    populateCalculatorInputs(buildCalculatorAutofillData());
    renderCalculatorPanel();
  }

  function handleCalculatorReset() {
    state.calculatorDirty = false;
    populateCalculatorInputs(buildCalculatorAutofillData());
    renderCalculatorPanel();
  }

  function handleCalculatorCompute(event) {
    if (event) {
      event.preventDefault();
    }
    state.calculatorDirty = true;
    renderCalculatorPanel();
  }

  function renderOnboarding(analytics) {
    const guide = buildOnboardingGuide(analytics);
    elements.onboardingCards.replaceChildren();
    elements.onboardingList.replaceChildren();
    elements.onboardingSummary.textContent = guide.summary;
    elements.onboardingStatus.textContent = guide.statusLabel;
    elements.onboardingStatus.className = `status-pill ${guide.statusClass}`;

    guide.cards.forEach((card) => {
      const article = document.createElement("article");
      article.className = "metric-card";

      const label = document.createElement("span");
      label.className = "metric-label";
      label.textContent = card.label;

      const value = document.createElement("p");
      value.className = `metric-value ${card.tone ? `metric-tone-${card.tone}` : ""}`.trim();
      value.textContent = card.value;

      const support = document.createElement("p");
      support.className = "metric-support";
      support.textContent = card.support;

      article.append(label, value, support);
      elements.onboardingCards.appendChild(article);
    });

    guide.items.forEach((message) => {
      const item = document.createElement("li");
      item.textContent = message;
      elements.onboardingList.appendChild(item);
    });
  }

  function buildOnboardingGuideLegacy(analytics) {
    const normalized = normalizeData(state.data);
    const settings = normalized.settings;
    const hasVault = Boolean(readStoredVault());
    const hasProfileBase = Number.isFinite(settings.currentWeightKg) && Number.isFinite(settings.heightCm);
    const hasTargets = Number.isFinite(settings.targetWeightKg) || Number.isFinite(settings.targetBodyFatPct);
    const hasEntry = normalized.entries.length > 0;
    const hasWorkout = normalized.workouts.length > 0;
    const hasTemplate = normalized.templates.length > 0;
    const hasProgram = normalized.trainingPrograms.length > 0;
    const coreCompletion = [hasVault && state.unlocked, hasProfileBase, hasEntry, hasWorkout].filter(Boolean).length;

    let summary = "Aplikacja jest gotowa do pierwszego uruchomienia. Zacznij od utworzenia konta lokalnego, potem uzupełnij profil i dodaj pierwszy wpis.";
    if (hasVault && !state.unlocked) {
      summary = "Masz już konto lokalne. Zaloguj się, żeby odblokować dane i kontynuować konfigurację albo codzienny tracking.";
    } else if (state.unlocked && !hasEntry && !hasWorkout) {
      summary = "Konto jest odblokowane. Największy sens ma teraz: profil, pierwszy wpis dzienny i pierwszy trening albo cardio.";
    } else if (state.unlocked) {
      summary = "Podstawy są już gotowe. Onboarding pilnuje teraz brakujących elementów, żeby model mógł działać coraz pewniej i praktyczniej.";
    }

    const cards = [
      {
        label: "1. Konto lokalne",
        value: !hasVault ? "Utwórz konto" : state.unlocked ? "Zalogowany" : "Zaloguj się",
        support: !hasVault
          ? "Najpierw utwórz lokalne konto w sekcji Logowanie. Bez tego aplikacja nie zapisze danych."
          : state.unlocked
            ? "Konto jest odblokowane, więc możesz już zapisywać wpisy, treningi i plan tygodniowy."
            : "Konto już istnieje. Wystarczy zalogować się hasłem, żeby odzyskać dostęp do danych.",
        tone: !hasVault ? "warn" : state.unlocked ? "good" : "warn",
      },
      {
        label: "2. Profil i cel",
        value: hasProfileBase ? (hasTargets ? "Profil + cel" : "Profil gotowy") : "Uzupelnij profil",
        support: hasProfileBase
          ? hasTargets
            ? "Masa, wzrost i przynajmniej jeden cel liczbowy są ustawione, więc prognozy i ETA mają sensowny punkt odniesienia."
            : "Masa i wzrost są już wpisane. Teraz warto dodać cel masy albo BF, żeby aplikacja mogła liczyć ETA."
          : "Uzupełnij masę i wzrost. To podstawa do BMR, BMI, szacowanego BF i części rekomendacji kalorii.",
        tone: hasProfileBase ? (hasTargets ? "good" : "warn") : "risk",
      },
      {
        label: "3. Dzienny wpis",
        value: hasEntry ? `${normalized.entries.length} wpis.` : "Dodaj pierwszy",
        support: hasEntry
          ? "Masz już wpisy dzienne, więc model widzi wagę, kalorie, kroki albo regenerację i może budować realne trendy."
          : "Pierwszy wpis najlepiej dodać od razu z masą, kaloriami lub makro, krokami i snem z dzisiejszego dnia.",
        tone: hasEntry ? "good" : "warn",
      },
      {
        label: "4. Trening",
        value: hasWorkout ? `${normalized.workouts.length} wpis. trening.` : "Dodaj pierwszy",
        support: hasWorkout
          ? "Treningi są już zapisane, więc aplikacja może liczyć progres ćwiczeń, spalanie i decyzje na dziś."
          : "Dodaj choć jeden trening siłowy albo cardio. To uruchomi progres ćwiczeń, historię aktywności i spalanie treningowe.",
        tone: hasWorkout ? "good" : "warn",
      },
      {
        label: "5. Szablony i plan",
        value: hasProgram ? "Plan gotowy" : hasTemplate ? "Masz szablon" : "Opcjonalne",
        support: hasProgram
          ? "Program tygodniowy jest już ustawiony, więc aplikacja umie proponować konkretne jednostki i progresję."
          : hasTemplate
            ? "Szablony są już zapisane. Plan trenerski może już bazować na historii i zapisanych jednostkach."
            : "To etap opcjonalny. Najpierw zbierz kilka wpisów i treningów, a potem zapisz dzień jako szablon i zbuduj plan tygodniowy.",
        tone: hasProgram ? "good" : hasTemplate ? "warn" : "warn",
      },
    ];

    const items = [];
    if (!hasVault) {
      items.push("1. Utwórz lokalne konto w sekcji Logowanie i zapamiętaj hasło, bo bez niego nie da się odszyfrować danych.");
    } else if (!state.unlocked) {
      items.push("1. Zaloguj się istniejącym hasłem, żeby odblokować dane i formularze.");
    }
    if (state.unlocked && !hasProfileBase) {
      items.push("2. W sekcji Profil i cel wpisz aktualną masę oraz wzrost. To dwa najważniejsze pola na start.");
    }
    if (state.unlocked && hasProfileBase && !hasTargets) {
      items.push("3. Dodaj cel masy albo tkanki tłuszczowej, jeśli chcesz dostawać sensowne ETA i bardziej konkretne rekomendacje.");
    }
    if (state.unlocked && !hasEntry) {
      items.push("4. Dodaj pierwszy dzienny wpis. Najbardziej opłaca się zacząć od masy, kalorii lub makro, kroków i snu.");
    }
    if (state.unlocked && !hasWorkout) {
      items.push("5. Dodaj pierwszy trening albo cardio. Przy siłowni wpisuj serie, powtórzenia i ciężar, a przy cardio profil, czas i opcjonalnie dystans.");
    }
    if (state.unlocked && hasEntry && hasWorkout && !hasTemplate) {
      items.push("6. Gdy zapiszesz pełny dzień treningowy, użyj przycisku zapisania dnia jako szablon - to bardzo przyspiesza kolejne wpisy.");
    }
    if (state.unlocked && hasTemplate && !hasProgram) {
      items.push("7. Z zapisanych szablonów możesz korzystać w treningu, a Plan trenerski będzie podpowiadał progresję na podstawie historii.");
    }
    if (state.unlocked && coreCompletion >= 4) {
      items.push("8. Podstawy są gotowe. Teraz najwięcej zyskasz na regularnym logowaniu danych i utrzymaniu porównywalnych warunków pomiaru.");
    }

    return {
      summary,
      cards,
      items: items.slice(0, 6),
      statusLabel: coreCompletion >= 4 ? "Gotowe" : coreCompletion >= 2 ? `${coreCompletion}/4 kroki` : "Start",
      statusClass: coreCompletion >= 4 ? "status-unlocked" : coreCompletion >= 2 ? "status-progress" : "status-locked",
    };
  }

  function buildOnboardingGuide(analytics) {
    const normalized = normalizeData(state.data);
    const settings = normalized.settings;
    const macroSummary = analytics && analytics.macroSummary ? analytics.macroSummary : null;
    const physiqueSummary = analytics && analytics.physiqueSummary ? analytics.physiqueSummary : null;
    const hasVault = Boolean(readStoredVault());
    const hasProfileBase = Number.isFinite(settings.currentWeightKg) && Number.isFinite(settings.heightCm);
    const hasTargets = Number.isFinite(settings.targetWeightKg) || Number.isFinite(settings.targetBodyFatPct);
    const hasEntry = normalized.entries.length > 0;
    const hasWorkout = normalized.workouts.length > 0;
    const hasTemplate = normalized.templates.length > 0;
    const hasProgram = normalized.trainingPrograms.length > 0;
    const hasMacroTracking = Boolean(macroSummary && macroSummary.trackedDays);
    const hasMeasurements = Boolean(physiqueSummary && physiqueSummary.loggedEntriesCount);
    const hasPhotos = Boolean(physiqueSummary && physiqueSummary.photoCount);
    const coreCompletion = [hasVault && state.unlocked, hasProfileBase, hasEntry, hasWorkout].filter(Boolean).length;
    const advancedCompletion = [hasTargets, hasTemplate, hasProgram, hasMacroTracking, hasMeasurements].filter(Boolean).length;

    let summary = "Aplikacja jest gotowa do pierwszego uruchomienia. Zacznij od utworzenia konta lokalnego, potem uzupełnij profil i dodaj pierwszy wpis.";
    if (hasVault && !state.unlocked) {
      summary = "Masz już konto lokalne. Zaloguj się, żeby odblokować dane i kontynuować konfigurację albo codzienny tracking.";
    } else if (state.unlocked && !hasEntry && !hasWorkout) {
      summary = "Konto jest odblokowane. Największy sens ma teraz: profil, pierwszy wpis dzienny i pierwszy trening albo cardio.";
    } else if (state.unlocked && coreCompletion >= 4 && advancedCompletion >= 4) {
      summary = "Podstawy i większość warstwy zaawansowanej są już gotowe. Onboarding pilnuje teraz regularności logowania i drobnych braków, żeby rekomendacje pozostawały praktyczne.";
    } else if (state.unlocked) {
      summary = "Podstawy są już gotowe. Onboarding pilnuje teraz brakujących elementów, żeby model mógł działać coraz pewniej i praktyczniej.";
    }

    const cards = [
      {
        label: "1. Konto lokalne",
        value: !hasVault ? "Utwórz konto" : state.unlocked ? "Zalogowany" : "Zaloguj się",
        support: !hasVault
          ? "Najpierw utwórz lokalne konto w sekcji Logowanie. Bez tego aplikacja nie zapisze danych."
          : state.unlocked
            ? "Konto jest odblokowane, więc możesz już zapisywać wpisy, treningi i plan tygodniowy."
            : "Konto już istnieje. Wystarczy zalogować się hasłem, żeby odzyskać dostęp do danych.",
        tone: !hasVault ? "warn" : state.unlocked ? "good" : "warn",
      },
      {
        label: "2. Profil i cel",
        value: hasProfileBase ? (hasTargets ? "Profil + cel" : "Profil gotowy") : "Uzupełnij profil",
        support: hasProfileBase
          ? hasTargets
            ? "Masa, wzrost i przynajmniej jeden cel liczbowy są ustawione, więc prognozy i ETA mają sensowny punkt odniesienia."
            : "Masa i wzrost są już wpisane. Teraz warto dodać cel masy albo BF, żeby aplikacja mogła liczyć ETA."
          : "Uzupełnij masę i wzrost. To podstawa do BMR, BMI, szacowanego BF i części rekomendacji kalorii.",
        tone: hasProfileBase ? (hasTargets ? "good" : "warn") : "risk",
      },
      {
        label: "3. Dzienny wpis",
        value: hasEntry ? `${normalized.entries.length} wpis.` : "Dodaj pierwszy",
        support: hasEntry
          ? "Masz już wpisy dzienne, więc model widzi wagę, kalorie, kroki albo regenerację i może budować realne trendy."
          : "Pierwszy wpis najlepiej dodać od razu z masą, kaloriami lub makro, krokami i snem z dzisiejszego dnia.",
        tone: hasEntry ? "good" : "warn",
      },
      {
        label: "4. Trening",
        value: hasWorkout ? `${normalized.workouts.length} wpis. trening.` : "Dodaj pierwszy",
        support: hasWorkout
          ? "Treningi są już zapisane, więc aplikacja może liczyć progres ćwiczeń, spalanie i decyzje na dziś."
          : "Dodaj choć jeden trening siłowy albo cardio. To uruchomi progres ćwiczeń, historię aktywności i spalanie treningowe.",
        tone: hasWorkout ? "good" : "warn",
      },
      {
        label: "5. Szablony i plan",
        value: hasProgram ? "Plan gotowy" : hasTemplate ? "Masz szablon" : "Opcjonalne",
        support: hasProgram
          ? "Program tygodniowy jest już ustawiony, więc aplikacja umie proponować konkretne jednostki i progresję."
          : hasTemplate
            ? "Szablony są już zapisane. Plan trenerski może już bazować na historii i zapisanych jednostkach."
            : "To etap opcjonalny. Najpierw zbierz kilka wpisów i treningów, a potem zapisz dzień jako szablon i zbuduj plan tygodniowy.",
        tone: hasProgram ? "good" : hasTemplate ? "warn" : "warn",
      },
      {
        label: "6. Makro i sylwetka",
        value: hasMacroTracking && hasMeasurements ? "Logi zaawansowane" : hasMacroTracking || hasMeasurements ? "Częściowo gotowe" : "Opcjonalne",
        support: hasMacroTracking && hasMeasurements
          ? "Masz już makro i pomiary sylwetki, więc analiza odżywiania, regeneracji i rekompozycji ma znacznie lepszy kontekst."
          : hasMacroTracking
            ? "Makro jest już logowane. Dla pełniejszego obrazu dorzuć jeszcze pas albo inne obwody raz na 7-14 dni."
            : hasMeasurements
              ? "Obwody lub zdjęcia już są. Teraz warto dopisać białko, tłuszcze i węgle, żeby model lepiej oceniał odżywianie."
              : "To nie jest wymagane na start, ale makro, obwody i zdjęcia progresu bardzo poprawiają jakość rekomendacji.",
        tone: hasMacroTracking && hasMeasurements ? "good" : hasMacroTracking || hasMeasurements ? "warn" : "warn",
      },
    ];

    const items = [];
    if (!hasVault) {
      items.push("Utwórz lokalne konto w sekcji Logowanie i zapamiętaj hasło, bo bez niego nie da się odszyfrowac danych.");
    } else if (!state.unlocked) {
      items.push("Zaloguj się istniejącym hasłem, żeby odblokować dane i formularze.");
    }
    if (state.unlocked && !hasProfileBase) {
      items.push("W sekcji Profil i cel wpisz aktualną masę oraz wzrost. To dwa najważniejsze pola na start.");
    }
    if (state.unlocked && hasProfileBase && !hasTargets) {
      items.push("Dodaj cel masy albo tkanki tłuszczowej, jeśli chcesz dostawać sensowne ETA i bardziej konkretne rekomendacje.");
    }
    if (state.unlocked && !hasEntry) {
      items.push("Dodaj pierwszy dzienny wpis. Najbardziej opłaca się zacząć od masy, kalorii lub makro, kroków i snu.");
    }
    if (state.unlocked && !hasWorkout) {
      items.push("Dodaj pierwszy trening albo cardio. Przy siłowni wpisuj serie, powtórzenia i ciężar, a przy cardio profil, czas i opcjonalnie dystans.");
    }
    if (state.unlocked && hasEntry && hasWorkout && !hasTemplate) {
      items.push("Gdy zapiszesz pełny dzień treningowy, użyj przycisku zapisania dnia jako szablon. To bardzo przyspiesza kolejne wpisy.");
    }
    if (state.unlocked && hasTemplate && !hasProgram) {
      items.push("Korzystaj z zapisanych szablonów w treningu, a Plan trenerski będzie podpowiadał progresję na podstawie historii.");
    }
    if (state.unlocked && hasEntry && !hasMacroTracking) {
      items.push("Zacznij dopisywać białko, tłuszcze i węgle przynajmniej w dni treningowe. Bez tego trudniej ocenić paliwo pod progres i regenerację.");
    }
    if (state.unlocked && hasEntry && !hasMeasurements) {
      items.push("Raz na 7-14 dni wpisz pas, biodra albo klatkę. Sama masa nie zawsze pokazuje, czy idzie redukcja, rekompozycja albo budowa mięśni.");
    }
    if (state.unlocked && hasMeasurements && !hasPhotos) {
      items.push("Dodaj lokalne zdjęcie progresu co 2-4 tygodnie, najlepiej w podobnym świetle i pozie. To mocno pomaga przy ocenie zmian sylwetki.");
    }
    if (state.unlocked && coreCompletion >= 4) {
      items.push("Podstawy są gotowe. Teraz najwięcej zyskasz na regularnym logowaniu danych i utrzymaniu porownywalnych warunkow pomiaru.");
    }
    if (state.unlocked && !items.length) {
      items.push("Konto jest już dobrze skonfigurowane. Korzystaj z szybkich przycisków, regularnie wpisuj dane i traktuj rekomendacje z planu działania jako dzienny pulpit decyzji.");
    }

    return {
      summary,
      cards,
      items: items.slice(0, 6).map((message, index) => `${index + 1}. ${message}`),
      statusLabel: coreCompletion >= 4 ? "Gotowe" : coreCompletion >= 2 ? `${coreCompletion}/4 kroki` : "Start",
      statusClass: coreCompletion >= 4 ? "status-unlocked" : coreCompletion >= 2 ? "status-progress" : "status-locked",
    };
  }

  function renderMetricCards(analytics) {
    elements.metricCards.replaceChildren();

    if (!state.unlocked) {
      elements.metricCards.appendChild(createMutedParagraph("Zaloguj się, aby zobaczyć wynik modelu."));
      return;
    }

    analytics.metricCards.forEach((card) => {
      const article = document.createElement("article");
      article.className = "metric-card";

      const label = document.createElement("span");
      label.className = "metric-label";
      label.textContent = card.label;

      const value = document.createElement("p");
      value.className = `metric-value ${card.tone ? `metric-tone-${card.tone}` : ""}`.trim();
      value.textContent = card.value;

      const support = document.createElement("p");
      support.className = "metric-support";
      support.textContent = card.support;

      article.append(label, value, support);
      elements.metricCards.appendChild(article);
    });
  }

  function renderLocalAiModel(analytics) {
    if (!elements.localAiModelCards || !elements.localAiModelList) {
      return;
    }

    const model = analytics && analytics.localAiModel ? analytics.localAiModel : null;
    if (!state.unlocked) {
      renderMetricCardCollection(elements.localAiModelCards, [], "Zaloguj się, aby lokalny model mógł trenowac na Twojej historii.");
      renderTextList(elements.localAiModelList, [], "Model predykcyjny uruchomi się po zalogowaniu.");
      return;
    }

    renderMetricCardCollection(
      elements.localAiModelCards,
      model && Array.isArray(model.cards) ? model.cards : [],
      "Model potrzebuje jeszcze historii masy, dziennika i treningów."
    );
    renderTextList(
      elements.localAiModelList,
      model && Array.isArray(model.notes) ? model.notes : [],
      "Dodaj więcej wpisów dziennika i treningów, aby model mógł zacząć walidowaną predykcję."
    );
  }

  function renderInsights(analytics) {
    elements.insightsList.replaceChildren();
    const insights = state.unlocked
      ? analytics.insights
      : ["Jesteś wylogowany. Rekomendacje pojawią się po zalogowaniu."];

    insights.forEach((message) => {
      const item = document.createElement("li");
      item.textContent = message;
      elements.insightsList.appendChild(item);
    });
  }

  function renderEntriesTable(entries) {
    elements.entriesBody.replaceChildren();
    if (state.unlocked) {
      const filteredEntries = filterEntrySnapshots(entries);
      if (entries.length && !filteredEntries.length) {
        elements.entriesBody.appendChild(createEmptyTableRow("Brak wpisów pasujących do aktywnych filtrów.", 7));
        return;
      }
      entries = filteredEntries;
    } else {
      elements.entryFilterSummary.textContent = "Filtry wpisów uaktywnia się po zalogowaniu.";
    }

    if (!state.unlocked) {
      elements.entriesBody.appendChild(createEmptyTableRow("Jesteś wylogowany.", 7));
      return;
    }

    if (!entries.length) {
      elements.entriesBody.appendChild(createEmptyTableRow("Brak wpisów. Dodaj pierwszy dzienny wpis.", 7));
      return;
    }

    entries.forEach((entry) => {
      const row = document.createElement("tr");
      row.appendChild(createCell(formatDisplayDate(entry.date)));
      row.appendChild(createCell(formatMetric(entry.weightKg, "kg")));
      row.appendChild(createCell(formatCaloriesPair(entry.calories, entry.totalBurnedCalories)));
      row.appendChild(createCell(formatMacroSummary(entry)));
      row.appendChild(createCell(formatEnergyBalance(entry.energyBalance)));
      row.appendChild(createCell(formatMetric(entry.sleepHours, "h")));

      const actionCell = document.createElement("td");
      const actionWrap = document.createElement("div");
      actionWrap.className = "table-actions";

      const editButton = document.createElement("button");
      editButton.type = "button";
      editButton.className = "edit-button";
      editButton.setAttribute("data-entry-id", entry.id);
      editButton.setAttribute("data-entry-action", "edit");
      editButton.textContent = "Edytuj";

      const deleteButton = document.createElement("button");
      deleteButton.type = "button";
      deleteButton.className = "delete-button";
      deleteButton.setAttribute("data-entry-id", entry.id);
      deleteButton.setAttribute("data-entry-action", "delete");
      deleteButton.textContent = "Usuń";

      actionWrap.append(editButton, deleteButton);
      actionCell.appendChild(actionWrap);
      row.appendChild(actionCell);

      elements.entriesBody.appendChild(row);
    });
  }

  function renderPhysiquePanel(summary) {
    elements.physiqueCards.replaceChildren();
    elements.physiqueBody.replaceChildren();
    elements.progressPhotoGallery.replaceChildren();

    if (!state.unlocked) {
      elements.physiqueCards.appendChild(createMutedParagraph("Zaloguj się, aby śledzić obwody i zdjęcia progresu."));
      elements.physiqueBody.appendChild(createEmptyTableRow("Jesteś wylogowany.", 7));
      const emptyGallery = document.createElement("p");
      emptyGallery.className = "muted-empty photo-empty";
      emptyGallery.textContent = "Galeria zdjęć progresu pojawi się po zalogowaniu.";
      elements.progressPhotoGallery.appendChild(emptyGallery);
      return;
    }

    const physique = summary || buildPhysiqueSummary(state.data.entries, normalizeData(state.data).settings);
    if (!physique.loggedEntriesCount) {
      elements.physiqueCards.appendChild(createMutedParagraph("Dodaj pas, biodra, klatkę, ramię, udo albo lokalne zdjęcie progresu, aby śledzić realne zmiany sylwetki."));
      elements.physiqueBody.appendChild(createEmptyTableRow("Brak pomiarów sylwetki ani zdjęć progresu.", 7));
      const emptyGallery = document.createElement("p");
      emptyGallery.className = "muted-empty photo-empty";
      emptyGallery.textContent = "Dodaj pierwsze zdjęcie progresu, aby zbudować lokalne archiwum sylwetki.";
      elements.progressPhotoGallery.appendChild(emptyGallery);
      return;
    }

    physique.cards.forEach((card) => {
      const article = document.createElement("article");
      article.className = "metric-card";

      const label = document.createElement("span");
      label.className = "metric-label";
      label.textContent = card.label;

      const value = document.createElement("p");
      value.className = `metric-value ${card.tone ? `metric-tone-${card.tone}` : ""}`.trim();
      value.textContent = card.value;

      const support = document.createElement("p");
      support.className = "metric-support";
      support.textContent = card.support;

      article.append(label, value, support);
      elements.physiqueCards.appendChild(article);
    });

    if (!physique.tableRows.length) {
      elements.physiqueBody.appendChild(createEmptyTableRow("Brak pomiarów do wyświetlenia.", 7));
    } else {
      physique.tableRows.forEach((rowData) => {
        const row = document.createElement("tr");
        row.appendChild(createCell(formatDisplayDate(rowData.date)));
        row.appendChild(createCell(formatMetric(rowData.waistCm, "cm")));
        row.appendChild(createCell(formatMetric(rowData.hipsCm, "cm")));
        row.appendChild(createCell(formatMetric(rowData.chestCm, "cm")));
        row.appendChild(createCell(formatMetric(rowData.armCm, "cm")));
        row.appendChild(createCell(formatMetric(rowData.thighCm, "cm")));
        row.appendChild(createCell(rowData.photoCount ? `${rowData.photoCount} zdj.` : "brak"));
        elements.physiqueBody.appendChild(row);
      });
    }

    if (!physique.photos.length) {
      const emptyGallery = document.createElement("p");
      emptyGallery.className = "muted-empty photo-empty";
      emptyGallery.textContent = "Brak zdjęć progresu w archiwum. Dodawaj je lokalnie co 2-4 tygodnie, najlepiej w tych samych warunkach.";
      elements.progressPhotoGallery.appendChild(emptyGallery);
      return;
    }

    physique.photos.forEach((photo) => {
      const article = document.createElement("article");
      article.className = "photo-card";

      const image = document.createElement("img");
      image.src = photo.dataUrl;
      image.alt = `${photo.name} (${formatDisplayDate(photo.date)})`;
      image.loading = "lazy";

      const meta = document.createElement("div");
      meta.className = "photo-meta";

      const title = document.createElement("strong");
      title.className = "photo-title";
      title.textContent = photo.name || "Zdjęcie progresu";

      const date = document.createElement("span");
      date.textContent = formatDisplayDate(photo.date);

      const size = document.createElement("span");
      size.textContent = `${photo.sizeKb || "?"} KB`;

      meta.append(title, date, size);
      article.append(image, meta);
      elements.progressPhotoGallery.appendChild(article);
    });
  }
  function renderProgressCards(analytics) {
    elements.progressCards.replaceChildren();

    if (!state.unlocked) {
      elements.progressCards.appendChild(createMutedParagraph("Zaloguj się, aby śledzić realizację celów."));
      return;
    }

    analytics.progressCards.forEach((card) => {
      const article = document.createElement("article");
      article.className = "progress-card";

      const label = document.createElement("span");
      label.className = "metric-label";
      label.textContent = card.label;

      const value = document.createElement("p");
      value.className = `metric-value ${card.tone ? `metric-tone-${card.tone}` : ""}`.trim();
      value.textContent = card.value;

      const support = document.createElement("p");
      support.className = "metric-support";
      support.textContent = card.support;

      article.append(label, value, support);

      if (Number.isFinite(card.progress)) {
        const meta = document.createElement("div");
        meta.className = "progress-meta";

        const progressText = document.createElement("span");
        progressText.textContent = `Realizacja: ${card.progress}%`;

        const etaText = document.createElement("span");
        etaText.textContent = card.eta;

        const track = document.createElement("div");
        track.className = "progress-track";

        const fill = document.createElement("div");
        fill.className = "progress-fill";
        fill.style.width = `${card.progress}%`;

        track.appendChild(fill);
        meta.append(progressText, etaText);
        article.append(meta, track);
      }

      elements.progressCards.appendChild(article);
    });
  }

  function renderCoachPlan(analytics) {
    if (!elements.coachPlanCards || !elements.coachPlanList || !elements.coachPlanTrainingBody) {
      return;
    }

    if (!state.unlocked) {
      if (elements.coachPlanStatus) {
        elements.coachPlanStatus.textContent = "Zablokowane";
        elements.coachPlanStatus.className = "status-pill status-locked";
      }
      if (elements.coachPlanSummary) {
        elements.coachPlanSummary.textContent = "Zaloguj się, aby trener połączył treningi, jedzenie, regenerację i cele w konkretny plan.";
      }
      renderMetricCardCollection(elements.coachPlanCards, [], "Zaloguj się, aby zobaczyć decyzję trenera.");
      renderTextList(elements.coachPlanList, [], "Po zalogowaniu pojawią się priorytety na najbliższe 7 dni.");
      elements.coachPlanTrainingBody.replaceChildren(createEmptyTableRow("Zaloguj się, aby zobaczyć decyzje treningowe.", 4));
      return;
    }

    const coachPlan = buildCoachPlanModel(analytics);
    if (elements.coachPlanStatus) {
      elements.coachPlanStatus.textContent = coachPlan.statusLabel;
      elements.coachPlanStatus.className = `status-pill ${coachPlan.statusClass}`;
    }
    if (elements.coachPlanSummary) {
      elements.coachPlanSummary.textContent = coachPlan.summary;
    }

    renderMetricCardCollection(elements.coachPlanCards, coachPlan.cards, "Dodaj trening albo wpis dziennika, aby trener miał z czego podjąć decyzję.");
    renderTextList(elements.coachPlanList, coachPlan.items, "Brak zaleceń. Dodaj trening, dziennik lub cel, aby Plan zaczął prowadzić tydzień.");
    renderCoachPlanTrainingRows(coachPlan.trainingRows);
  }

  function buildCoachPlanModel(analytics) {
    const normalized = normalizeData(state.data);
    const settings = normalized.settings;
    const today = toISODate(new Date());
    const activeProgram = getActiveTrainingProgram(normalized);
    const activeProgramPreview = buildTrainingProgramPreview(activeProgram, normalized, today);
    const currentWeight = getCurrentWeightForCalculations(settings, normalized.entries);
    const macroSummaryFallback = summarizeMacroIntake([], settings, currentWeight);
    const todayActionPlan = analytics && analytics.todayActionPlan ? analytics.todayActionPlan : buildTodayActionPlan({
      settings,
      recovery: 0,
      plateauRisk: 0,
      averageBalance7: NaN,
      recentAverageSleep: NaN,
      recentWorkoutDays7: 0,
      latestExercise: null,
      activeProgramPreview,
      macroSummary: macroSummaryFallback,
      physiqueSummary: buildPhysiqueSummary(normalized.entries, settings),
    });
    const weeklyReport = analytics && analytics.weeklyReport ? analytics.weeklyReport : null;
    const riskAlerts = analytics && analytics.riskAlerts ? analytics.riskAlerts : null;
    const localAiModel = analytics && analytics.localAiModel ? analytics.localAiModel : null;
    const preparationPlan = analytics && analytics.preparationPlan ? analytics.preparationPlan : null;
    const exerciseSummaries = analytics && Array.isArray(analytics.exerciseSummaries) ? analytics.exerciseSummaries : summarizeExercises(normalized.workouts);
    const actionCards = Array.isArray(todayActionPlan.cards) ? todayActionPlan.cards.filter(Boolean) : [];
    const riskCards = riskAlerts && Array.isArray(riskAlerts.cards) ? riskAlerts.cards : [];
    const weeklyCards = weeklyReport && Array.isArray(weeklyReport.cards) ? weeklyReport.cards : [];

    const cards = []
      .concat(actionCards)
      .concat(weeklyCards.slice(0, 2))
      .concat(riskCards.slice(0, 1))
      .concat(localAiModel && Array.isArray(localAiModel.cards) ? localAiModel.cards.slice(0, 1) : [])
      .filter(Boolean)
      .slice(0, 8);

    const items = [];
    const pushItem = (text, tone = "warn") => {
      const clean = sanitizePlainText(text, 280);
      if (!clean || items.some((item) => item.text === clean)) {
        return;
      }
      items.push({ text: clean, tone });
    };

    actionCards.forEach((card) => pushItem(card.itemText || `${card.label}: ${card.value}. ${card.support || ""}`, card.tone || "warn"));
    if (riskAlerts && Array.isArray(riskAlerts.items)) {
      riskAlerts.items.slice(0, 3).forEach((alert) => pushItem(alert.recommendation || alert.message || alert.support, alert.tone || "warn"));
    }
    if (weeklyReport && Array.isArray(weeklyReport.actions)) {
      weeklyReport.actions.slice(0, 3).forEach((action) => pushItem(action, "warn"));
    }
    if (preparationPlan && preparationPlan.available && Array.isArray(preparationPlan.items)) {
      preparationPlan.items.slice(0, 2).forEach((item) => pushItem(`Cel z terminem: ${item}`, "good"));
    }
    if (localAiModel && localAiModel.available) {
      if (localAiModel.suggestedKcalShift) {
        pushItem(`Model lokalny: przez 7 dni ${localAiModel.suggestedKcalShift > 0 ? "dodaj" : "odejmij"} około ${Math.abs(localAiModel.suggestedKcalShift)} kcal dziennie i obserwuj trend masy.`, "warn");
      } else {
        pushItem(`Model lokalny: utrzymaj rytm, bo predykcja ${signedMetric(localAiModel.predictedDelta7, "kg/7 dni")} idzie zgodnie z celem.`, "good");
      }
    }

    const topRisk = riskAlerts && Array.isArray(riskAlerts.items)
      ? riskAlerts.items.find((item) => item.tone === "risk") || riskAlerts.items[0]
      : null;
    const mainDecision = actionCards.find((card) => card.tone === "risk") || actionCards.find((card) => card.tone === "warn") || actionCards[0] || null;
    const statusTone = topRisk && topRisk.tone === "risk"
      ? "risk"
      : mainDecision && mainDecision.tone === "warn"
        ? "warn"
        : "good";
    const statusClass = statusTone === "risk" ? "status-risk" : statusTone === "warn" ? "status-warn" : "status-unlocked";
    const statusLabel = statusTone === "risk" ? "Wymaga korekty" : statusTone === "warn" ? "Do dopilnowania" : "Plan stabilny";
    const summary = buildCoachPlanSummary({
      mainDecision,
      topRisk,
      weeklyReport,
      activeProgramPreview,
      settings,
      exerciseSummaries,
    });

    return {
      statusLabel,
      statusClass,
      summary,
      cards,
      items: items.slice(0, 8),
      trainingRows: buildCoachTrainingRows(activeProgramPreview, exerciseSummaries, normalized),
    };
  }

  function buildCoachPlanSummary(input) {
    const pieces = [];
    if (input.mainDecision) {
      pieces.push(`${input.mainDecision.value}: ${input.mainDecision.support || input.mainDecision.label}.`);
    }
    if (input.topRisk && input.topRisk.tone === "risk") {
      pieces.push(`Najpierw opanuj ryzyko: ${input.topRisk.label ? input.topRisk.label.toLowerCase() : "alert"}.`);
    }
    if (input.activeProgramPreview && input.activeProgramPreview.scheduleEntry) {
      pieces.push(`Dziś prowadzi jednostka ${input.activeProgramPreview.scheduleEntry.unitName}.`);
    } else if (input.exerciseSummaries && input.exerciseSummaries.length) {
      pieces.push("Bez ręcznego planu tygodniowego trener bazuje na historii ćwiczeń i ostatnich sygnałach.");
    }
    if (input.weeklyReport && input.weeklyReport.summary) {
      pieces.push(input.weeklyReport.summary);
    }
    if (!pieces.length) {
      pieces.push(`Tryb ${getPriorityModeConfig(resolvePriorityMode(input.settings)).label.toLowerCase()}: zacznij od pierwszego treningu i dziennego wpisu, a Plan zacznie działać jak trener.`);
    }
    return pieces.join(" ");
  }

  function buildCoachTrainingRows(activeProgramPreview, exerciseSummaries, data) {
    if (activeProgramPreview && Array.isArray(activeProgramPreview.exercisePlan) && activeProgramPreview.exercisePlan.length) {
      return activeProgramPreview.exercisePlan.slice(0, 10).map((item, index) => {
        const adaptive = item.adaptiveDecision || null;
        return {
          priority: `${index + 1}. ${item.exerciseName}`,
          signal: item.latestWorkout ? `Ostatnio: ${formatWorkoutPlan(item.latestWorkout)}` : "Brak historii tego ruchu",
          action: item.recommendedPlanText || "Zacznij od planu bazowego",
          reason: adaptive
            ? `${adaptive.label}: ${adaptive.reason}`
            : item.reason || "Rekomendacja wynika z zapisanego szablonu i historii użytkownika.",
          tone: adaptive && adaptive.tone ? adaptive.tone : "good",
        };
      });
    }

    const summaries = Array.isArray(exerciseSummaries) ? exerciseSummaries : [];
    if (!summaries.length) {
      return [];
    }

    const recentWorkouts = sortWorkouts((data && Array.isArray(data.workouts) ? data.workouts : []).slice()).slice(-120);
    return summaries.slice(0, 10).map((summary, index) => {
      const isCardio = summary.activityProfile && summary.activityProfile !== "strength";
      const latestWorkout = recentWorkouts.slice().reverse().find((workout) => workout.exerciseName && workout.exerciseName.toLowerCase() === summary.exerciseName.toLowerCase());
      const latestSignal = latestWorkout
        ? `${formatDisplayDate(latestWorkout.date)}: ${formatWorkoutPlan(latestWorkout)}`
        : `${summary.sessions30Days || 0} sesji / 30 dni`;
      let action = "Powtórz jakość";
      let reason = "Brakuje jeszcze stabilnej historii, więc najpierw utrwal technikę i zapisuj RPE po sesji.";
      let tone = "warn";

      if (isCardio) {
        if (summary.sessions30Days >= 3) {
          action = "Dodaj 5-10% czasu albo trzymaj tempo";
          reason = `Masz ${summary.sessions30Days} sesji w 30 dni. Progresuj małym krokiem, bez skoku intensywności.`;
          tone = "good";
        } else {
          action = "Zbuduj regularność 2-3x / tydz.";
          reason = "Dla cardio najpierw liczy się powtarzalność bodźca, dopiero potem tempo lub interwały.";
        }
      } else if (summary.sessions30Days >= 4) {
        action = "Spróbuj +1 powt. w głównej serii";
        reason = "Ruch wraca regularnie, więc najbezpieczniejsza progresja to mały wzrost powtórzeń przy tej samej jakości.";
        tone = "good";
      } else if (summary.sessions30Days >= 2) {
        action = "Zostań i wyrównaj serie";
        reason = "Są już dane, ale jeszcze za mało, żeby agresywnie dokładać. Najpierw ustabilizuj wykonanie.";
      }

      return {
        priority: `${index + 1}. ${summary.exerciseName}`,
        signal: latestSignal,
        action,
        reason,
        tone,
      };
    });
  }

  function renderCoachPlanTrainingRows(rows) {
    elements.coachPlanTrainingBody.replaceChildren();
    const safeRows = Array.isArray(rows) ? rows.filter(Boolean) : [];
    if (!safeRows.length) {
      elements.coachPlanTrainingBody.appendChild(createEmptyTableRow("Brak treningów do analizy. Dodaj pierwszą sesję albo wybierz szablon treningu.", 4));
      return;
    }

    safeRows.forEach((item) => {
      const row = document.createElement("tr");
      row.dataset.tone = item.tone || "warn";
      row.appendChild(createCoachPlanCell(item.priority));
      row.appendChild(createCoachPlanCell(item.signal));
      row.appendChild(createCoachPlanCell(item.action));
      row.appendChild(createCoachPlanCell(item.reason));
      elements.coachPlanTrainingBody.appendChild(row);
    });
  }

  function createCoachPlanCell(value) {
    const cell = document.createElement("td");
    cell.textContent = value || "Brak danych";
    return cell;
  }

  function renderCustomGoalTable(analytics) {
    if (!elements.customGoalBody) {
      return;
    }

    elements.customGoalBody.replaceChildren();
    syncCustomGoalFormMode();

    if (!state.unlocked) {
      elements.customGoalBody.appendChild(createEmptyTableRow("Zaloguj się, aby zarządzać celami użytkownika.", 5));
      return;
    }

    const customGoals = normalizeData(state.data).customGoals.filter((goal) => !goal.archived);
    if (!customGoals.length) {
      elements.customGoalBody.appendChild(createEmptyTableRow("Brak celów. Dodaj np. 10 podciągnięć, 5 km biegu albo pas 85 cm.", 5));
      return;
    }

    const progressItems = analytics && analytics.customGoalProgress && Array.isArray(analytics.customGoalProgress.items)
      ? analytics.customGoalProgress.items
      : [];
    const progressById = new Map(progressItems.map((item) => [item.id, item]));

    customGoals.forEach((goal) => {
      const progress = progressById.get(goal.id);
      const row = document.createElement("tr");
      const goalCell = document.createElement("td");
      const goalName = document.createElement("strong");
      goalName.textContent = goal.name;
      const goalMeta = document.createElement("span");
      goalMeta.className = "table-subtext";
      const goalMetaParts = [];
      if (goal.metric) {
        goalMetaParts.push(`Metryka: ${goal.metric}`);
      }
      if (goal.prepMode && goal.prepMode !== "none") {
        goalMetaParts.push(`Tryb: ${formatPreparationModeLabel(goal.prepMode)}`);
      }
      if (!goalMetaParts.length && goal.notes) {
        goalMetaParts.push(goal.notes);
      }
      goalMeta.textContent = goalMetaParts.join(" · ") || "Cel ogólny";
      goalCell.append(goalName, goalMeta);

      row.appendChild(goalCell);
      row.appendChild(createCell(formatCustomGoalTypeLabel(goal.type)));
      row.appendChild(createCell(progress ? formatCustomGoalProgressLine(progress) : "Brak danych z historii"));
      row.appendChild(createCell(goal.dueDate ? formatDisplayDate(goal.dueDate) : "Bez terminu"));

      const actionCell = document.createElement("td");
      const actionWrap = document.createElement("div");
      actionWrap.className = "table-actions";

      const editButton = document.createElement("button");
      editButton.type = "button";
      editButton.className = "edit-button";
      editButton.setAttribute("data-custom-goal-id", goal.id);
      editButton.setAttribute("data-custom-goal-action", "edit");
      editButton.textContent = "Edytuj";

      const deleteButton = document.createElement("button");
      deleteButton.type = "button";
      deleteButton.className = "delete-button";
      deleteButton.setAttribute("data-custom-goal-id", goal.id);
      deleteButton.setAttribute("data-custom-goal-action", "delete");
      deleteButton.textContent = "Usuń";

      actionWrap.append(editButton, deleteButton);
      actionCell.appendChild(actionWrap);
      row.appendChild(actionCell);
      elements.customGoalBody.appendChild(row);
    });
  }

  function setTemplateBuilderStatus(node, message, isError) {
    if (!node) {
      return;
    }
    node.textContent = message;
    node.classList.toggle("metric-tone-risk", Boolean(isError));
    node.classList.toggle("metric-tone-good", !isError);
  }

  function normalizeExerciseSearchKey(value, maxLength) {
    return sanitizePlainText(value || "", maxLength || 120)
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[\u0142\u0141]/g, "l")
      .replace(/[^a-z0-9]+/g, " ")
      .trim();
  }

  function getAiSelectedExerciseNames() {
    return Array.from(state.aiSelectedExerciseNames || []);
  }

  function renderTrainingGeneratorState() {
    if (!elements.trainingGeneratorContent || !elements.toggleTrainingGeneratorButton) {
      return;
    }
    elements.trainingGeneratorContent.classList.toggle("is-hidden", !state.trainingGeneratorExpanded);
    elements.toggleTrainingGeneratorButton.textContent = state.trainingGeneratorExpanded ? "Zwiń generator" : "Rozwiń generator";
    elements.toggleTrainingGeneratorButton.setAttribute("aria-expanded", state.trainingGeneratorExpanded ? "true" : "false");
  }

  function toggleTrainingGenerator() {
    state.trainingGeneratorExpanded = !state.trainingGeneratorExpanded;
    renderTrainingGeneratorState();
  }

  function handleAiExercisePickerChange(event) {
    const input = event.target.closest("input[data-ai-exercise-name]");
    if (!input) {
      return;
    }
    const exerciseName = input.getAttribute("data-ai-exercise-name");
    if (!exerciseName) {
      return;
    }
    if (input.checked) {
      state.aiSelectedExerciseNames.add(exerciseName);
    } else {
      state.aiSelectedExerciseNames.delete(exerciseName);
    }
    setTemplateBuilderStatus(elements.aiTemplateStatus, `Wybrano ${state.aiSelectedExerciseNames.size} ćwiczeń do generatora.`, false);
  }

  function getAiWorkoutFocus() {
    return safeSelectValue(elements.aiWorkoutFocusInput && elements.aiWorkoutFocusInput.value, [
      "full_body",
      "upper",
      "lower",
      "push",
      "pull",
      "legs",
      "chest",
      "back",
      "shoulders",
      "arms",
      "core",
      "endurance",
    ], "full_body");
  }

  function getAiFocusLabel(focus) {
    if (!elements.aiWorkoutFocusInput) {
      return "Full body";
    }
    const safeFocus = focus || getAiWorkoutFocus();
    const option = Array.from(elements.aiWorkoutFocusInput.options || []).find((item) => item.value === safeFocus);
    return option ? option.textContent : "Full body";
  }

  function getAiPriorityMode(settings) {
    const selectedMode = elements.aiPriorityModeInput ? elements.aiPriorityModeInput.value : "";
    return resolvePriorityMode(settings || normalizeData(state.data).settings, selectedMode);
  }

  function getActivePreparationGoals() {
    const data = normalizeData(state.data);
    return (Array.isArray(data.customGoals) ? data.customGoals : [])
      .map(normalizeCustomGoal)
      .filter((goal) => goal && !goal.archived && goalUsesPreparationMode(goal));
  }

  function populateAiPreparationGoalSelect(analytics) {
    if (!elements.aiPreparationGoalSelect) {
      return;
    }

    const currentValue = elements.aiPreparationGoalSelect.value;
    const progressItems = analytics && analytics.customGoalProgress && Array.isArray(analytics.customGoalProgress.items)
      ? analytics.customGoalProgress.items.filter(goalUsesPreparationMode)
      : [];
    const fallbackGoals = progressItems.length ? [] : getActivePreparationGoals().map((goal) => ({
      id: goal.id,
      label: goal.name,
      dueDate: goal.dueDate,
      prepMode: goal.prepMode,
    }));
    const items = progressItems.length ? progressItems : fallbackGoals;

    elements.aiPreparationGoalSelect.replaceChildren();
    const placeholder = document.createElement("option");
    placeholder.value = "";
    placeholder.textContent = items.length ? "Bez celu z deadline'em" : "Brak aktywnych celów z deadline'em";
    elements.aiPreparationGoalSelect.appendChild(placeholder);

    items.forEach((item) => {
      const option = document.createElement("option");
      const timing = buildPreparationGoalTiming(item);
      const deadlineText = item.dueDate ? ` · ${formatDisplayDate(item.dueDate)}` : "";
      option.value = item.id;
      option.textContent = `${item.label} · ${formatPreparationModeLabel(item.prepMode || "deadline")}${deadlineText} · ${timing.statusLabel}`;
      elements.aiPreparationGoalSelect.appendChild(option);
    });

    if (items.some((item) => item.id === currentValue)) {
      elements.aiPreparationGoalSelect.value = currentValue;
    }
  }

  function getSelectedAiPreparationGoal() {
    const goalId = elements.aiPreparationGoalSelect ? elements.aiPreparationGoalSelect.value : "";
    if (!goalId) {
      return null;
    }
    return getActivePreparationGoals().find((goal) => goal.id === goalId) || null;
  }

  function getSelectedAiPreparationGoalProgress(goal, settings) {
    if (!goal) {
      return null;
    }
    const data = normalizeData(state.data);
    const progress = buildCustomGoalProgressCards([goal], {
      entries: data.entries,
      workouts: data.workouts,
      settings: settings || data.settings,
    });
    return progress.items[0] || {
      id: goal.id,
      label: goal.name,
      type: goal.type,
      unit: goal.unit,
      metric: goal.metric,
      dueDate: goal.dueDate,
      prepMode: goal.prepMode || "none",
      createdAt: goal.createdAt,
      progress: 0,
      remainingDistance: null,
      hasData: false,
      reached: false,
    };
  }

  function inferFocusForPreparationGoal(goal, fallbackFocus) {
    const key = normalizeGoalSearchText(`${goal.metric || ""} ${goal.name || ""}`);
    if (goal.prepMode === "test_5k" || goal.type === "cardio_distance" || /5k|5 km|bieg|run|rower|bike|wydoln/.test(key)) {
      return "endurance";
    }
    if (/podciag|podciaganie|pull|wiosl|plecy|grzbiet/.test(key)) {
      return "pull";
    }
    if (/wycisk|bench|pomp|dip|dipy|klat|push/.test(key)) {
      return "push";
    }
    if (/przysiad|squat|nogi|udo|lydk|leg/.test(key)) {
      return "legs";
    }
    if (/martwy|deadlift|hinge/.test(key)) {
      return "pull";
    }
    if (goal.type === "body_measurement" || goal.prepMode === "vacation") {
      return fallbackFocus === "full_body" ? "full_body" : fallbackFocus;
    }
    return fallbackFocus || "full_body";
  }

  function inferPriorityModeForPreparationGoal(goal, settings, selectedMode) {
    if (PRIORITY_MODE_VALUES.includes(selectedMode)) {
      return selectedMode;
    }
    if (goal.prepMode === "vacation" || goal.type === "body_measurement") {
      return "cut";
    }
    if (goal.prepMode === "test_5k" || goal.type === "cardio_distance") {
      return "conditioning";
    }
    if (goal.prepMode === "competition" || goal.type === "strength_weight" || goal.type === "strength_reps") {
      return "strength";
    }
    if (goal.type === "rehab") {
      return "health";
    }
    return resolvePriorityMode(settings);
  }

  function getAiEffectiveContext(settingsArg) {
    const settings = settingsArg || normalizeData(state.data).settings;
    const selectedMode = elements.aiPriorityModeInput ? elements.aiPriorityModeInput.value : "";
    const baseFocus = getAiWorkoutFocus();
    const preparationGoal = getSelectedAiPreparationGoal();
    const preparationGoalProgress = getSelectedAiPreparationGoalProgress(preparationGoal, settings);
    const focus = preparationGoal ? inferFocusForPreparationGoal(preparationGoal, baseFocus) : baseFocus;
    const priorityMode = preparationGoal
      ? inferPriorityModeForPreparationGoal(preparationGoal, settings, selectedMode)
      : getAiPriorityMode(settings);

    return {
      settings,
      preparationGoal,
      preparationGoalProgress,
      focus,
      priorityMode,
    };
  }

  function renderAiModeRecommendations() {
    if (!elements.aiModeRecommendations) {
      return;
    }

    const settings = normalizeData(state.data).settings;
    const context = getAiEffectiveContext(settings);
    const focus = context.focus;
    const mode = context.priorityMode;
    const recommendations = buildPriorityModeRecommendations(mode, focus, settings);
    if (context.preparationGoal && context.preparationGoalProgress) {
      const timing = buildPreparationGoalTiming(context.preparationGoalProgress);
      const goalName = context.preparationGoal.name || context.preparationGoalProgress.label;
      recommendations.unshift(`Cel przygotowania: ${goalName}. ${buildPreparationTrainingAdvice(context.preparationGoalProgress, timing, settings)}`);
      recommendations.unshift(`AI ustawi akcent "${getAiFocusLabel(focus)}" i tryb "${formatPriorityModeLabel(mode)}" pod wybrany deadline.`);
    }
    renderTextList(
      elements.aiModeRecommendations,
      recommendations,
      "Wybierz tryb i typ jednostki, aby trener AI pokazał zalecenia."
    );
  }

  function getAiExerciseCandidatePool(options) {
    const settings = options && options.settings ? options.settings : normalizeData(state.data).settings;
    const context = getAiEffectiveContext(settings);
    const focus = options && options.focus ? options.focus : context.focus;
    const priorityMode = options && options.priorityMode ? options.priorityMode : context.priorityMode;
    const ignoreTextFilter = Boolean(options && options.ignoreTextFilter);
    const query = ignoreTextFilter ? "" : normalizeExerciseSearchKey(elements.aiExerciseFilterInput ? elements.aiExerciseFilterInput.value : "");

    return EXERCISE_LIBRARY.filter((exercise) => {
      if (!matchesExerciseFocus(exercise, focus, settings, priorityMode)) {
        return false;
      }
      if (!query) {
        return true;
      }
      return normalizeExerciseSearchKey(`${exercise.name} ${exercise.category}`).includes(query);
    });
  }

  function pruneAiSelectionForFocus() {
    const settings = normalizeData(state.data).settings;
    const context = getAiEffectiveContext(settings);
    const focus = context.focus;
    const priorityMode = context.priorityMode;
    const allowedNames = new Set(
      EXERCISE_LIBRARY
        .filter((exercise) => matchesExerciseFocus(exercise, focus, settings, priorityMode))
        .map((exercise) => exercise.name)
    );
    state.aiSelectedExerciseNames = new Set(
      Array.from(state.aiSelectedExerciseNames || []).filter((name) => allowedNames.has(name))
    );
  }

  function renderAiExercisePicker() {
    if (!elements.aiExercisePicker) {
      return;
    }

    const selected = new Set(getAiSelectedExerciseNames());
    const visibleExercises = getAiExerciseCandidatePool();

    elements.aiExercisePicker.replaceChildren();

    if (!visibleExercises.length) {
      const empty = document.createElement("p");
      empty.className = "filter-summary";
      empty.textContent = "Brak ćwiczeń pasujących do typu jednostki i filtra.";
      elements.aiExercisePicker.appendChild(empty);
      renderAiModeRecommendations();
      return;
    }

    visibleExercises.forEach((exercise) => {
      const label = document.createElement("label");
      label.className = "exercise-picker-option";

      const checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.setAttribute("data-ai-exercise-name", exercise.name);
      checkbox.checked = selected.has(exercise.name);

      const textWrap = document.createElement("span");
      const name = document.createElement("strong");
      name.textContent = exercise.name;
      const meta = document.createElement("span");
      meta.textContent = exercise.category;
      textWrap.append(name, meta);

      label.append(checkbox, textWrap);
      elements.aiExercisePicker.appendChild(label);
    });
    renderAiModeRecommendations();
  }

  function selectPopularAiExercises() {
    const settings = normalizeData(state.data).settings;
    const context = getAiEffectiveContext(settings);
    const focus = context.focus;
    const priorityMode = context.priorityMode;
    const limit = clamp(Math.round(Number(elements.aiExerciseLimitInput.value) || 6), 3, 12);
    const pool = getAiExerciseCandidatePool({ focus, settings, priorityMode });
    const result = chooseAiExercises(pool, settings.goal, focus, limit, settings, state.data, priorityMode, context.preparationGoal);

    state.aiSelectedExerciseNames.clear();
    result.selected.forEach((exercise) => state.aiSelectedExerciseNames.add(exercise.name));
    renderAiExercisePicker();
    const missingText = result.missingPatterns.length
        ? ` Brakuje wzorców: ${result.missingPatterns.join(", ")} - dodaj podobne ćwiczenia, jeśli masz je w sprzęcie.`
      : "";
    const prepText = context.preparationGoal ? ` oraz cel "${context.preparationGoal.name}"` : "";
    setTemplateBuilderStatus(elements.aiTemplateStatus, `Trener wybrał ${result.selected.length} najoptymalniejszych ćwiczeń pod tryb ${formatPriorityModeLabel(priorityMode).toLowerCase()}, jednostkę ${getAiFocusLabel(focus)}${prepText}.${missingText}`, false);
  }

  function clearAiExerciseSelection() {
    Array.from(elements.aiExercisePicker.querySelectorAll("input[data-ai-exercise-name]")).forEach((input) => {
      input.checked = false;
    });
    state.aiSelectedExerciseNames.clear();
    setTemplateBuilderStatus(elements.aiTemplateStatus, "Wyczyszczono wybór ćwiczeń do generatora.", false);
  }

  function isRunningAthleticExercise(exercise) {
    const profile = exercise && exercise.activityProfile ? exercise.activityProfile : "";
    const key = normalizeExerciseSearchKey(`${exercise && exercise.name ? exercise.name : exercise && exercise.exerciseName ? exercise.exerciseName : ""} ${exercise && exercise.category ? exercise.category : exercise && exercise.exerciseCategory ? exercise.exerciseCategory : ""}`);
    return RUNNING_ATHLETIC_PROFILES.has(profile) || /(bieg|skip|sprint|podbie|przebiez|przebież|fartlek|interwa|tempo|prog|rytmy|wieloskok|ankling)/.test(key);
  }

  function isCardioCrossTrainingExercise(exercise) {
    const profile = exercise && exercise.activityProfile ? exercise.activityProfile : "";
    const key = normalizeExerciseSearchKey(`${exercise && exercise.name ? exercise.name : exercise && exercise.exerciseName ? exercise.exerciseName : ""} ${exercise && exercise.category ? exercise.category : exercise && exercise.exerciseCategory ? exercise.exerciseCategory : ""}`);
    return CARDIO_MACHINE_PROFILES.has(profile) || /(rower|bike|cycling|orbitrek|elliptical|wioslarz|wioślarz|rowing|plywan|pływan|basen|sport|rekreacja)/.test(key);
  }

  function getRunningProfileRank(profile, priorityMode, preparationGoal) {
    const mode = resolvePriorityMode(null, priorityMode);
    if (mode === "health") {
      return {
        running_drills: 90,
        running: 84,
        running_strides: 74,
        fartlek: 66,
        tempo_run: 58,
        hill_sprint: 34,
        interval_run: 30,
        sprint: 18,
      }[profile] || 45;
    }

    if (preparationGoal && (preparationGoal.prepMode === "test_5k" || preparationGoal.type === "cardio_distance")) {
      return {
        running_drills: 92,
        running_strides: 88,
        interval_run: 86,
        tempo_run: 82,
        running: 78,
        hill_sprint: 72,
        fartlek: 68,
        sprint: 56,
      }[profile] || 45;
    }

    return {
      running_drills: 88,
      running_strides: 84,
      running: 80,
      tempo_run: 76,
      fartlek: 72,
      interval_run: 68,
      hill_sprint: 62,
      sprint: 48,
    }[profile] || 45;
  }

  function classifyTrainingPattern(exercise) {
    const profile = exercise && exercise.activityProfile ? exercise.activityProfile : "";
    const loadMode = exercise && exercise.loadMode ? exercise.loadMode : "";
    const key = normalizeExerciseSearchKey(`${exercise && exercise.name ? exercise.name : exercise && exercise.exerciseName ? exercise.exerciseName : ""} ${exercise && exercise.category ? exercise.category : exercise && exercise.exerciseCategory ? exercise.exerciseCategory : ""}`);
    if (profile === "mobility" || profile === "stretching" || /rozgrzew|mobiln|rozciag|stretch|cooldown|prehab/.test(key)) {
      return "mobility";
    }
    if (profile === "crossfit" || /crossfit|metcon|amrap|emom|wod|wall ball|double under|battle rope|sled push|thruster|complex/.test(key)) {
      return "crossfit";
    }
    if (profile === "endurance" || /wydoln|zone 2|z2|steady state/.test(key)) {
      return "cardio";
    }
    if (/bieg|marsz|rower|orbitrek|plywan|wioslarz|hiit|tabata|conditioning|sport|trekking|hiking|spacer/.test(key)) {
      return "cardio";
    }
    if (/brzuch|sit up|russian|hanging|core|farmer|carry|walk|back extension|turkish/.test(key)) {
      return "core";
    }
    if (/przysiad|squat|suwnic|wykrok|lunge|step up|prostowanie|pistol|box jump|sissy/.test(key)) {
      return "squat";
    }
    if (/martwy|rumunski|hip thrust|glute|good morning|uginanie nog|nordic|swing/.test(key)) {
      return "hinge";
    }
    if (/wycisk|press|pompki|dipy|chest|rozpietki|pec deck|thruster|landmine/.test(key)) {
      return "push";
    }
    if (/wiosl|row|podciag|sciag|pull|pulldown|pullover|shrug|face pull/.test(key)) {
      return "pull";
    }
    if (/biceps|curl|triceps|skull|french|modlitewnik|kickback|extension/.test(key)) {
      return "arms";
    }
    if (/barki|unoszenie|arnold|cuban|upright|odwrotne/.test(key)) {
      return "shoulders";
    }
    return loadMode === "cardio" ? "cardio" : "accessory";
  }

  function getAiFocusConfig(focus) {
    const map = {
      full_body: { required: ["squat", "hinge", "push", "pull", "core"], allowed: ["squat", "hinge", "push", "pull", "core", "shoulders", "arms", "accessory"] },
      upper: { required: ["push", "pull", "shoulders"], allowed: ["push", "pull", "shoulders", "arms", "core", "accessory"] },
      lower: { required: ["squat", "hinge", "core"], allowed: ["squat", "hinge", "core", "accessory"] },
      push: { required: ["push", "shoulders", "arms"], allowed: ["push", "shoulders", "arms"] },
      pull: { required: ["pull", "hinge", "arms"], allowed: ["pull", "hinge", "arms"] },
      legs: { required: ["squat", "hinge", "core"], allowed: ["squat", "hinge", "core"] },
      chest: { required: ["push"], allowed: ["push"] },
      back: { required: ["pull"], allowed: ["pull", "hinge"] },
      shoulders: { required: ["shoulders"], allowed: ["shoulders", "push", "pull"] },
      arms: { required: ["arms"], allowed: ["arms"] },
      core: { required: ["core"], allowed: ["core"] },
      endurance: { required: ["cardio"], allowed: ["cardio"] },
    };
    return map[focus] || map.full_body;
  }

  function matchesExerciseFocus(exercise, focus, settings, priorityMode) {
    const key = normalizeExerciseSearchKey(`${exercise.name} ${exercise.category}`);
    const pattern = classifyTrainingPattern(exercise);
    const config = getAiFocusConfig(focus);
    const goal = settings && settings.goal ? settings.goal : "performance";
    const mode = resolvePriorityMode(settings, priorityMode);

    if (mode === "health" && (["crossfit"].includes(pattern) || /box jump|sprint|thruster|max|plyo|amrap|emom/.test(key))) {
      return false;
    }

    if (!config.allowed.includes(pattern)) {
      if (focus === "full_body" && pattern === "cardio" && ["cut", "conditioning", "health"].includes(mode)) {
        return true;
      }
      return false;
    }

    if (focus === "push") {
      if (pattern === "arms") {
        return /triceps|pushdown|french|skull|kickback|extension|wasko|wąsko/.test(key);
      }
      return pattern === "push" || pattern === "shoulders";
    }
    if (focus === "pull") {
      if (pattern === "arms") {
        return /biceps|curl|hammer|modlitewnik|reverse curl/.test(key);
      }
      return pattern === "pull" || pattern === "hinge";
    }
    if (focus === "chest") {
      return /klat|chest|pec|bench|lawce|ławce|rozpiet|rozpięt|floor press|spoto/.test(key);
    }
    if (focus === "back") {
      return /plecy|wiosl|row|podciag|sciag|sciaganie|ściąg|pull|pulldown|pullover|martwy|rack pull|shrug/.test(key);
    }
    if (focus === "shoulders") {
      return /barki|shoulder|zolnierskie|arnold|unoszenie|face pull|cuban|upright|landmine|overhead|nad glowe|seated dumbbell/.test(key);
    }
    if (focus === "arms") {
      return /biceps|triceps|curl|pushdown|french|skull|modlitewnik|kickback|extension|reverse curl/.test(key);
    }
    if (focus === "core") {
      return pattern === "core";
    }
    if (focus === "crossfit") {
      return pattern === "crossfit" || exercise.loadMode === "bodyweight" || /kettlebell|burpee|box jump|thruster|farmer|swing|rower|wioslarz|wioślarz|air bike|skakanka|hiit|tabata/.test(key);
    }
    if (focus === "endurance") {
      return exercise.loadMode === "cardio" && !/sport|rekreacja|koszyk|pilka|piłka|badminton|tenis/.test(key);
    }
    if (goal === "fat_loss" && focus === "full_body" && pattern === "cardio") {
      return true;
    }

    return true;
  }

  function getRequiredPatternsForFocus(focus) {
    return getAiFocusConfig(focus).required;
  }

  function getExercisePriority(exercise, goal, focus, settings, data, priorityMode, preparationGoal) {
    const key = normalizeExerciseSearchKey(exercise.name);
    const goalKey = preparationGoal
      ? normalizeGoalSearchText(`${preparationGoal.metric || ""} ${preparationGoal.name || ""}`)
      : "";
    const exerciseGoalKey = normalizeGoalSearchText(`${exercise.name || ""} ${exercise.category || ""}`);
    const pattern = classifyTrainingPattern(exercise);
    const mode = resolvePriorityMode(settings, priorityMode);
    const latestWorkout = data && Array.isArray(data.workouts)
      ? findLatestWorkoutForExercise(data.workouts, exercise.name, "9999-12-31")
      : null;
    let score = 20;
    if (focus === "endurance") {
      if (isRunningAthleticExercise(exercise)) {
        score += getRunningProfileRank(exercise.activityProfile, mode, preparationGoal);
      }
      if (isCardioCrossTrainingExercise(exercise)) {
        score -= 34;
      }
      if (exercise.activityProfile === "endurance" && /bieg|run|z2|tlenow/.test(key)) {
        score += 32;
      }
      if (RUNNING_HARD_PROFILES.has(exercise.activityProfile) && mode === "health") {
        score -= 28;
      }
      if (RUNNING_HARD_PROFILES.has(exercise.activityProfile) && Number.isFinite(settings && settings.currentWeightKg) && settings.currentWeightKg >= 105) {
        score -= 16;
      }
    }
    if (/przysiad|martwy|wyciskanie lezac|podciag|wiosl|hip thrust|wyciskanie zolnierskie|dipy|rower|bieganie|wioslarz|crossfit wod|amrap|emom/.test(key)) {
      score += 18;
    }
    if (["squat", "hinge", "push", "pull"].includes(pattern)) {
      score += 12;
    }
    if (goal === "fat_loss" && ["cardio", "core"].includes(pattern)) {
      score += 7;
    }
    if (goal === "performance" && ["squat", "hinge", "push", "pull"].includes(pattern)) {
      score += 8;
    }
    if (goal === "muscle_gain" && ["push", "pull", "squat", "hinge", "shoulders", "arms"].includes(pattern)) {
      score += 6;
    }
    if (mode === "strength" && ["squat", "hinge", "push", "pull"].includes(pattern)) {
      score += 14;
    }
    if (mode === "mass" && ["push", "pull", "squat", "hinge", "shoulders", "arms", "accessory"].includes(pattern)) {
      score += 10;
    }
    if (mode === "cut" && ["cardio", "core", "crossfit"].includes(pattern)) {
      score += 9;
    }
    if (mode === "conditioning" && ["cardio", "crossfit", "core"].includes(pattern)) {
      score += 16;
    }
    if (mode === "health") {
      if (["mobility", "core", "cardio"].includes(pattern)) {
        score += 15;
      }
      if (["crossfit"].includes(pattern) || /box jump|sprint|thruster|max|plyo/.test(key)) {
        score -= 18;
      }
    }
    if (preparationGoal) {
      if (goalKey && (exerciseGoalKey.includes(goalKey) || goalKey.includes(exerciseGoalKey))) {
        score += 26;
      }
      if ((preparationGoal.prepMode === "test_5k" || preparationGoal.type === "cardio_distance") && pattern === "cardio") {
        score += 22;
        if (["running_drills", "running_strides", "interval_run", "tempo_run", "running", "fartlek"].includes(exercise.activityProfile)) {
          score += 18;
        }
        if (isCardioCrossTrainingExercise(exercise)) {
          score -= 18;
        }
      }
      if ((preparationGoal.prepMode === "vacation" || preparationGoal.type === "body_measurement") && ["squat", "hinge", "push", "pull", "cardio", "core"].includes(pattern)) {
        score += 10;
      }
      if ((preparationGoal.prepMode === "competition" || preparationGoal.type === "strength_weight" || preparationGoal.type === "strength_reps") && ["squat", "hinge", "push", "pull"].includes(pattern)) {
        score += 14;
      }
      if (preparationGoal.type === "rehab" && ["mobility", "core", "cardio"].includes(pattern)) {
        score += 12;
      }
    }
    if ((focus === "push" && ["push", "shoulders", "arms"].includes(pattern)) ||
        (focus === "pull" && ["pull", "hinge", "arms"].includes(pattern)) ||
        (focus === "legs" && ["squat", "hinge", "core"].includes(pattern)) ||
        (focus === "upper" && ["push", "pull", "shoulders", "arms"].includes(pattern)) ||
        (focus === "lower" && ["squat", "hinge", "core"].includes(pattern)) ||
        (focus === "chest" && pattern === "push") ||
        (focus === "back" && ["pull", "hinge"].includes(pattern)) ||
        (focus === "shoulders" && pattern === "shoulders") ||
        (focus === "arms" && pattern === "arms") ||
        (focus === "core" && pattern === "core") ||
        (focus === "crossfit" && ["crossfit", "cardio", "core"].includes(pattern)) ||
        (focus === "endurance" && pattern === "cardio")) {
      score += 14;
    }
    if (latestWorkout) {
      score += 5;
    }
    if (Number.isFinite(settings && settings.currentWeightKg) && settings.currentWeightKg >= 110 && ["box jump", "sprint", "pistol"].some((riskKey) => key.includes(riskKey))) {
      score -= 8;
    }
    if (exercise.loadMode === "cardio" && goal !== "fat_loss" && !["cut", "conditioning", "health"].includes(mode) && focus !== "endurance" && focus !== "crossfit") {
      score -= 7;
    }
    return score;
  }

  function getAiGoalLabel(goal) {
    if (goal === "fat_loss") return "redukcja";
    if (goal === "muscle_gain") return "budowa masy";
    return "sila i wydolność";
  }

  function buildAiTemplateExercise(exercise, goal, focus, settings, data, priorityMode, preparationGoal) {
    const meta = resolveExerciseMeta({
      exerciseName: exercise.name,
      activityProfile: exercise.activityProfile,
      exerciseCategory: exercise.category,
      loadMode: exercise.loadMode,
    });
    const pattern = classifyTrainingPattern(exercise);
    const compound = ["squat", "hinge", "push", "pull"].includes(pattern);
    const cardio = meta.loadMode === "cardio";
    const mode = resolvePriorityMode(settings, priorityMode);
    const latestWorkout = data && Array.isArray(data.workouts)
      ? findLatestWorkoutForExercise(data.workouts, exercise.name, "9999-12-31")
      : null;
    const historyLoad = Number.isFinite(latestWorkout && latestWorkout.weightKg) ? latestWorkout.weightKg : 0;
    let sets = cardio
      ? pattern === "crossfit" ? 4 : 1
      : goal === "performance" && compound ? 5
        : focus === "arms" || focus === "shoulders" ? 3
          : goal === "fat_loss" ? 3
            : compound ? 4 : 3;
    let reps = cardio
      ? pattern === "crossfit" ? 10 : 1
      : goal === "performance" && compound ? 5
        : focus === "arms" || focus === "shoulders" ? 12
          : goal === "fat_loss" ? 12
            : compound ? 8 : 12;
    let durationMin = cardio
      ? focus === "endurance"
        ? Math.max(meta.defaultDurationMin || 35, goal === "fat_loss" ? 45 : 35)
        : pattern === "crossfit"
          ? clamp(Math.round(meta.defaultDurationMin || 22), 12, 35)
          : goal === "fat_loss" ? Math.max(meta.defaultDurationMin || 25, 30) : meta.defaultDurationMin || 25
      : meta.defaultDurationMin || (compound ? 18 : 12);
    let intensityRpe = focus === "endurance"
      ? 6
      : pattern === "crossfit"
        ? 8
        : goal === "performance" && compound ? 8
          : goal === "fat_loss" ? 7 : meta.defaultIntensityRpe || 7.5;

    if (mode === "strength" && !cardio) {
      sets = compound ? Math.max(sets, 5) : Math.max(sets, 3);
      reps = compound ? clamp(Math.min(reps, 5), 3, 6) : clamp(reps, 6, 10);
      durationMin = Math.max(durationMin, compound ? 20 : 12);
      intensityRpe = compound ? Math.max(intensityRpe, 8) : Math.max(intensityRpe, 7);
    } else if (mode === "mass" && !cardio) {
      sets = compound ? clamp(Math.max(sets, 4), 4, 5) : clamp(Math.max(sets, 3), 3, 4);
      reps = compound ? clamp(Math.max(reps, 8), 8, 10) : clamp(Math.max(reps, 10), 10, 15);
      intensityRpe = Math.max(intensityRpe, 7.5);
    } else if (mode === "cut") {
      sets = cardio ? sets : Math.min(sets, 3);
      reps = cardio ? reps : clamp(Math.max(reps, 10), 8, 15);
      durationMin = cardio ? Math.max(durationMin, focus === "endurance" ? 40 : 25) : durationMin;
      intensityRpe = clamp(cardio ? intensityRpe : Math.min(intensityRpe, 7.2), 5, 8);
    } else if (mode === "conditioning") {
      if (cardio || pattern === "crossfit") {
        sets = pattern === "crossfit" ? Math.max(sets, 4) : sets;
        durationMin = Math.max(durationMin, focus === "endurance" ? 45 : 28);
        intensityRpe = pattern === "crossfit" ? 8 : clamp(Math.max(intensityRpe, 6.5), 6, 8);
      } else {
        sets = Math.min(sets, compound ? 4 : 3);
        reps = clamp(Math.max(reps, 8), 8, 15);
        intensityRpe = clamp(intensityRpe, 6, 7.5);
      }
    } else if (mode === "health") {
      sets = cardio ? 1 : clamp(Math.min(sets, compound ? 3 : 2), 1, 3);
      reps = cardio ? reps : clamp(Math.max(reps, 8), 8, 12);
      durationMin = cardio ? clamp(Math.max(durationMin, 20), 20, 45) : Math.min(durationMin, compound ? 16 : 12);
      intensityRpe = clamp(Math.min(intensityRpe, 6.5), 4.5, 6.5);
    }

    if (preparationGoal) {
      if (preparationGoal.prepMode === "test_5k" || preparationGoal.type === "cardio_distance") {
        if (cardio) {
          durationMin = Math.max(durationMin, focus === "endurance" ? 38 : 28);
          intensityRpe = clamp(pattern === "cardio" ? Math.max(intensityRpe, 6.5) : intensityRpe, 5.5, 8);
        } else {
          sets = Math.min(sets, compound ? 3 : 2);
          reps = clamp(Math.max(reps, 8), 8, 12);
          intensityRpe = clamp(Math.min(intensityRpe, 7), 5.5, 7);
        }
      } else if (preparationGoal.prepMode === "competition" || preparationGoal.type === "strength_weight" || preparationGoal.type === "strength_reps") {
        if (!cardio && compound) {
          sets = Math.max(sets, 5);
          reps = clamp(Math.min(reps, preparationGoal.type === "strength_reps" ? 8 : 5), 3, 8);
          durationMin = Math.max(durationMin, 20);
          intensityRpe = Math.max(intensityRpe, 8);
        } else if (!cardio) {
          sets = Math.max(sets, 3);
          reps = clamp(reps, 8, 12);
          intensityRpe = clamp(intensityRpe, 6.5, 7.5);
        }
      } else if (preparationGoal.prepMode === "vacation" || preparationGoal.type === "body_measurement") {
        if (cardio) {
          durationMin = Math.max(durationMin, 30);
          intensityRpe = clamp(intensityRpe, 6, 7.5);
        } else {
          sets = compound ? clamp(sets, 3, 4) : clamp(sets, 2, 4);
          reps = clamp(Math.max(reps, 10), 8, 15);
          intensityRpe = clamp(intensityRpe, 6.5, 7.8);
        }
      } else if (preparationGoal.type === "rehab") {
        sets = cardio ? 1 : Math.min(sets, 2);
        reps = cardio ? reps : clamp(Math.max(reps, 10), 8, 15);
        durationMin = cardio ? clamp(durationMin, 18, 35) : Math.min(durationMin, 12);
        intensityRpe = clamp(Math.min(intensityRpe, 6.5), 4.5, 6.5);
      }
    }

    const weightKg = meta.loadMode === "external" && Number.isFinite(historyLoad) && historyLoad > 0 ? round(historyLoad, 1) : 0;
    const loadNote = meta.loadMode === "external" && !weightKg
      ? "dobierz startowo ciężar na RPE 6-7, bez walki o rekord"
      : latestWorkout
        ? "bazuje na ostatnio zapisanym ciężarze"
        : "zostaw zapas techniczny";
    let specificNote = "";

    if (cardio && RUNNING_ATHLETIC_PROFILES.has(meta.activityProfile)) {
      sets = clamp(Math.round(exercise.defaultSets || meta.defaultSets || sets || 1), 1, 12);
      reps = 1;
      durationMin = clamp(Math.round(exercise.defaultDurationMin || meta.defaultDurationMin || durationMin), 8, 60);
      intensityRpe = clamp(Number(exercise.defaultIntensityRpe || meta.defaultIntensityRpe || intensityRpe), 4, 9.5);

      if (meta.activityProfile === "running_drills") {
        sets = clamp(sets, 3, 6);
        durationMin = clamp(durationMin, 10, 18);
        intensityRpe = clamp(intensityRpe, 4.5, 6);
        specificNote = "Technika: krótki kontakt z podłożem, wysoka postawa, pełna kontrola. To nie jest blok na zmęczenie.";
      } else if (meta.activityProfile === "running_strides") {
        sets = clamp(sets, 4, 8);
        durationMin = clamp(durationMin, 10, 18);
        intensityRpe = clamp(intensityRpe, 6.5, 7.5);
        specificNote = "Rytmy: narastaj do szybkiego, luźnego biegu i wracaj marszem/truchtem. Bez zajeżdżania nóg.";
      } else if (meta.activityProfile === "sprint") {
        sets = clamp(sets, 4, 8);
        durationMin = clamp(durationMin, 14, 24);
        intensityRpe = clamp(intensityRpe, 8, 9.2);
        specificNote = "Sprint: pełny odpoczynek 90-180 s, koniec serii gdy spada szybkość lub technika.";
      } else if (meta.activityProfile === "hill_sprint") {
        sets = clamp(sets, 5, 10);
        durationMin = clamp(durationMin, 14, 24);
        intensityRpe = clamp(intensityRpe, 7.5, 8.8);
        specificNote = "Podbiegi: krótkie odcinki, mocna praca ramion, wracaj w dół spokojnie. Nie rób na obolałych łydkach.";
      } else if (meta.activityProfile === "interval_run") {
        sets = clamp(sets, 4, 10);
        durationMin = clamp(durationMin, 24, 42);
        intensityRpe = clamp(intensityRpe, 7.5, 8.6);
        specificNote = "Interwały: jeden główny akcent dnia. Przerwa w truchcie lub marszu, tempo równe od pierwszego do ostatniego powtórzenia.";
      } else if (meta.activityProfile === "tempo_run") {
        sets = clamp(sets, 1, 4);
        durationMin = clamp(durationMin, 22, 45);
        intensityRpe = clamp(intensityRpe, 7, 8);
        specificNote = "Tempo/próg: wysiłek kontrolowany, bez sprintu. Masz czuć, że mógłbyś utrzymać jeszcze kilka minut.";
      } else if (meta.activityProfile === "fartlek") {
        sets = clamp(sets, 1, 6);
        durationMin = clamp(durationMin, 24, 45);
        intensityRpe = clamp(intensityRpe, 6.5, 7.8);
        specificNote = "Fartlek: zmieniaj tempo, ale zostaw technikę. Szybkie fragmenty mają być dynamiczne, nie chaotyczne.";
      }
    }

    return {
      exerciseName: exercise.name,
      exerciseCategory: meta.category,
      loadMode: meta.loadMode,
      activityProfile: meta.activityProfile,
      sets,
      reps,
      weightKg,
      distanceKm: null,
      elevationGainM: null,
      durationMin,
      intensityRpe: round(intensityRpe, 1),
      notes: `Trener: ${pattern}, tryb ${formatPriorityModeLabel(mode).toLowerCase()}, cel ${getAiGoalLabel(goal)}${preparationGoal ? `, przygotowanie ${preparationGoal.name}` : ""}, ${loadNote}.${specificNote ? ` ${specificNote}` : ""}`,
    };
  }

  function chooseEnduranceAiExercises(pool, goal, limit, settings, data, priorityMode, preparationGoal) {
    const safeLimit = clamp(Math.round(Number(limit) || 6), 3, 12);
    const selected = [];
    const usedNames = new Set();
    const mode = resolvePriorityMode(settings, priorityMode);
    const prefer5k = preparationGoal && (preparationGoal.prepMode === "test_5k" || preparationGoal.type === "cardio_distance");
    const sorted = pool
      .filter((exercise) => exercise.loadMode === "cardio")
      .slice()
      .sort((first, second) => getExercisePriority(second, goal, "endurance", settings, data, priorityMode, preparationGoal) - getExercisePriority(first, goal, "endurance", settings, data, priorityMode, preparationGoal));

    function addBest(predicate) {
      if (selected.length >= safeLimit) {
        return false;
      }
      const candidate = sorted.find((exercise) => !usedNames.has(exercise.name) && predicate(exercise));
      if (!candidate) {
        return false;
      }
      selected.push(candidate);
      usedNames.add(candidate.name);
      return true;
    }

    function addBestProfile(profile) {
      return addBest((exercise) => exercise.activityProfile === profile);
    }

    addBestProfile("running_drills");
    if (safeLimit >= 5) {
      addBest((exercise) => exercise.activityProfile === "running_drills" && !/praca ramion|drabinka|płotki|plotki/.test(normalizeExerciseSearchKey(exercise.name)));
    }
    addBestProfile("running_strides");

    if (mode === "health") {
      addBestProfile("running");
      addBestProfile("fartlek");
      addBestProfile("fast_walk");
    } else if (prefer5k || mode === "conditioning") {
      addBestProfile("interval_run");
      addBestProfile("tempo_run");
      if (safeLimit >= 6 && Number(settings && settings.currentWeightKg || 80) < 105) {
        addBestProfile("hill_sprint");
      }
      addBestProfile("running");
    } else {
      addBestProfile("tempo_run");
      addBestProfile("running");
      addBestProfile("fartlek");
      if (safeLimit >= 6 && Number(settings && settings.currentWeightKg || 80) < 100) {
        addBestProfile("hill_sprint");
      }
    }

    sorted.forEach((exercise) => {
      if (selected.length >= safeLimit || usedNames.has(exercise.name)) {
        return;
      }
      const hardCount = selected.filter((item) => RUNNING_HARD_PROFILES.has(item.activityProfile)).length;
      if (RUNNING_HARD_PROFILES.has(exercise.activityProfile) && hardCount >= (safeLimit >= 6 ? 2 : 1)) {
        return;
      }
      if (isCardioCrossTrainingExercise(exercise) && selected.some(isRunningAthleticExercise)) {
        return;
      }
      selected.push(exercise);
      usedNames.add(exercise.name);
    });

    if (selected.length < safeLimit) {
      sorted.forEach((exercise) => {
        if (selected.length < safeLimit && !usedNames.has(exercise.name)) {
          selected.push(exercise);
          usedNames.add(exercise.name);
        }
      });
    }

    return {
      selected,
      missingPatterns: selected.length ? [] : ["cardio biegowe"],
    };
  }

  function chooseAiExercises(pool, goal, focus, limit, settings, data, priorityMode, preparationGoal) {
    const requiredPatterns = getRequiredPatternsForFocus(focus);
    const selected = [];
    const usedNames = new Set();
    const byPattern = new Map();
    const safeLimit = clamp(Math.round(Number(limit) || 6), 3, 12);

    if (focus === "endurance") {
      return chooseEnduranceAiExercises(pool, goal, safeLimit, settings, data, priorityMode, preparationGoal);
    }

    pool.forEach((exercise) => {
      const pattern = classifyTrainingPattern(exercise);
      if (!byPattern.has(pattern)) {
        byPattern.set(pattern, []);
      }
      byPattern.get(pattern).push(exercise);
    });

    byPattern.forEach((items) => {
      items.sort((first, second) => getExercisePriority(second, goal, focus, settings, data, priorityMode, preparationGoal) - getExercisePriority(first, goal, focus, settings, data, priorityMode, preparationGoal));
    });

    requiredPatterns.forEach((pattern) => {
      const candidate = (byPattern.get(pattern) || []).find((exercise) => !usedNames.has(exercise.name));
      if (candidate && selected.length < safeLimit) {
        selected.push(candidate);
        usedNames.add(candidate.name);
      }
    });

    pool
      .slice()
      .sort((first, second) => getExercisePriority(second, goal, focus, settings, data, priorityMode, preparationGoal) - getExercisePriority(first, goal, focus, settings, data, priorityMode, preparationGoal))
      .forEach((exercise) => {
        if (selected.length >= safeLimit || usedNames.has(exercise.name)) {
          return;
        }
        const pattern = classifyTrainingPattern(exercise);
        const heavyPatternCount = selected.filter((item) => ["squat", "hinge"].includes(classifyTrainingPattern(item))).length;
        if (heavyPatternCount >= 2 && ["squat", "hinge"].includes(pattern) && !["lower", "legs", "full_body", "crossfit"].includes(focus)) {
          return;
        }
        selected.push(exercise);
        usedNames.add(exercise.name);
      });

    const coveredPatterns = new Set(selected.map(classifyTrainingPattern));
    const missingPatterns = requiredPatterns.filter((pattern) => !coveredPatterns.has(pattern));
    return { selected, missingPatterns };
  }

  function buildAiSupportExercise(name, activityProfile, durationMin, intensityRpe, notes) {
    const meta = resolveExerciseMeta({
      exerciseName: name,
      activityProfile,
      exerciseCategory: activityProfile === "stretching" ? "regeneracja i mobilność" : "prehab i mobilność",
      loadMode: "cardio",
    });

    return {
      exerciseName: name,
      exerciseCategory: meta.category,
      loadMode: meta.loadMode,
      activityProfile: meta.activityProfile,
      sets: 1,
      reps: 1,
      weightKg: 0,
      distanceKm: null,
      elevationGainM: null,
      durationMin,
      intensityRpe,
      notes,
    };
  }

  function buildAiWarmupExercises(selectedExercises, focus) {
    const patterns = new Set(selectedExercises.map(classifyTrainingPattern));
    const hasLower = patterns.has("squat") || patterns.has("hinge");
    const hasUpper = patterns.has("push") || patterns.has("pull") || patterns.has("shoulders") || patterns.has("arms");
    const isMetcon = focus === "crossfit" || patterns.has("crossfit");
    const isEndurance = focus === "endurance" || (patterns.has("cardio") && selectedExercises.every((exercise) => classifyTrainingPattern(exercise) === "cardio"));
    const primaryStrength = selectedExercises.find((exercise) => ["squat", "hinge", "push", "pull"].includes(classifyTrainingPattern(exercise)));
    const warmup = [
      buildAiSupportExercise(
        isEndurance ? "Rozgrzewka tlenowa - 8 min bardzo lekko" : "Rozgrzewka ogólna - 6-8 min lekko",
        "mobility",
        isEndurance ? 8 : 7,
        4,
        "Podnies temperaturę ciała, oddychaj spokojnie i nie wchodz jeszcze w zmęczenie."
      ),
    ];

    if (isEndurance) {
      warmup.push(buildAiSupportExercise(
        "Mobilność biegowa - biodra, kostki, łydki",
        "mobility",
        6,
        4.5,
        "Krazenia bioder, wymachy nog, aktywacja stopy i 2-3 lekkie skipy bez zmęczenia."
      ));
      warmup.push(buildAiSupportExercise(
        "Przebiezki narastajace 3-4x60 m",
        "running_strides",
        8,
        6.5,
        "Każda przebieżka szybciej, ale luźno. Pełny powrót marszem lub truchtem przed częścią główną."
      ));
    }

    if (hasLower) {
      warmup.push(buildAiSupportExercise(
        "Mobilizacja bioder, kostek i aktywacja posladkow",
        "mobility",
        7,
        4.5,
        "Krążenia bioder, przysiad z pauza, glute bridge i lekka aktywacja core przed seria robocza."
      ));
    }

    if (hasUpper) {
      warmup.push(buildAiSupportExercise(
        "Mobilizacja lopatek, rotatorow i barkow",
        "mobility",
        7,
        4.5,
        "Band pull apart, face pull gumą, rotacje zewnętrzne i 1-2 lekkie serie ruchu docelowego."
      ));
    }

    if (isMetcon) {
      warmup.push(buildAiSupportExercise(
        "Progresja WOD - technika ruchow bez zmęczenia",
        "mobility",
        8,
        5,
        "Przejdź każdy ruch z planu w wersji lekkiej. Celem jest rytm i zakres ruchu, nie tempo."
      ));
    } else if (primaryStrength) {
      warmup.push(buildAiSupportExercise(
        `Serie narastajace do: ${primaryStrength.name}`,
        "mobility",
        8,
        5,
        "Wykonaj 2-4 serie narastające około 40/60/80% ciężaru roboczego. Nie licz ich jako serie robocze."
      ));
    }

    return warmup.slice(0, 4);
  }

  function buildAiCooldownExercises(selectedExercises, focus) {
    const patterns = new Set(selectedExercises.map(classifyTrainingPattern));
    const hasLower = patterns.has("squat") || patterns.has("hinge");
    const hasUpper = patterns.has("push") || patterns.has("pull") || patterns.has("shoulders") || patterns.has("arms");
    const isEndurance = focus === "endurance" || patterns.has("cardio");
    const cooldown = [
      buildAiSupportExercise(
        isEndurance ? "Schlodzenie - 5-8 min bardzo lekko" : "Schlodzenie - oddech i lekki marsz",
        "stretching",
        isEndurance ? 8 : 5,
        3,
        "Zejdz z tetna, oddychaj nosem i zakoncz trening bez gwaltownego urwania intensywnosci."
      ),
    ];

    if (hasLower) {
      cooldown.push(buildAiSupportExercise(
        "Rozciąganie: biodra, dwugłowe, czworogłowe i łydki",
        "stretching",
        8,
        3,
        "Po 30-45 s spokojnego zakresu na strone. Bez dociskania bolu."
      ));
    }

    if (hasUpper) {
      cooldown.push(buildAiSupportExercise(
        "Rozciąganie: klatka, najszerszy, barki i przedramiona",
        "stretching",
        8,
        3,
        "Utrzymaj spokojny oddech i rozluznij obszary najmocniej pracujace w planie."
      ));
    }

    if (isEndurance) {
      cooldown.push(buildAiSupportExercise(
        "Biegowy cooldown - łydki, biodra, dwugłowe i oddech",
        "stretching",
        8,
        3,
        "Spokojne zakresy po 30-45 s, bez agresywnego dociskania. Priorytet: zejscie z napiecia i tetna."
      ));
    }

    if (!hasLower && !hasUpper) {
      cooldown.push(buildAiSupportExercise(
        "Mobilność końcowa - kręgosłup piersiowy i oddech",
        "stretching",
        6,
        3,
        "Lekka mobilność po cardio albo core, bez rozciągania na siłę."
      ));
    }

    return cooldown.slice(0, 3);
  }

  async function saveTemplateFromBuilder(templateDraft, statusNode, successMessage) {
    const normalizedTemplate = normalizeTemplate(templateDraft);
    if (!normalizedTemplate) {
      throw new Error("Nie udało się utworzyć poprawnego szablonu. Sprawdź nazwę i ćwiczenia.");
    }

    const existingIndex = state.data.templates.findIndex((template) => template.name.toLowerCase() === normalizedTemplate.name.toLowerCase());
    const finalTemplate = {
      ...normalizedTemplate,
      id: existingIndex >= 0 ? state.data.templates[existingIndex].id : normalizedTemplate.id,
      updatedAt: new Date().toISOString(),
    };

    if (existingIndex >= 0 && !window.confirm(`Szablon "${finalTemplate.name}" już istnieje. Zastapic go nowa wersja?`)) {
      return null;
    }

    if (existingIndex >= 0) {
      state.data.templates[existingIndex] = finalTemplate;
    } else {
      state.data.templates.push(finalTemplate);
    }

    state.data.templates = sortTemplates(state.data.templates).slice(-150);
    state.templateEditMode = false;
    await persistVault();
    elements.templateSelect.value = finalTemplate.id;
    elements.templateNameInput.value = finalTemplate.name;
    renderDashboard();
    elements.templateSelect.value = finalTemplate.id;
    renderTemplateExerciseEditor(finalTemplate);
    setTemplateBuilderStatus(statusNode, successMessage, false);
    showStatus(successMessage);
    return finalTemplate;
  }

  function parseWorkoutTextToExercises(text) {
    const rawText = (typeof text === "string" ? text : "")
      .replace(/[<>]/g, "")
      .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, " ")
      .slice(0, 4000)
      .trim();
    if (!rawText) {
      return [];
    }

    const fullKey = normalizeExerciseSearchKey(rawText, 4000);
    const initialLines = rawText
      .replace(/\r/g, "\n")
      .replace(/[\u2022\u00b7]/g, "\n")
      .split(/\n|;/)
      .map((line) => line.trim())
      .filter((line) => line.length >= 3);
    const candidateLines = initialLines.length > 1 ? initialLines : [];

    if (candidateLines.length < 2) {
      EXERCISE_LIBRARY.forEach((exercise) => {
        const key = normalizeExerciseSearchKey(exercise.name);
        if (fullKey.includes(key)) {
          candidateLines.push(exercise.name);
        }
      });
    }

    const parsed = [];
    const seen = new Set();
    candidateLines.forEach((line) => {
      const exercise = detectExerciseFromLine(line);
      if (!exercise) {
        return;
      }
      const params = parseExerciseParamsFromLine(line, exercise);
      const key = `${exercise.name}|${params.sets}|${params.reps}|${params.weightKg}`;
      if (seen.has(key)) {
        return;
      }
      seen.add(key);
      parsed.push({
        exerciseName: exercise.name,
        exerciseCategory: exercise.category,
        loadMode: exercise.loadMode,
        activityProfile: exercise.activityProfile,
        sets: params.sets,
        reps: params.reps,
        weightKg: params.weightKg,
        distanceKm: params.distanceKm,
        elevationGainM: null,
        durationMin: params.durationMin,
        intensityRpe: params.intensityRpe,
        notes: sanitizePlainText(line, 180),
      });
    });

    return parsed.slice(0, 16);
  }

  function detectExerciseFromLine(line) {
    const key = normalizeExerciseSearchKey(line);
    if (!key) {
      return null;
    }

    const exact = EXERCISE_LIBRARY
      .slice()
      .sort((first, second) => second.name.length - first.name.length)
      .find((exercise) => key.includes(normalizeExerciseSearchKey(exercise.name)));
    if (exact) {
      return exact;
    }

    const cleanedName = line
      .replace(/\d+\s*[xX]\s*\d+.*/g, "")
      .replace(/\d+\s*(serii|serie|sets?|powt|reps?|kg|min).*/gi, "")
      .replace(/[-\u2013\u2014:]+/g, " ")
      .trim();
    if (cleanedName.length < 3 || !/[\p{L}]/u.test(cleanedName)) {
      return null;
    }

    const meta = resolveExerciseMeta({ exerciseName: cleanedName, activityProfile: "strength" });
    return {
      name: sanitizePlainText(cleanedName, 80),
      category: meta.category,
      loadMode: meta.loadMode,
      activityProfile: meta.activityProfile,
      defaultSets: meta.defaultSets,
      defaultReps: meta.defaultReps,
      defaultDurationMin: meta.defaultDurationMin,
      defaultIntensityRpe: meta.defaultIntensityRpe,
    };
  }

  function parseExerciseParamsFromLine(line, exercise) {
    const meta = resolveExerciseMeta({
      exerciseName: exercise.name,
      activityProfile: exercise.activityProfile,
      exerciseCategory: exercise.category,
      loadMode: exercise.loadMode,
    });
    const normalized = line.replace(",", ".");
    const crossMatch = normalized.match(/(\d{1,2})\s*[xX\u00d7]\s*(\d{1,2})(?:\s*[-\u2013]\s*(\d{1,2}))?/);
    const setsMatch = normalized.match(/(\d{1,2})\s*(?:serii|serie|sets?)(?:\s*(?:po|x)\s*(\d{1,2}))?/i);
    const repsMatch = normalized.match(/(\d{1,2})\s*(?:powt|reps?)/i);
    const weightMatch = normalized.match(/(\d{1,3}(?:\.\d+)?)\s*kg/i);
    const durationMatch = normalized.match(/(\d{1,3})\s*(?:min|minute|minut)/i);
    const distanceMatch = normalized.match(/(\d{1,3}(?:\.\d+)?)\s*km/i);
    const rpeMatch = normalized.match(/rpe\s*(\d{1,2}(?:\.\d)?)/i);

    const sets = crossMatch ? Number(crossMatch[1]) : setsMatch ? Number(setsMatch[1]) : meta.defaultSets;
    const reps = crossMatch ? Number(crossMatch[3] || crossMatch[2]) : setsMatch && setsMatch[2] ? Number(setsMatch[2]) : repsMatch ? Number(repsMatch[1]) : meta.defaultReps;

    return {
      sets: meta.loadMode === "cardio" ? 1 : clamp(Math.round(sets || meta.defaultSets || 3), 1, 20),
      reps: meta.loadMode === "cardio" ? 1 : clamp(Math.round(reps || meta.defaultReps || 10), 1, 50),
      weightKg: weightMatch ? clamp(Number(weightMatch[1]), 0, 600) : 0,
      durationMin: durationMatch ? clamp(Math.round(Number(durationMatch[1])), 5, 240) : meta.defaultDurationMin,
      distanceKm: distanceMatch ? clamp(Number(distanceMatch[1]), 0, 300) : null,
      intensityRpe: rpeMatch ? clamp(Number(rpeMatch[1]), 4, 10) : meta.defaultIntensityRpe,
    };
  }

  async function handleCreateTemplateFromText() {
    if (!requireUnlocked()) {
      return;
    }

    try {
      const exercises = parseWorkoutTextToExercises(elements.templatePdfTextInput.value);
      if (!exercises.length) {
        throw new Error("Nie rozpoznano ćwiczeń w tekście. Wklej plan w formacie np. Przysiad 4x8 100 kg.");
      }
      const name = sanitizePlainText(elements.templatePdfNameInput.value || elements.templateNameInput.value, 80) || `Import tekstu ${formatDisplayDate(toISODate(new Date()))}`;
      await saveTemplateFromBuilder({
        id: window.crypto.randomUUID ? window.crypto.randomUUID() : `template-import-${Date.now()}`,
        name,
        updatedAt: new Date().toISOString(),
        exercises,
      }, elements.templatePdfStatus, `Utworzono szablon "${name}" z ${exercises.length} ćwiczeniami.`);
    } catch (error) {
      setTemplateBuilderStatus(elements.templatePdfStatus, error.message || "Nie udało się utworzyć szablonu z tekstu.", true);
      showStatus(error.message || "Nie udało się utworzyć szablonu z tekstu.", true);
    }
  }

  async function handleImportTemplatePdf() {
    if (!requireUnlocked()) {
      return;
    }

    const file = elements.templatePdfInput.files && elements.templatePdfInput.files[0];
    if (!file) {
      setTemplateBuilderStatus(elements.templatePdfStatus, "Wybierz plik PDF z planem treningowym.", true);
      return;
    }

    try {
      setTemplateBuilderStatus(elements.templatePdfStatus, "Czytam PDF lokalnie w przegladarce...", false);
      const bytes = new Uint8Array(await file.arrayBuffer());
      const extractedText = await extractTextFromPdfBytes(bytes);
      elements.templatePdfTextInput.value = extractedText.slice(0, 4000);
      if (!extractedText || extractedText.length < 12) {
        throw new Error("Nie udało się znaleźć warstwy tekstowej w PDF. Jeśli to skan, wklej tekst planu ręcznie.");
      }
      const defaultName = file.name.replace(/\.pdf$/i, "").slice(0, 70);
      if (!elements.templatePdfNameInput.value.trim()) {
        elements.templatePdfNameInput.value = defaultName || "Plan z PDF";
      }
      await handleCreateTemplateFromText();
    } catch (error) {
      setTemplateBuilderStatus(elements.templatePdfStatus, error.message || "Nie udało się zaimportować PDF.", true);
      showStatus(error.message || "Nie udało się zaimportować PDF.", true);
    }
  }

  async function extractTextFromPdfBytes(bytes) {
    const raw = decodeLatin1Bytes(bytes);
    const chunks = [extractPdfTextTokens(raw)];
    const streamRanges = findPdfStreamRanges(raw);

    for (const range of streamRanges.slice(0, 80)) {
      const streamBytes = bytes.slice(range.start, range.end);
      chunks.push(extractPdfTextTokens(decodeLatin1Bytes(streamBytes)));
      const inflated = await tryInflatePdfStream(streamBytes);
      if (inflated) {
        chunks.push(extractPdfTextTokens(decodeLatin1Bytes(new Uint8Array(inflated))));
      }
    }

    return chunks
      .join("\n")
      .replace(/\u0000/g, " ")
      .replace(/[ \t]{2,}/g, " ")
      .replace(/\n{3,}/g, "\n\n")
      .trim();
  }

  function decodeLatin1Bytes(bytes) {
    let output = "";
    const chunkSize = 8192;
    for (let index = 0; index < bytes.length; index += chunkSize) {
      output += String.fromCharCode.apply(null, bytes.slice(index, index + chunkSize));
    }
    return output;
  }

  function findPdfStreamRanges(raw) {
    const ranges = [];
    const streamPattern = /stream\r?\n/g;
    let match = streamPattern.exec(raw);
    while (match) {
      let start = match.index + match[0].length;
      const end = raw.indexOf("endstream", start);
      if (end < 0) {
        break;
      }
      if (raw.charCodeAt(start) === 13 && raw.charCodeAt(start + 1) === 10) {
        start += 2;
      } else if (raw.charCodeAt(start) === 10) {
        start += 1;
      }
      ranges.push({ start, end });
      streamPattern.lastIndex = end + 9;
      match = streamPattern.exec(raw);
    }
    return ranges;
  }

  async function tryInflatePdfStream(streamBytes) {
    if (typeof DecompressionStream === "undefined") {
      return null;
    }
    for (const format of ["deflate", "deflate-raw"]) {
      try {
        const inflatedStream = new Blob([streamBytes]).stream().pipeThrough(new DecompressionStream(format));
        return await new Response(inflatedStream).arrayBuffer();
      } catch (_error) {
        // Try the next supported browser format.
      }
    }
    return null;
  }

  function extractPdfTextTokens(content) {
    const tokens = [];
    const literalPattern = /\((?:\\.|[^\\)]){2,}\)/g;
    let match = literalPattern.exec(content);
    while (match) {
      tokens.push(decodePdfLiteralString(match[0].slice(1, -1)));
      match = literalPattern.exec(content);
    }

    const hexPattern = /<([0-9A-Fa-f]{8,})>/g;
    match = hexPattern.exec(content);
    while (match) {
      const decoded = decodePdfHexString(match[1]);
      if (decoded) {
        tokens.push(decoded);
      }
      match = hexPattern.exec(content);
    }

    return tokens
      .map((token) => token.replace(/\s+/g, " ").trim())
      .filter((token) => token.length >= 2 && /[\p{L}0-9]/u.test(token))
      .join("\n");
  }

  function decodePdfLiteralString(value) {
    return value
      .replace(/\\([nrtbf\\()])/g, (_match, code) => {
        const map = { n: "\n", r: "\r", t: "\t", b: "\b", f: "\f", "\\": "\\", "(": "(", ")": ")" };
        return map[code] || code;
      })
      .replace(/\\([0-7]{1,3})/g, (_match, octal) => String.fromCharCode(parseInt(octal, 8)))
      .replace(/\\\r?\n/g, "");
  }

  function decodePdfHexString(hex) {
    try {
      const pairs = hex.match(/[0-9A-Fa-f]{2}/g) || [];
      if (pairs.length >= 2 && pairs[0].toLowerCase() === "fe" && pairs[1].toLowerCase() === "ff") {
        let output = "";
        for (let index = 2; index < pairs.length - 1; index += 2) {
          output += String.fromCharCode(parseInt(`${pairs[index]}${pairs[index + 1]}`, 16));
        }
        return output;
      }
      return pairs.map((pair) => String.fromCharCode(parseInt(pair, 16))).join("");
    } catch (_error) {
      return "";
    }
  }

  async function handleGenerateAiTemplate() {
    if (!requireUnlocked()) {
      return;
    }

    try {
      const selectedNames = getAiSelectedExerciseNames();
      if (!selectedNames.length) {
        throw new Error("Zaznacz ćwiczenia, które możesz wykonywać, albo użyj przycisku \"Wybierz najoptymalniejszy\".");
      }

      const selectedSet = new Set(selectedNames);
      const settings = normalizeData(state.data).settings;
      const context = getAiEffectiveContext(settings);
      const focus = context.focus;
      const priorityMode = context.priorityMode;
      const preparationGoal = context.preparationGoal;
      const limit = clamp(Math.round(Number(elements.aiExerciseLimitInput.value) || 6), 3, 12);
      const pool = EXERCISE_LIBRARY.filter((exercise) => selectedSet.has(exercise.name) && matchesExerciseFocus(exercise, focus, settings, priorityMode));
      const result = chooseAiExercises(pool, settings.goal, focus, limit, settings, state.data, priorityMode, preparationGoal);
      if (!result.selected.length) {
        throw new Error("Nie udało się dobrać ćwiczeń z aktualnego wyboru. Sprawdź typ jednostki albo kliknij \"Wybierz najoptymalniejszy\".");
      }

      const mainExercises = result.selected.map((exercise) => buildAiTemplateExercise(exercise, settings.goal, focus, settings, state.data, priorityMode, preparationGoal));
      const warmupExercises = buildAiWarmupExercises(result.selected, focus);
      const cooldownExercises = buildAiCooldownExercises(result.selected, focus);
      const exercises = [
        ...warmupExercises,
        ...mainExercises,
        ...cooldownExercises,
      ];
      const focusLabel = getAiFocusLabel(focus);
      const modeLabel = formatPriorityModeLabel(priorityMode);
      const prepLabel = preparationGoal ? preparationGoal.name : "";
      const name = sanitizePlainText(elements.aiTemplateNameInput.value || elements.templateNameInput.value, 80) || (prepLabel ? `${prepLabel}` : `${focusLabel} ${modeLabel}`);
      const missingText = result.missingPatterns.length
        ? ` Brakuje kategorii: ${result.missingPatterns.join(", ")} - dodaj takie ćwiczenia do wyboru, aby plan był pełniejszy.`
        : "";
      const modeAdvice = ` Tryb ${modeLabel.toLowerCase()} zmienił priorytet: ${getPriorityModeConfig(priorityMode).trainingText}.`;
      const prepAdvice = preparationGoal && context.preparationGoalProgress
        ? ` Cel przygotowania "${preparationGoal.name}" dopasował jednostkę do deadline'u.`
        : "";

      await saveTemplateFromBuilder({
        id: window.crypto.randomUUID ? window.crypto.randomUUID() : `template-ai-${Date.now()}`,
        name,
        updatedAt: new Date().toISOString(),
        exercises,
      }, elements.aiTemplateStatus, `Wygenerowano szablon "${name}": ${warmupExercises.length} rozgrzewkowe, ${mainExercises.length} główne, ${cooldownExercises.length} końcowe.${modeAdvice}${prepAdvice}${missingText}`);
    } catch (error) {
      setTemplateBuilderStatus(elements.aiTemplateStatus, error.message || "Nie udało się wygenerować szablonu.", true);
      showStatus(error.message || "Nie udało się wygenerować szablonu.", true);
    }
  }

  function populateTemplateSelect() {
    const currentValue = elements.templateSelect.value;
    elements.templateSelect.replaceChildren();

    const placeholder = document.createElement("option");
    placeholder.value = "";
    placeholder.textContent = state.data.templates.length ? "Wybierz szablon" : "Brak zapisanych szablonów";
    elements.templateSelect.appendChild(placeholder);

    state.data.templates.forEach((template) => {
      const option = document.createElement("option");
      option.value = template.id;
      option.textContent = template.name;
      elements.templateSelect.appendChild(option);
    });

    if (state.data.templates.some((template) => template.id === currentValue)) {
      elements.templateSelect.value = currentValue;
    }
  }

  function renderTemplateTable(templates) {
    if (!elements.templateBody) {
      return;
    }

    elements.templateBody.replaceChildren();
    if (state.unlocked) {
      const filteredTemplates = filterTemplates(templates);
      if (templates.length && !filteredTemplates.length) {
        elements.templateBody.appendChild(createEmptyTableRow("Brak szablonów pasujących do aktywnych filtrów.", 4));
        return;
      }
      templates = filteredTemplates;
    } else if (elements.templateFilterSummary) {
      elements.templateFilterSummary.textContent = "Filtry szablonów uaktywnią się po zalogowaniu.";
    }

    if (!state.unlocked) {
      elements.templateBody.appendChild(createEmptyTableRow("Zaloguj się, aby zarządzać szablonami treningów.", 4));
      return;
    }

    if (!templates.length) {
      elements.templateBody.appendChild(createEmptyTableRow("Brak szablonów. Zapisz jeden z gotowego dnia treningowego.", 4));
      return;
    }

    templates.forEach((template) => {
      const row = document.createElement("tr");
      row.appendChild(createCell(template.name));
      row.appendChild(createCell(`${template.exercises.length} ćw. | ${buildExercisePreview(template.exercises, 3)}`));
      row.appendChild(createCell(formatTimestamp(template.updatedAt)));

      const actionCell = document.createElement("td");
      const actionWrap = document.createElement("div");
      actionWrap.className = "table-actions";

      const selectButton = document.createElement("button");
      selectButton.type = "button";
      selectButton.className = "edit-button";
      selectButton.setAttribute("data-template-id", template.id);
      selectButton.setAttribute("data-template-action", "select");
      selectButton.textContent = "Podgląd";

      const applyButton = document.createElement("button");
      applyButton.type = "button";
      applyButton.className = "edit-button";
      applyButton.setAttribute("data-template-id", template.id);
      applyButton.setAttribute("data-template-action", "apply");
      applyButton.textContent = "Wczytaj";

      const deleteButton = document.createElement("button");
      deleteButton.type = "button";
      deleteButton.className = "delete-button";
      deleteButton.setAttribute("data-template-id", template.id);
      deleteButton.setAttribute("data-template-action", "delete");
      deleteButton.textContent = "Usuń";

      actionWrap.append(selectButton, applyButton, deleteButton);
      actionCell.appendChild(actionWrap);
      row.appendChild(actionCell);

      elements.templateBody.appendChild(row);
    });
  }

  function renderTemplateExerciseEditor(templateArg) {
    const template = templateArg || getSelectedTemplate();
    renderTemplatePreviewVisibility(template);
    syncTemplateExerciseFormMode(template);
    renderTemplateExerciseTable(template);
  }

  function renderTemplatePreviewVisibility(templateArg) {
    if (!elements.templatePreviewBlock) {
      return;
    }
    const template = templateArg || getSelectedTemplate();
    const shouldShow = state.unlocked && state.templatePreviewVisible && Boolean(template);
    elements.templatePreviewBlock.classList.toggle("is-hidden", !shouldShow);
  }

  function showTemplatePreview(template, editMode) {
    if (!template) {
      state.templatePreviewVisible = false;
      state.templateEditMode = false;
      renderTemplateExerciseEditor(null);
      return;
    }
    state.templatePreviewVisible = true;
    state.templateEditMode = Boolean(editMode);
    clearTemplateExerciseDraft();
    renderTemplateExerciseEditor(template);
  }

  function syncTemplateExecutionDateFromWorkout() {
    if (!elements.templateExecutionDateInput || !elements.workoutDateInput) {
      return;
    }
    const nextDate = elements.workoutDateInput.value || elements.templateExecutionDateInput.value || toISODate(new Date());
    elements.workoutDateInput.value = nextDate;
    elements.templateExecutionDateInput.value = nextDate;
  }

  function handleWorkoutDateChange() {
    if (elements.templateExecutionDateInput && elements.workoutDateInput.value) {
      elements.templateExecutionDateInput.value = elements.workoutDateInput.value;
    }
    renderDashboard();
  }

  function handleTemplateExecutionDateChange() {
    if (elements.workoutDateInput && elements.templateExecutionDateInput.value) {
      elements.workoutDateInput.value = elements.templateExecutionDateInput.value;
    }
    renderTemplateExecutionPanel(getSelectedTemplate());
    renderDashboard();
  }

  function renderTemplateExecutionPanel(templateArg) {
    if (!elements.templateExecutionBlock || !elements.templateExecutionBody) {
      return;
    }

    syncTemplateExecutionDateFromWorkout();
    const template = templateArg || getSelectedTemplate();
    const activeDate = elements.templateExecutionDateInput ? elements.templateExecutionDateInput.value : toISODate(new Date());
    const canShow = state.unlocked && Boolean(template);
    elements.templateExecutionBlock.classList.toggle("is-hidden", !canShow);
    elements.templateExecutionBody.replaceChildren();

    if (!canShow) {
      if (elements.templateExecutionStatus) {
        elements.templateExecutionStatus.textContent = state.unlocked ? "Brak szablonu" : "Zablokowane";
        elements.templateExecutionStatus.className = "status-pill status-locked";
      }
      return;
    }

    const existingCount = countTemplateExecutionWorkouts(template.id, activeDate);
    elements.templateExecutionTitle.textContent = `Wykonanie: ${template.name}`;
    elements.templateExecutionStatus.textContent = existingCount ? `${existingCount} zapisanych serii` : "Gotowe do wpisania";
    elements.templateExecutionStatus.className = `status-pill ${existingCount ? "status-unlocked" : "status-progress"}`;
    elements.templateExecutionSummary.textContent = `Data ${formatDisplayDate(activeDate)}. Zmieniaj wartości w tabeli podczas treningu, a potem kliknij "Zapisz wykonanie dnia".`;

    if (!template.exercises.length) {
      elements.templateExecutionBody.appendChild(createEmptyTableRow("Ten szablon jest pusty. Otwórz edycję stałą i dodaj ćwiczenia.", 7));
      return;
    }

    template.exercises.forEach((exercise, exerciseIndex) => {
      const meta = resolveExerciseMeta(exercise);
      const plannedSets = meta.loadMode === "cardio"
        ? 1
        : clamp(Math.round(Number(exercise.sets) || 1), 1, 20);
      for (let setIndex = 0; setIndex < plannedSets; setIndex += 1) {
        const savedWorkout = findTemplateExecutionWorkout(template.id, activeDate, exerciseIndex, setIndex);
        appendTemplateExecutionRow(template, exercise, exerciseIndex, setIndex, savedWorkout);
      }
    });
  }

  function appendTemplateExecutionRow(template, exercise, exerciseIndex, setIndex, savedWorkout) {
    const meta = resolveExerciseMeta(exercise);
    const row = document.createElement("tr");
    row.dataset.templateExecutionRow = "true";
    row.dataset.templateId = template.id;
    row.dataset.exerciseIndex = String(exerciseIndex);
    row.dataset.setIndex = String(setIndex);
    row.dataset.activityProfile = meta.activityProfile;
    row.dataset.loadMode = meta.loadMode;

    row.appendChild(createCell(exercise.exerciseName));
    const seriesCell = createCell(meta.loadMode === "cardio" ? "Aktywność" : String(setIndex + 1));
    seriesCell.dataset.templateExecutionSeriesCell = "true";
    row.appendChild(seriesCell);
    row.appendChild(createCell(formatWorkoutPlan(exercise)));

    const firstValue = meta.loadMode === "cardio"
      ? savedWorkout && Number.isFinite(savedWorkout.distanceKm) ? savedWorkout.distanceKm : exercise.distanceKm
      : savedWorkout && Number.isFinite(savedWorkout.reps) ? savedWorkout.reps : exercise.reps;
    const secondValue = meta.loadMode === "cardio"
      ? savedWorkout && Number.isFinite(savedWorkout.durationMin) ? savedWorkout.durationMin : exercise.durationMin
      : savedWorkout && Number.isFinite(savedWorkout.weightKg) ? savedWorkout.weightKg : exercise.weightKg;
    const rpeValue = savedWorkout && Number.isFinite(savedWorkout.intensityRpe)
      ? savedWorkout.intensityRpe
      : exercise.intensityRpe;

    row.appendChild(createTemplateExecutionInputCell(meta.loadMode === "cardio" ? "distanceKm" : "reps", firstValue, meta.loadMode === "cardio" ? "km" : "powt."));
    row.appendChild(createTemplateExecutionInputCell(meta.loadMode === "cardio" ? "durationMin" : "weightKg", secondValue, meta.loadMode === "cardio" ? "min" : "kg"));
    row.appendChild(createTemplateExecutionInputCell("intensityRpe", rpeValue, "RPE"));

    const actionCell = document.createElement("td");
    actionCell.className = "table-actions";
    if (meta.loadMode !== "cardio") {
      const addButton = document.createElement("button");
      addButton.type = "button";
      addButton.className = "edit-button";
      addButton.dataset.templateExecutionAction = "add-row";
      addButton.textContent = "+ seria";
      actionCell.appendChild(addButton);
    }
    const removeButton = document.createElement("button");
    removeButton.type = "button";
    removeButton.className = "delete-button";
    removeButton.dataset.templateExecutionAction = "remove-row";
    removeButton.textContent = "Pomiń";
    actionCell.appendChild(removeButton);
    row.appendChild(actionCell);
    elements.templateExecutionBody.appendChild(row);
  }

  function createTemplateExecutionInputCell(field, value, label) {
    const cell = document.createElement("td");
    const input = document.createElement("input");
    input.type = "number";
    input.className = "table-input template-execution-input";
    input.dataset.templateExecutionField = field;
    input.placeholder = label;
    if (field === "reps") {
      input.min = "1";
      input.max = "80";
      input.step = "1";
    } else if (field === "weightKg") {
      input.min = "0";
      input.max = "600";
      input.step = "0.5";
    } else if (field === "distanceKm") {
      input.min = "0";
      input.max = "300";
      input.step = "0.1";
    } else if (field === "durationMin") {
      input.min = "1";
      input.max = "240";
      input.step = "1";
    } else {
      input.min = "4";
      input.max = "10";
      input.step = "0.5";
    }
    const numericValue = value === "" || value === null || typeof value === "undefined" ? NaN : Number(value);
    input.value = Number.isFinite(numericValue) ? String(round(numericValue, field === "reps" || field === "durationMin" ? 0 : 2)) : "";
    cell.appendChild(input);
    return cell;
  }

  function buildTemplateExecutionMarker(templateId, exerciseIndex, setIndex) {
    return `[BTO_TEMPLATE:${templateId}:${exerciseIndex}:${setIndex}]`;
  }

  function workoutHasTemplateExecutionMarker(workout, templateId, exerciseIndex, setIndex) {
    const marker = typeof exerciseIndex === "number"
      ? buildTemplateExecutionMarker(templateId, exerciseIndex, setIndex)
      : `[BTO_TEMPLATE:${templateId}:`;
    return String(workout && workout.notes || "").includes(marker);
  }

  function findTemplateExecutionWorkout(templateId, date, exerciseIndex, setIndex) {
    return state.data.workouts.find((workout) =>
      workout.date === date && workoutHasTemplateExecutionMarker(workout, templateId, exerciseIndex, setIndex)
    ) || null;
  }

  function countTemplateExecutionWorkouts(templateId, date) {
    return state.data.workouts.filter((workout) =>
      workout.date === date && workoutHasTemplateExecutionMarker(workout, templateId)
    ).length;
  }

  function readTemplateExecutionNumber(row, field, fallback) {
    const input = row.querySelector(`[data-template-execution-field="${field}"]`);
    const rawValue = input ? input.value : "";
    if (rawValue === "" || rawValue === null || typeof rawValue === "undefined") {
      return Number.isFinite(Number(fallback)) ? Number(fallback) : null;
    }
    const value = Number(rawValue);
    return Number.isFinite(value) ? value : null;
  }

  async function handleSaveTemplateExecution() {
    if (!requireUnlocked()) {
      return;
    }

    const template = getSelectedTemplate();
    if (!template) {
      showStatus("Wybierz szablon, który chcesz wykonać.", true);
      return;
    }

    const targetDate = elements.templateExecutionDateInput && elements.templateExecutionDateInput.value
      ? elements.templateExecutionDateInput.value
      : elements.workoutDateInput.value || toISODate(new Date());
    const rows = Array.from(elements.templateExecutionBody.querySelectorAll("[data-template-execution-row]"));
    if (!rows.length) {
      showStatus("Nie ma żadnych serii do zapisania.", true);
      return;
    }

    try {
      const settings = normalizeData(state.data).settings;
      const currentWeight = getCurrentWeightForCalculations(settings, state.data.entries);
      const rowCountsByExerciseIndex = rows.reduce((counts, row) => {
        const exerciseIndex = Number(row.dataset.exerciseIndex);
        counts.set(exerciseIndex, (counts.get(exerciseIndex) || 0) + 1);
        return counts;
      }, new Map());
      const generated = rows.map((row) => {
        const exerciseIndex = Number(row.dataset.exerciseIndex);
        const setIndex = Number(row.dataset.setIndex);
        const exercise = template.exercises[exerciseIndex];
        if (!exercise) {
          return null;
        }
        const meta = resolveExerciseMeta(exercise);
        const marker = buildTemplateExecutionMarker(template.id, exerciseIndex, setIndex);
        const executionExercise = {
          ...exercise,
          sets: meta.loadMode === "cardio" ? exercise.sets : 1,
          reps: meta.loadMode === "cardio" ? exercise.reps : readTemplateExecutionNumber(row, "reps", exercise.reps),
          weightKg: meta.loadMode === "cardio" ? exercise.weightKg : readTemplateExecutionNumber(row, "weightKg", exercise.weightKg) || 0,
          distanceKm: meta.loadMode === "cardio" ? readTemplateExecutionNumber(row, "distanceKm", exercise.distanceKm) : exercise.distanceKm,
          durationMin: meta.loadMode === "cardio"
            ? readTemplateExecutionNumber(row, "durationMin", exercise.durationMin)
            : Number.isFinite(Number(exercise.durationMin))
              ? Math.max(1, round(Number(exercise.durationMin) / Math.max(rowCountsByExerciseIndex.get(exerciseIndex) || 1, 1), 0))
              : exercise.durationMin,
          intensityRpe: readTemplateExecutionNumber(row, "intensityRpe", exercise.intensityRpe),
          notes: `${marker} ${exercise.notes || ""}`.trim(),
        };
        if (meta.loadMode !== "cardio" && (!Number.isFinite(Number(executionExercise.reps)) || Number(executionExercise.reps) <= 0)) {
          throw new Error(`Uzupełnij powtórzenia dla: ${exercise.exerciseName}, seria ${setIndex + 1}.`);
        }
        const workout = buildWorkoutFromTemplateExercise(executionExercise, targetDate, settings, currentWeight);
        workout.notes = executionExercise.notes;
        return workout;
      }).filter(Boolean);

      if (!generated.length) {
        throw new Error("Nie udało się zbudować wykonania z tabeli.");
      }

      state.data.workouts = sortWorkouts(
        state.data.workouts
          .filter((workout) => !(workout.date === targetDate && workoutHasTemplateExecutionMarker(workout, template.id)))
          .concat(generated)
      ).slice(-MAX_ENTRIES * 4);

      if (elements.workoutDateInput) {
        elements.workoutDateInput.value = targetDate;
      }
      await persistVault();
      renderDashboard();
      showStatus(`Zapisano wykonanie "${template.name}" na ${formatDisplayDate(targetDate)}.`);
    } catch (error) {
      showStatus(error.message || "Nie udało się zapisać wykonania szablonu.", true);
    }
  }

  async function handleClearTemplateExecution() {
    if (!requireUnlocked()) {
      return;
    }
    const template = getSelectedTemplate();
    const targetDate = elements.templateExecutionDateInput && elements.templateExecutionDateInput.value
      ? elements.templateExecutionDateInput.value
      : elements.workoutDateInput.value || toISODate(new Date());
    if (!template) {
      showStatus("Wybierz szablon, którego wykonanie chcesz wyczyścić.", true);
      return;
    }

    const count = countTemplateExecutionWorkouts(template.id, targetDate);
    if (!count) {
      showStatus("Ten szablon nie ma jeszcze zapisanego wykonania dla wybranej daty.", true);
      return;
    }
    if (!window.confirm(`Usuńąć ${count} zapisanych serii z szablonu "${template.name}" dla dnia ${formatDisplayDate(targetDate)}?`)) {
      return;
    }

    try {
      state.data.workouts = state.data.workouts.filter((workout) =>
        !(workout.date === targetDate && workoutHasTemplateExecutionMarker(workout, template.id))
      );
      await persistVault();
      renderDashboard();
      showStatus("Wyczyszczono wykonanie szablonu dla wybranej daty.");
    } catch (error) {
      showStatus(error.message || "Nie udało się wyczyścić wykonania szablonu.", true);
    }
  }

  function handleTemplateExecutionTableAction(event) {
    const button = event.target.closest("[data-template-execution-action]");
    if (!button) {
      return;
    }
    const row = button.closest("[data-template-execution-row]");
    if (row && button.dataset.templateExecutionAction === "add-row") {
      const template = getSelectedTemplate();
      const exerciseIndex = Number(row.dataset.exerciseIndex);
      const exercise = template && template.exercises ? template.exercises[exerciseIndex] : null;
      if (!template || !exercise) {
        return;
      }
      const rowsForExercise = Array.from(elements.templateExecutionBody.querySelectorAll(`[data-template-execution-row][data-exercise-index="${exerciseIndex}"]`));
      const nextSetIndex = rowsForExercise.reduce((max, item) => Math.max(max, Number(item.dataset.setIndex) || 0), -1) + 1;
      appendTemplateExecutionRow(template, exercise, exerciseIndex, nextSetIndex, null);
      renumberTemplateExecutionRows(exerciseIndex);
      return;
    }
    if (row && button.dataset.templateExecutionAction === "remove-row") {
      const exerciseIndex = Number(row.dataset.exerciseIndex);
      row.remove();
      renumberTemplateExecutionRows(exerciseIndex);
    }
  }

  function renumberTemplateExecutionRows(exerciseIndex) {
    Array.from(elements.templateExecutionBody.querySelectorAll(`[data-template-execution-row][data-exercise-index="${exerciseIndex}"]`))
      .forEach((row, index) => {
        if (row.dataset.loadMode === "cardio") {
          return;
        }
        row.dataset.setIndex = String(index);
        const seriesCell = row.querySelector("[data-template-execution-series-cell]");
        if (seriesCell) {
          seriesCell.textContent = String(index + 1);
        }
      });
  }

  function renderTemplateExerciseTable(template) {
    elements.templateExerciseBody.replaceChildren();
    const editMode = state.unlocked && Boolean(template) && state.templateEditMode;

    if (!state.unlocked) {
      elements.templateExerciseBody.appendChild(createEmptyTableRow("Zaloguj się, aby edytować ćwiczenia w szablonach.", 6));
      return;
    }

    if (!template) {
      elements.templateExerciseBody.appendChild(createEmptyTableRow("Wybierz zapisany szablon, aby zmienić ćwiczenia i ich kolejność.", 6));
      return;
    }

    if (!template.exercises.length) {
      elements.templateExerciseBody.appendChild(createEmptyTableRow("Ten szablon nie zawiera jeszcze ćwiczeń.", 6));
      return;
    }

    template.exercises.forEach((exercise, index) => {
      const row = document.createElement("tr");
      row.appendChild(createCell(String(index + 1)));
      row.appendChild(createCell(exercise.exerciseName));
      row.appendChild(createCell(formatWorkoutPlan(exercise)));
      row.appendChild(createCell(formatMetric(exercise.durationMin, "min")));
      row.appendChild(createCell(exercise.notes || "brak"));

      const actionCell = document.createElement("td");
      if (!editMode) {
        actionCell.textContent = "Podgląd";
        row.appendChild(actionCell);
        elements.templateExerciseBody.appendChild(row);
        return;
      }

      const actionWrap = document.createElement("div");
      actionWrap.className = "table-actions";

      const moveUpButton = document.createElement("button");
      moveUpButton.type = "button";
      moveUpButton.className = "edit-button";
      moveUpButton.setAttribute("data-template-exercise-index", String(index));
      moveUpButton.setAttribute("data-template-exercise-action", "move-up");
      moveUpButton.textContent = "Wyżej";
      moveUpButton.disabled = index === 0;

      const moveDownButton = document.createElement("button");
      moveDownButton.type = "button";
      moveDownButton.className = "edit-button";
      moveDownButton.setAttribute("data-template-exercise-index", String(index));
      moveDownButton.setAttribute("data-template-exercise-action", "move-down");
      moveDownButton.textContent = "Niżej";
      moveDownButton.disabled = index === template.exercises.length - 1;

      const editButton = document.createElement("button");
      editButton.type = "button";
      editButton.className = "edit-button";
      editButton.setAttribute("data-template-exercise-index", String(index));
      editButton.setAttribute("data-template-exercise-action", "edit");
      editButton.textContent = "Edytuj";

      const deleteButton = document.createElement("button");
      deleteButton.type = "button";
      deleteButton.className = "delete-button";
      deleteButton.setAttribute("data-template-exercise-index", String(index));
      deleteButton.setAttribute("data-template-exercise-action", "delete");
      deleteButton.textContent = "Usuń";

      actionWrap.append(moveUpButton, moveDownButton, editButton, deleteButton);
      actionCell.appendChild(actionWrap);
      row.appendChild(actionCell);
      elements.templateExerciseBody.appendChild(row);
    });
  }

  function renderSessionTable(sessionSummaries) {
    elements.sessionBody.replaceChildren();
    if (state.unlocked) {
      const filteredSessions = filterSessionSummaries(sessionSummaries);
      if (sessionSummaries.length && !filteredSessions.length) {
        elements.sessionBody.appendChild(createEmptyTableRow("Brak sesji pasujących do aktywnych filtrów.", 6));
        return;
      }
      sessionSummaries = filteredSessions;
    } else {
      elements.sessionFilterSummary.textContent = "Filtry sesji uaktywnia się po zalogowaniu.";
    }

    if (!state.unlocked) {
      elements.sessionBody.appendChild(createEmptyTableRow("Zaloguj się, aby zobaczyć sesje treningowe.", 6));
      return;
    }

    if (!sessionSummaries.length) {
      elements.sessionBody.appendChild(createEmptyTableRow("Brak sesji. Dodaj ćwiczenia, a aplikacja zgrupuje je w treningi dzienne.", 6));
      return;
    }

    sessionSummaries.forEach((session) => {
      const row = document.createElement("tr");
      row.appendChild(createCell(formatDisplayDate(session.date)));
      row.appendChild(createCell(`${session.exerciseCount} ćw.`));
      row.appendChild(createCell(formatSessionActivitySummary(session)));
      row.appendChild(createCell(formatMetric(session.estimatedCalories, "kcal")));
      row.appendChild(createCell(session.exercisePreview));

      const actionCell = document.createElement("td");
      const actionWrap = document.createElement("div");
      actionWrap.className = "table-actions";

      const openButton = document.createElement("button");
      openButton.type = "button";
      openButton.className = "edit-button";
      openButton.setAttribute("data-session-date", session.date);
      openButton.setAttribute("data-session-action", "open");
      openButton.textContent = "Otwórz dzień";

      const templateButton = document.createElement("button");
      templateButton.type = "button";
      templateButton.className = "edit-button";
      templateButton.setAttribute("data-session-date", session.date);
      templateButton.setAttribute("data-session-action", "template");
      templateButton.textContent = "Szablon";

      actionWrap.append(openButton, templateButton);
      actionCell.appendChild(actionWrap);
      row.appendChild(actionCell);

      elements.sessionBody.appendChild(row);
    });
  }

  function renderWeeklyPlan(analytics) {
    elements.weeklyPlanList.replaceChildren();

    const planItems = state.unlocked
      ? analytics.weeklyPlan
      : ["Zaloguj się, aby zobaczyć spersonalizowany plan działania."];

    planItems.forEach((message) => {
      const item = document.createElement("li");
      item.textContent = message;
      elements.weeklyPlanList.appendChild(item);
    });
  }

  function renderRiskAlerts(analytics) {
    const riskAlerts = analytics && analytics.riskAlerts ? analytics.riskAlerts : null;
    const cards = state.unlocked && riskAlerts && Array.isArray(riskAlerts.cards) ? riskAlerts.cards : [];
    renderMetricCardCollection(
      elements.riskAlertCards,
      cards,
      state.unlocked
        ? "Brak aktywnych alertów ryzyka. Utrzymuj logowanie snu, jedzenia, pasa i treningów."
        : "Zaloguj się, aby aplikacja mogła sprawdzić ryzyka tygodnia."
    );

    if (!elements.riskAlertStatus) {
      return;
    }

    if (!state.unlocked) {
      elements.riskAlertStatus.textContent = "Zablokowane";
      elements.riskAlertStatus.className = "status-pill status-locked";
      return;
    }

    const riskCount = riskAlerts && Number.isFinite(riskAlerts.riskCount) ? riskAlerts.riskCount : 0;
    const warnCount = riskAlerts && Number.isFinite(riskAlerts.warnCount) ? riskAlerts.warnCount : 0;
    elements.riskAlertStatus.textContent = riskCount
      ? `${riskCount} ryzyko`
      : warnCount
        ? `${warnCount} uwaga`
        : "Stabilnie";
    elements.riskAlertStatus.className = `status-pill ${riskCount ? "status-risk" : warnCount ? "status-warn" : "status-unlocked"}`;
  }

  function renderPreparationPlan(analytics) {
    const plan = analytics && analytics.preparationPlan ? analytics.preparationPlan : null;
    renderMetricCardCollection(
      elements.preparationPlanCards,
      state.unlocked && plan && Array.isArray(plan.cards) ? plan.cards : [],
      state.unlocked
        ? "Dodaj cel z terminem i trybem przygotowania, aby aplikacja policzyła tempo do deadline'u."
        : "Zaloguj się, aby uruchomić tryb przygotowania do celu."
    );
    renderTextList(
      elements.preparationPlanList,
      state.unlocked && plan ? plan.items : [],
      "Po dodaniu celu z deadline'em aplikacja ułoży tempo, zalecenia tygodniowe i kierunek treningu."
    );

    if (!elements.preparationPlanStatus) {
      return;
    }

    if (!state.unlocked) {
      elements.preparationPlanStatus.textContent = "Zablokowane";
      elements.preparationPlanStatus.className = "status-pill status-locked";
      return;
    }

    if (!plan || !plan.available) {
      elements.preparationPlanStatus.textContent = "Brak celu";
      elements.preparationPlanStatus.className = "status-pill status-warn";
      return;
    }

    const statusClass = plan.timing && plan.timing.tone === "risk"
      ? "status-risk"
      : plan.timing && plan.timing.tone === "warn"
        ? "status-warn"
        : "status-unlocked";
    elements.preparationPlanStatus.textContent = plan.timing ? plan.timing.statusLabel : "Aktywny";
    elements.preparationPlanStatus.className = `status-pill ${statusClass}`;
  }

  function renderWeeklyReport(analytics) {
    const report = analytics && analytics.weeklyReport ? analytics.weeklyReport : null;
    renderMetricCardCollection(
      elements.weeklyReportCards,
      state.unlocked && report && Array.isArray(report.cards) ? report.cards : [],
      state.unlocked
        ? "Raport tygodniowy pojawi się po pierwszych wpisach dziennika lub treningach w tym tygodniu."
        : "Zaloguj się, aby zobaczyć raport tygodniowy."
    );
    renderTextList(
      elements.weeklyReportWins,
      state.unlocked && report ? report.wins : [],
      "Brakuje jeszcze danych, żeby wskazać mocne strony tygodnia."
    );
    renderTextList(
      elements.weeklyReportBlocks,
      state.unlocked && report ? report.blockers : [],
      "Na razie nie widać dużych blokad progresu."
    );
    renderTextList(
      elements.weeklyReportActions,
      state.unlocked && report ? report.actions : [],
      "Dodaj kilka wpisów i treningów, a aplikacja zaproponuje korekty na kolejny tydzień."
    );

    if (elements.weeklyReportSummary) {
      elements.weeklyReportSummary.textContent = state.unlocked && report
        ? report.summary
        : "Raport tygodniowy działa lokalnie i aktualizuje się po każdym wpisie.";
    }

    if (elements.weeklyReportStatus) {
      elements.weeklyReportStatus.textContent = state.unlocked && report ? report.periodLabel : "Zablokowane";
      elements.weeklyReportStatus.className = `status-pill ${state.unlocked ? "status-unlocked" : "status-locked"}`;
    }
  }

  function handleExportCsv() {
    if (!requireUnlocked()) {
      return;
    }

    if (!state.data.entries.length) {
      showStatus("Brak wpisów do eksportu.", true);
      return;
    }

    const settings = normalizeData(state.data).settings;
    const entrySnapshots = buildEntriesPreview(state.data.entries, state.data.workouts, settings);
    const rows = [
      [
        "date",
        "weightKg",
        "bodyFatPct",
        "estimatedBodyFatPct",
        "caloriesIn",
        "burnedCalories",
        "energyBalance",
        "estimatedBMR",
        "estimatedStepCalories",
        "estimatedWorkoutCalories",
        "proteinG",
        "fatG",
        "carbsG",
        "mealCount",
        "mealSummary",
        "waistCm",
        "hipsCm",
        "chestCm",
        "armCm",
        "thighCm",
        "progressPhotosCount",
        "steps",
        "sleepHours",
        "restingHr",
        "workoutCount",
        "notes",
      ],
    ];

    entrySnapshots.forEach((entry) => {
      rows.push([
        entry.date,
        toCsvValue(entry.weightKg),
        toCsvValue(entry.bodyFatPct),
        toCsvValue(entry.estimatedBodyFatPct),
        toCsvValue(entry.calories),
        toCsvValue(entry.totalBurnedCalories),
        toCsvValue(entry.energyBalance),
        toCsvValue(entry.bmrCalories),
        toCsvValue(entry.stepCalories),
        toCsvValue(entry.workoutCalories),
        toCsvValue(entry.proteinG),
        toCsvValue(entry.fatG),
        toCsvValue(entry.carbsG),
        toCsvValue(entry.mealCount),
        Array.isArray(entry.meals) ? entry.meals.map((meal) => `${meal.name} (${round(meal.calories, 0)} kcal)`).join(" | ") : "",
        toCsvValue(entry.waistCm),
        toCsvValue(entry.hipsCm),
        toCsvValue(entry.chestCm),
        toCsvValue(entry.armCm),
        toCsvValue(entry.thighCm),
        toCsvValue(entry.progressPhotosCount),
        toCsvValue(entry.steps),
        toCsvValue(entry.sleepHours),
        toCsvValue(entry.restingHr),
        toCsvValue(entry.workoutCount),
        entry.notes || "",
      ]);
    });

    const csvContent = rows.map((row) => row.map(escapeCsvCell).join(",")).join("\r\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = "fitsecure-entries.csv";
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    URL.revokeObjectURL(url);
    showStatus("Wyeksportowano wpisy do pliku CSV.");
  }
  async function handleImportEntriesCsv(event) {
    const file = event.target.files && event.target.files[0];
    if (!file) {
      return;
    }

    if (!requireUnlocked()) {
      elements.importEntriesCsvInput.value = "";
      return;
    }

    try {
      const rawText = await file.text();
      const rows = parseCsvText(rawText);
      if (!rows.length) {
        throw new Error("Plik CSV z wpisami jest pusty.");
      }

      const importedEntries = rows
        .map((row) => mapCsvEntryRow(row))
        .filter(Boolean);

      if (!importedEntries.length) {
        throw new Error("Nie znaleziono poprawnych wpisów do importu.");
      }

      const conflictingDates = importedEntries.filter((entry) => state.data.entries.some((item) => item.date === entry.date)).length;
      if (conflictingDates && !window.confirm(`Import nadpisze ${conflictingDates} istniejących wpisów z tych samych dat. Kontynuować?`)) {
        return;
      }

      const mergedEntries = new Map(state.data.entries.map((entry) => [entry.date, entry]));
      importedEntries.forEach((entry) => {
        const existing = mergedEntries.get(entry.date);
        mergedEntries.set(entry.date, {
          ...(existing || {}),
          ...entry,
          id: existing ? existing.id : entry.id,
          progressPhotos: existing && Array.isArray(existing.progressPhotos) ? existing.progressPhotos : [],
        });
      });

      state.data.entries = sortEntries(Array.from(mergedEntries.values())).slice(-MAX_ENTRIES);
      syncCurrentWeightFromEntries();
      await persistVault();
      resetEntryForm();
      renderDashboard();
      showStatus(`Zaimportowano ${importedEntries.length} wpisów dziennych.`);
    } catch (error) {
      showStatus(error.message || "Nie udało się zaimportować wpisów z CSV.", true);
    } finally {
      elements.importEntriesCsvInput.value = "";
    }
  }

    function handleExportWorkoutsCsv() {
    if (!requireUnlocked()) {
      return;
    }

    if (!state.data.workouts.length) {
      showStatus("Brak ćwiczeń do eksportu.", true);
      return;
    }

    const rows = [
      ["date", "exerciseName", "activityProfile", "sets", "reps", "weightKg", "distanceKm", "elevationGainM", "paceMinKm", "avgSpeedKmh", "effectiveLoadKg", "loadMode", "exerciseCategory", "durationMin", "intensityRpe", "sessionDifficulty", "sessionFeedbackNotes", "notes", "volumeKg", "estimated1RM", "estimatedCalories"],
    ];

    state.data.workouts.forEach((workout) => {
      rows.push([
        workout.date,
        workout.exerciseName,
        workout.activityProfile || "strength",
        toCsvValue(workout.sets),
        toCsvValue(workout.reps),
        toCsvValue(workout.weightKg),
        toCsvValue(workout.distanceKm),
        toCsvValue(workout.elevationGainM),
        toCsvValue(workout.paceMinKm),
        toCsvValue(workout.avgSpeedKmh),
        toCsvValue(workout.effectiveLoadKg),
        workout.loadMode || "",
        workout.exerciseCategory || "",
        toCsvValue(workout.durationMin),
        toCsvValue(workout.intensityRpe),
        toCsvValue(workout.sessionDifficulty),
        workout.sessionFeedbackNotes || "",
        workout.notes || "",
        toCsvValue(workout.volumeKg),
        toCsvValue(workout.estimated1RM),
        toCsvValue(workout.estimatedCalories),
      ]);
    });

    const csvContent = rows.map((row) => row.map(escapeCsvCell).join(",")).join("\r\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `fitsecure-workouts-${toISODate(new Date())}.csv`;
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    URL.revokeObjectURL(url);
    showStatus("Wyeksportowano plik CSV z ćwiczeniami.");
  }
async function handleImportWorkoutsCsv(event) {
    const file = event.target.files && event.target.files[0];
    if (!file) {
      return;
    }

    if (!requireUnlocked()) {
      elements.importWorkoutsCsvInput.value = "";
      return;
    }

    try {
      const rawText = await file.text();
      const rows = parseCsvText(rawText);
      if (!rows.length) {
        throw new Error("Plik CSV z ćwiczeniami jest pusty.");
      }

      const importedWorkouts = rows
        .map((row) => mapCsvWorkoutRow(row))
        .filter(Boolean);

      if (!importedWorkouts.length) {
        throw new Error("Nie znaleziono poprawnych ćwiczeń do importu.");
      }

      const mergedWorkouts = new Map(state.data.workouts.map((workout) => [buildWorkoutIdentityKey(workout), workout]));
      let replacedCount = 0;
      importedWorkouts.forEach((workout) => {
        const key = buildWorkoutIdentityKey(workout);
        const existing = mergedWorkouts.get(key);
        if (existing) {
          replacedCount += 1;
        }
        mergedWorkouts.set(key, {
          ...workout,
          id: existing ? existing.id : workout.id,
        });
      });

      if (replacedCount && !window.confirm(`Import zaktualizuje ${replacedCount} ćwiczeń o takim samym kluczu (data, ćwiczenie i parametry). Kontynuować?`)) {
        return;
      }

      state.data.workouts = sortWorkouts(Array.from(mergedWorkouts.values())).slice(-MAX_ENTRIES * 4);
      await persistVault();
      resetWorkoutForm();
      renderDashboard();
      showStatus(`Zaimportowano ${importedWorkouts.length} ćwiczeń.`);
    } catch (error) {
      showStatus(error.message || "Nie udało się zaimportować ćwiczeń z CSV.", true);
    } finally {
      elements.importWorkoutsCsvInput.value = "";
    }
  }

  async function handleSaveTemplate() {
    if (!requireUnlocked()) {
      return;
    }

    try {
      let templateName = sanitizePlainText(elements.templateNameInput.value, 80);
      const templateDate = elements.workoutDateInput.value;
      if (!templateDate) {
        throw new Error("Wybierz datę treningu, z której chcesz zapisać szablon.");
      }
      const selectedTemplateId = elements.templateSelect.value;
      const selectedTemplate = state.data.templates.find((template) => template.id === selectedTemplateId) || null;
      templateName = selectedTemplate ? selectedTemplate.name : templateName;
      if (!templateName) {
        templateName = requestTemplateName(`Plan ${formatDisplayDate(templateDate)}`, "Podaj nazwę szablonu dla zapisywanego dnia treningowego.");
      }
      if (!templateName) {
        return;
      }

      const workoutsForDate = sortWorkouts(state.data.workouts.filter((workout) => workout.date === templateDate));
      if (!workoutsForDate.length) {
        throw new Error("Najpierw dodaj ćwiczenia dla wybranej daty, a dopiero potem zapisz szablon.");
      }

      const existingTemplate = selectedTemplate ||
        state.data.templates.find((template) => template.name.toLowerCase() === templateName.toLowerCase());

      if (existingTemplate && !window.confirm(`Szablon "${existingTemplate.name}" już istnieje. Zastąpić go treningiem z dnia ${formatDisplayDate(templateDate)}?`)) {
        return;
      }

      const template = {
        id: existingTemplate ? existingTemplate.id : (window.crypto.randomUUID ? window.crypto.randomUUID() : `template-${Date.now()}`),
        name: templateName,
        updatedAt: new Date().toISOString(),
        exercises: workoutsForDate.map((workout) => ({
          exerciseName: workout.exerciseName,
          activityProfile: workout.activityProfile || "strength",
          sets: workout.sets,
          reps: workout.reps,
          weightKg: workout.weightKg,
          distanceKm: workout.distanceKm,
          elevationGainM: workout.elevationGainM,
          durationMin: workout.durationMin,
          intensityRpe: workout.intensityRpe,
          exerciseCategory: workout.exerciseCategory,
          loadMode: workout.loadMode,
          notes: workout.notes || "",
        })),
      };

      const existingIndex = state.data.templates.findIndex((item) => item.id === template.id);
      if (existingIndex >= 0) {
        state.data.templates[existingIndex] = template;
      } else {
        state.data.templates.push(template);
      }

      state.data.templates = sortTemplates(state.data.templates).slice(-150);
      await persistVault();
      elements.templateSelect.value = template.id;
      state.templateEditMode = false;
      clearTemplateExerciseDraft();
      renderDashboard();
      elements.templateSelect.value = template.id;
      syncTemplateSelection();
      const templatePanel = getTemplateExercisePanel();
      if (templatePanel) {
        templatePanel.scrollIntoView({ behavior: "smooth", block: "start" });
      }
      showStatus(`Zapisano szablon "${template.name}" z ${template.exercises.length} ćwiczeniami.`);
    } catch (error) {
      showStatus(error.message || "Nie udało się zapisać szablonu.", true);
    }
  }

  function requestTemplateName(defaultName, promptText) {
    const fallbackName = sanitizePlainText(defaultName, 80);
    const response = window.prompt(promptText || "Podaj nazwę szablonu treningowego.", fallbackName || "");
    if (response === null) {
      return "";
    }
    return sanitizePlainText(response, 80);
  }

  function showBlankTemplateNameForm() {
    if (!requireUnlocked()) {
      return;
    }
    if (!elements.blankTemplateNameRow || !elements.blankTemplateNameInput) {
      return;
    }
    elements.blankTemplateNameInput.value = elements.blankTemplateNameInput.value || `Nowy szablon ${state.data.templates.length + 1}`;
    elements.blankTemplateNameRow.classList.remove("is-hidden");
    window.setTimeout(() => {
      elements.blankTemplateNameInput.focus({ preventScroll: true });
      elements.blankTemplateNameInput.select();
    }, 0);
  }

  function hideBlankTemplateNameForm() {
    if (elements.blankTemplateNameRow) {
      elements.blankTemplateNameRow.classList.add("is-hidden");
    }
    if (elements.blankTemplateNameInput) {
      elements.blankTemplateNameInput.value = "";
    }
  }

  function handleBlankTemplateNameKeydown(event) {
    if (event.key === "Enter") {
      event.preventDefault();
      handleCreateBlankTemplate();
      return;
    }
    if (event.key === "Escape") {
      event.preventDefault();
      hideBlankTemplateNameForm();
    }
  }

  async function handleCreateBlankTemplate() {
    if (!requireUnlocked()) {
      return;
    }

    try {
      const templateName = sanitizePlainText(elements.blankTemplateNameInput ? elements.blankTemplateNameInput.value : "", 80);
      if (!templateName) {
        showBlankTemplateNameForm();
        showStatus("Wpisz nazwę szablonu i kliknij OK.", true);
        return;
      }

      const existingTemplate = state.data.templates.find((template) => template.name.toLowerCase() === templateName.toLowerCase());
      if (existingTemplate) {
        elements.templateSelect.value = existingTemplate.id;
        elements.templateNameInput.value = existingTemplate.name;
        hideBlankTemplateNameForm();
        showTemplatePreview(existingTemplate, true);
        const templatePanel = getTemplateExercisePanel();
        if (templatePanel) {
          templatePanel.scrollIntoView({ behavior: "smooth", block: "start" });
        }
        showStatus(`Szablon "${existingTemplate.name}" już istnieje. Włączono jego edycję.`);
        return;
      }

      const template = {
        id: window.crypto.randomUUID ? window.crypto.randomUUID() : `template-${Date.now()}`,
        name: templateName,
        updatedAt: new Date().toISOString(),
        exercises: [],
      };

      state.data.templates.push(template);
      state.data.templates = sortTemplates(state.data.templates).slice(-150);
      state.editingTemplateExerciseIndex = null;
      await persistVault();
      renderDashboard();
      elements.templateSelect.value = template.id;
      elements.templateNameInput.value = template.name;
      hideBlankTemplateNameForm();
      showTemplatePreview(template, true);
      const templatePanel = getTemplateExercisePanel();
      if (templatePanel) {
        templatePanel.scrollIntoView({ behavior: "smooth", block: "start" });
      }
      showStatus(`Utworzono pusty szablon "${template.name}". Dodaj ćwiczenia ręcznie w edytorze.`);
    } catch (error) {
      showStatus(error.message || "Nie udało się utworzyć własnego szablonu.", true);
    }
  }

  function handlePreviewSelectedTemplate() {
    if (!requireUnlocked()) {
      return;
    }

    const template = getSelectedTemplate();
    if (!template) {
      showStatus("Wybierz zapisany szablon do podglądu.", true);
      return;
    }

    hideBlankTemplateNameForm();
    showTemplatePreview(template, false);
    const templatePanel = getTemplateExercisePanel();
    if (templatePanel) {
      templatePanel.scrollIntoView({ behavior: "smooth", block: "start" });
    }
    showStatus(`Otworzono podgląd szablonu "${template.name}".`);
  }

  async function handleApplyTemplate() {
    if (!requireUnlocked()) {
      return;
    }

    try {
      const template = getSelectedTemplate();
      if (!template) {
        throw new Error("Wybierz zapisany szablon treningu.");
      }
      if (!template.exercises.length) {
        throw new Error("Ten szablon jest jeszcze pusty. Dodaj ćwiczenia ręcznie, zanim wczytasz go do dnia.");
      }

      const targetDate = elements.workoutDateInput.value;
      if (!targetDate) {
        throw new Error("Wybierz datę, do której chcesz wczytać szablon.");
      }

      const existingForDate = state.data.workouts.filter((workout) => workout.date === targetDate);
      if (existingForDate.length && !window.confirm(`Dla dnia ${formatDisplayDate(targetDate)} są już zapisane ćwiczenia. Zastąpić je wybranym szablonem?`)) {
        return;
      }

      const settings = normalizeData(state.data).settings;
      const currentWeight = getCurrentWeightForCalculations(settings, state.data.entries);
      const generatedWorkouts = template.exercises.map((exercise) => buildWorkoutFromTemplateExercise(exercise, targetDate, settings, currentWeight));

      state.data.workouts = sortWorkouts(
        state.data.workouts
          .filter((workout) => workout.date !== targetDate)
          .concat(generatedWorkouts)
      ).slice(-MAX_ENTRIES * 4);

      await persistVault();
      resetWorkoutForm();
      state.templateEditMode = false;
      elements.workoutDateInput.value = targetDate;
      renderDashboard();
      showStatus(`Wczytano szablon "${template.name}" do dnia ${formatDisplayDate(targetDate)}.`);
    } catch (error) {
      showStatus(error.message || "Nie udało się wczytać szablonu.", true);
    }
  }

  async function handleDeleteTemplate() {
    if (!requireUnlocked()) {
      return;
    }

    const template = getSelectedTemplate();
    if (!template) {
      showStatus("Wybierz szablon, który chcesz usuńąć.", true);
      return;
    }

    if (!window.confirm(`Usuńąć szablon "${template.name}"?`)) {
      return;
    }

    try {
      state.data.templates = state.data.templates.filter((item) => item.id !== template.id);
      if (elements.templateSelect.value === template.id) {
        elements.templateSelect.value = "";
      }
      state.templateEditMode = false;
      state.templatePreviewVisible = false;
      clearTemplateExerciseDraft();
      elements.templateNameInput.value = "";
      await persistVault();
      renderDashboard();
      showStatus(`Usunięto szablon "${template.name}".`);
    } catch (error) {
      showStatus(error.message || "Nie udało się usuńąć szablonu.", true);
    }
  }

  function handleTemplateTableAction(event) {
    const actionButton = event.target.closest("button[data-template-id][data-template-action]");
    if (!actionButton || !state.unlocked) {
      return;
    }

    const templateId = actionButton.getAttribute("data-template-id");
    const template = state.data.templates.find((item) => item.id === templateId);
    if (!template) {
      return;
    }

    elements.templateSelect.value = template.id;
    elements.templateNameInput.value = template.name;
    state.templateEditMode = false;
    clearTemplateExerciseDraft();

    const action = actionButton.getAttribute("data-template-action");
    if (action === "select") {
      showTemplatePreview(template, false);
      const templatePanel = getTemplateExercisePanel();
      if (templatePanel) {
        templatePanel.scrollIntoView({ behavior: "smooth", block: "start" });
      }
      showStatus(`Wybrano szablon "${template.name}".`);
      return;
    }
    if (action === "apply") {
      handleApplyTemplate();
      return;
    }
    if (action === "delete") {
      handleDeleteTemplate();
    }
  }

  function handleSessionTableAction(event) {
    const actionButton = event.target.closest("button[data-session-date][data-session-action]");
    if (!actionButton || !state.unlocked) {
      return;
    }

    const sessionDate = actionButton.getAttribute("data-session-date");
    if (!sessionDate) {
      return;
    }

    elements.workoutDateInput.value = sessionDate;

    const action = actionButton.getAttribute("data-session-action");
    if (action === "open") {
      elements.workoutForm.scrollIntoView({ behavior: "smooth", block: "start" });
      showStatus(`Ustawiono dzień treningowy na ${formatDisplayDate(sessionDate)}.`);
      return;
    }

    if (action === "template") {
      elements.templateNameInput.value = elements.templateNameInput.value || `Plan ${formatDisplayDate(sessionDate)}`;
      elements.workoutForm.scrollIntoView({ behavior: "smooth", block: "start" });
      showStatus(`Wybrano dzień ${formatDisplayDate(sessionDate)}. Teraz możesz zapisać go jako szablon.`);
    }
  }

  function getSelectedTemplate() {
    return state.data.templates.find((template) => template.id === elements.templateSelect.value) || null;
  }

  function clearTemplateExerciseDraft() {
    elements.templateExerciseForm.reset();
    elements.templateActivityProfileInput.value = "strength";
    state.editingTemplateExerciseIndex = null;
    syncExerciseTemplateInput("template");
  }

  function getTemplateExercisePanel() {
    return elements.templateExerciseBody ? elements.templateExerciseBody.closest(".planner-block") : null;
  }

  function syncTemplateSelection() {
    const template = getSelectedTemplate();
    state.templateEditMode = false;
    state.templatePreviewVisible = false;
    clearTemplateExerciseDraft();
    hideBlankTemplateNameForm();
    elements.templateNameInput.value = template ? template.name : "";
    renderTemplateExecutionPanel(template);
    renderTemplateExerciseEditor(template);
  }

  function syncTemplateExerciseFormMode(templateArg) {
    const template = templateArg || getSelectedTemplate();
    const hasTemplate = state.unlocked && Boolean(template);
    const editMode = hasTemplate && state.templateEditMode;
    const hasEditingExercise = editMode &&
      Number.isInteger(state.editingTemplateExerciseIndex) &&
      state.editingTemplateExerciseIndex >= 0 &&
      state.editingTemplateExerciseIndex < template.exercises.length;

    if (!hasEditingExercise) {
      state.editingTemplateExerciseIndex = null;
    }

    elements.templateExerciseEditorTitle.textContent = template
      ? `Ćwiczenia w szablonie: ${template.name}`
      : "Ćwiczenia wybranego szablonu";
    elements.templateExerciseModeBadge.textContent = hasEditingExercise
      ? "Tryb edycji ćwiczenia"
      : hasTemplate
        ? "Tryb edycji szablonu"
        : "Tryb dodawania";
    elements.templateExerciseModeBadge.className = `status-pill ${hasTemplate ? "status-unlocked" : "status-locked"}`;
    elements.saveTemplateExerciseButton.textContent = hasEditingExercise
      ? "Zapisz zmiany w szablonie"
      : hasTemplate
        ? "Zapisz zmiany w szablonie"
        : "Dodaj ćwiczenie do szablonu";
    elements.resetTemplateExerciseButton.textContent = hasEditingExercise
      ? "Anuluj edycję ćwiczenia"
      : "Wyczyść pola";

    if (!state.unlocked) {
      elements.templateSummary.textContent = "Zaloguj się, aby dopracowywać ćwiczenia zapisane w szablonach.";
    } else if (!template) {
      elements.templateSummary.textContent = "Wybierz zapisany szablon, aby zmieniać ćwiczenia, kolejność, serie, powtórzenia, ciężar, czas i RPE.";
    } else {
      elements.templateSummary.textContent = `Szablon "${template.name}" zawiera ${template.exercises.length} ćwiczeń. Możesz poprawiać plan pojedynczo i od razu ustawiać kolejność całego dnia.`;
    }

    Array.from(elements.templateExerciseForm.querySelectorAll("input, textarea, button")).forEach((node) => {
      node.disabled = !hasTemplate;
    });

    elements.templateExerciseEditorTitle.textContent = template
      ? `Plan szablonu: ${template.name}`
      : "Plan wybranego szablonu";
    elements.templateExerciseModeBadge.textContent = !state.unlocked
      ? "Zablokowane"
      : hasEditingExercise
        ? "Edycja ćwiczenia"
        : editMode
          ? "Edycja szablonu"
          : "Podgląd szablonu";
    elements.saveTemplateExerciseButton.textContent = hasEditingExercise
      ? "Zapisz zmiany ćwiczenia"
      : "Dodaj ćwiczenie do szablonu";
    elements.resetTemplateExerciseButton.textContent = hasEditingExercise
      ? "Anuluj edycje ćwiczenia"
      : "Wyczyść pola";

    if (!state.unlocked) {
      elements.templateSummary.textContent = "Zaloguj się, aby otwierać i edytować zapisane szablony treningowe.";
    } else if (!template) {
      elements.templateSummary.textContent = "Wybierz zapisany szablon, aby zobaczyć rozpiskę całego treningu.";
    } else if (!editMode) {
      elements.templateSummary.textContent = `Szablon "${template.name}" zawiera ${template.exercises.length} ćwiczeń. Poniżej widzisz plan dnia; kliknij "Edytuj szablon", gdy chcesz zmienić kolejność, serie, powtórzenia albo ćwiczenia.`;
    } else {
      elements.templateSummary.textContent = `Tryb edycji jest wlaczony dla szablonu "${template.name}". Dodawaj nowe ćwiczenia albo poprawiaj wpisy w tabeli poniżej.`;
    }

    elements.templateExerciseForm.classList.toggle("is-hidden", !editMode);
    Array.from(elements.templateExerciseForm.querySelectorAll("input, textarea, select, button")).forEach((node) => {
      node.disabled = !editMode;
    });
    elements.editTemplateButton.disabled = !hasTemplate;
    elements.editTemplateButton.textContent = editMode ? "Zakoncz edycje" : "Edytuj szablon";
    elements.editTemplateButton.classList.toggle("button-primary", editMode);
    elements.editTemplateButton.classList.toggle("button-subtle", !editMode);
  }

  function handleToggleTemplateEditMode() {
    if (!requireUnlocked()) {
      return;
    }

    const template = getSelectedTemplate();
    if (!template) {
      showStatus("Wybierz szablon, który chcesz edytować.", true);
      return;
    }

    state.templatePreviewVisible = true;
    state.templateEditMode = !state.templateEditMode;
    clearTemplateExerciseDraft();
    renderTemplateExerciseEditor(template);

    if (state.templateEditMode) {
      elements.templateExerciseForm.scrollIntoView({ behavior: "smooth", block: "start" });
      showStatus(`Wlaczono edycje szablonu "${template.name}".`);
      return;
    }

    const templatePanel = getTemplateExercisePanel();
    if (templatePanel) {
      templatePanel.scrollIntoView({ behavior: "smooth", block: "start" });
    }
    showStatus(`Wylaczono edycje szablonu "${template.name}".`);
  }

  function buildTemplateExerciseFromForm() {
    const exerciseName = sanitizePlainText(elements.templateExerciseNameInput.value, 80);
    if (!exerciseName) {
      throw new Error("Podaj nazwę ćwiczenia w szablonie.");
    }

    const activityProfile = resolveActivityProfileValue(elements.templateActivityProfileInput.value, "strength");
    const exerciseMeta = resolveExerciseMeta({ exerciseName, activityProfile });
    const sets = exerciseMeta.loadMode === "cardio"
      ? parseOptionalNumber(elements.templateSetsInput.value, { label: "Liczba serii", min: 1, max: 20, integer: true })
      : parseStrictNumber(elements.templateSetsInput.value, { label: "Liczba serii", min: 1, max: 20, integer: true });
    const reps = exerciseMeta.loadMode === "cardio"
      ? parseOptionalNumber(elements.templateRepsInput.value, { label: "Powtórzenia", min: 1, max: 50, integer: true })
      : parseStrictNumber(elements.templateRepsInput.value, { label: "Powtórzenia", min: 1, max: 50, integer: true });
    const weightKg = parseOptionalNumber(elements.templateWeightInput.value, { label: "Ciężar", min: 0, max: 600 }) || 0;
    const distanceKm = parseOptionalNumber(elements.templateDistanceInput.value, { label: "Dystans", min: 0, max: 300 });
    const elevationGainM = parseOptionalNumber(elements.templateElevationInput.value, { label: "Przewyższenie", min: 0, max: 5000 });
    const durationMin = parseOptionalNumber(elements.templateDurationMinInput.value, { label: "Czas ćwiczenia", min: 5, max: 240 });
    const intensityRpe = parseOptionalNumber(elements.templateIntensityInput.value, { label: "Intensywność RPE", min: 4, max: 10 });
    const derived = buildWorkoutDerivedMetrics({
      exerciseName,
      activityProfile,
      sets,
      reps,
      weightKg,
      distanceKm,
      elevationGainM,
      durationMin,
      intensityRpe,
    }, normalizeData(state.data).settings, getCurrentWeightForCalculations(normalizeData(state.data).settings, state.data.entries));

    return {
      exerciseName,
      sets,
      reps,
      weightKg,
      activityProfile: derived.activityProfile,
      distanceKm: derived.distanceKm,
      elevationGainM: derived.elevationGainM,
      durationMin: derived.durationMin,
      intensityRpe,
      exerciseCategory: exerciseMeta.category,
      loadMode: exerciseMeta.loadMode,
      notes: sanitizePlainText(elements.templateExerciseNotesInput.value, 180),
    };
  }

  function replaceTemplate(updatedTemplate) {
    const normalizedTemplate = normalizeTemplate(updatedTemplate);
    if (!normalizedTemplate) {
      throw new Error("Szablon musi mieć nazwę i poprawny format.");
    }

    const existingIndex = state.data.templates.findIndex((item) => item.id === normalizedTemplate.id);
    if (existingIndex >= 0) {
      state.data.templates[existingIndex] = normalizedTemplate;
    } else {
      state.data.templates.push(normalizedTemplate);
    }

    state.data.templates = sortTemplates(state.data.templates).slice(-150);
    elements.templateSelect.value = normalizedTemplate.id;
    elements.templateNameInput.value = normalizedTemplate.name;
    return normalizedTemplate;
  }

  function startEditingTemplateExercise(template, exerciseIndex) {
    const exercise = template && template.exercises ? template.exercises[exerciseIndex] : null;
    if (!exercise) {
      return;
    }

    state.templateEditMode = true;
    state.editingTemplateExerciseIndex = exerciseIndex;
    elements.templateExerciseNameInput.value = exercise.exerciseName;
    elements.templateActivityProfileInput.value = exercise.activityProfile || "strength";
    elements.templateSetsInput.value = toInputValue(exercise.sets);
    elements.templateRepsInput.value = toInputValue(exercise.reps);
    elements.templateWeightInput.value = toInputValue(exercise.weightKg);
    elements.templateDistanceInput.value = toInputValue(exercise.distanceKm);
    elements.templateElevationInput.value = toInputValue(exercise.elevationGainM);
    elements.templateDurationMinInput.value = toInputValue(exercise.durationMin);
    elements.templateIntensityInput.value = toInputValue(exercise.intensityRpe);
    elements.templateExerciseNotesInput.value = exercise.notes || "";
    syncTemplateExerciseFormMode(template);
    syncExerciseTemplateInput("template");
    elements.templateExerciseForm.scrollIntoView({ behavior: "smooth", block: "start" });
    showStatus(`Wczytano ćwiczenie ${exercise.exerciseName} z szablonu "${template.name}" do edycji.`);
  }

  function resetTemplateExerciseForm() {
    clearTemplateExerciseDraft();
    syncTemplateExerciseFormMode();
  }

  async function handleTemplateExerciseSubmit(event) {
    event.preventDefault();
    if (!requireUnlocked()) {
      return;
    }

    try {
      const template = getSelectedTemplate();
      if (!template) {
        throw new Error("Wybierz szablon, który chcesz dopracować.");
      }

      if (!state.templateEditMode) {
        throw new Error("Kliknij \"Edytuj szablon\", aby wprowadzać zmiany w ćwiczeniach.");
      }

      const exercise = buildTemplateExerciseFromForm();
      const nextExercises = template.exercises.slice();
      const editingIndex = state.editingTemplateExerciseIndex;
      const editing = Number.isInteger(editingIndex) && editingIndex >= 0 && editingIndex < nextExercises.length;

      if (editing) {
        nextExercises[editingIndex] = exercise;
      } else {
        nextExercises.push(exercise);
      }

      replaceTemplate({
        ...template,
        updatedAt: new Date().toISOString(),
        exercises: nextExercises,
      });

      resetTemplateExerciseForm();
      await persistVault();
      renderDashboard();
      showStatus(editing ? "Zapisano zmiany ćwiczenia w szablonie." : `Dodano ćwiczenie do szablonu "${template.name}".`);
    } catch (error) {
      showStatus(error.message || "Nie udało się zapisać ćwiczenia w szablonie.", true);
    }
  }

  function handleTemplateExerciseTableAction(event) {
    const actionButton = event.target.closest("button[data-template-exercise-index][data-template-exercise-action]");
    if (!actionButton || !state.unlocked || !state.templateEditMode) {
      return;
    }

    const template = getSelectedTemplate();
    if (!template) {
      return;
    }

    const exerciseIndex = Number(actionButton.getAttribute("data-template-exercise-index"));
    if (!Number.isInteger(exerciseIndex) || exerciseIndex < 0 || exerciseIndex >= template.exercises.length) {
      return;
    }

    const action = actionButton.getAttribute("data-template-exercise-action");
    if (action === "edit") {
      startEditingTemplateExercise(template, exerciseIndex);
      return;
    }

    if (action === "delete") {
      deleteTemplateExercise(template, exerciseIndex);
      return;
    }

    if (action === "move-up" || action === "move-down") {
      moveTemplateExercise(template, exerciseIndex, action === "move-up" ? -1 : 1);
    }
  }

  async function deleteTemplateExercise(template, exerciseIndex) {
    const exercise = template.exercises[exerciseIndex];
    if (!exercise) {
      return;
    }

    if (template.exercises.length <= 1) {
      showStatus("To ostatnie ćwiczenie w szablonie. Jeśli chcesz usuńąć całość, skorzystaj z przycisku usuwania szablonu.", true);
      return;
    }

    if (!window.confirm(`Usuńąć ćwiczenie "${exercise.exerciseName}" z szablonu "${template.name}"?`)) {
      return;
    }

    try {
      const nextExercises = template.exercises.filter((_item, index) => index !== exerciseIndex);
      replaceTemplate({
        ...template,
        updatedAt: new Date().toISOString(),
        exercises: nextExercises,
      });

      if (state.editingTemplateExerciseIndex === exerciseIndex) {
        resetTemplateExerciseForm();
      } else if (Number.isInteger(state.editingTemplateExerciseIndex) && state.editingTemplateExerciseIndex > exerciseIndex) {
        state.editingTemplateExerciseIndex -= 1;
      }

      await persistVault();
      renderDashboard();
      showStatus(`Usunięto ćwiczenie ${exercise.exerciseName} z szablonu "${template.name}".`);
    } catch (error) {
      showStatus(error.message || "Nie udało się usuńąć ćwiczenia z szablonu.", true);
    }
  }

  async function moveTemplateExercise(template, exerciseIndex, direction) {
    const targetIndex = exerciseIndex + direction;
    if (targetIndex < 0 || targetIndex >= template.exercises.length) {
      return;
    }

    try {
      const nextExercises = template.exercises.slice();
      const movedExercise = nextExercises[exerciseIndex];
      nextExercises[exerciseIndex] = nextExercises[targetIndex];
      nextExercises[targetIndex] = movedExercise;

      replaceTemplate({
        ...template,
        updatedAt: new Date().toISOString(),
        exercises: nextExercises,
      });

      if (state.editingTemplateExerciseIndex === exerciseIndex) {
        state.editingTemplateExerciseIndex = targetIndex;
      } else if (state.editingTemplateExerciseIndex === targetIndex) {
        state.editingTemplateExerciseIndex = exerciseIndex;
      }

      await persistVault();
      renderDashboard();
      showStatus(`Zmieniono kolejność ćwiczeń w szablonie "${template.name}".`);
    } catch (error) {
      showStatus(error.message || "Nie udało się zmienić kolejności ćwiczeń.", true);
    }
  }

  function buildWorkoutFromTemplateExercise(exercise, date, settings, currentWeight) {
    const derived = buildWorkoutDerivedMetrics({
      exerciseName: exercise.exerciseName,
      activityProfile: exercise.activityProfile,
      sets: exercise.sets,
      reps: exercise.reps,
      weightKg: exercise.weightKg,
      distanceKm: exercise.distanceKm,
      elevationGainM: exercise.elevationGainM,
      durationMin: exercise.durationMin,
      intensityRpe: exercise.intensityRpe,
      loadMode: exercise.loadMode,
      exerciseCategory: exercise.exerciseCategory,
    }, settings, currentWeight);

    return {
      id: window.crypto.randomUUID ? window.crypto.randomUUID() : `workout-${Date.now()}-${Math.random()}`,
      date,
      exerciseName: exercise.exerciseName,
      sets: exercise.sets,
      reps: exercise.reps,
      weightKg: exercise.weightKg,
      activityProfile: derived.activityProfile,
      distanceKm: derived.distanceKm,
      elevationGainM: derived.elevationGainM,
      avgSpeedKmh: derived.avgSpeedKmh,
      paceMinKm: derived.paceMinKm,
      durationMin: derived.durationMin,
      intensityRpe: exercise.intensityRpe,
      exerciseCategory: derived.exerciseCategory,
      loadMode: derived.loadMode,
      effectiveLoadKg: derived.effectiveLoadKg,
      notes: exercise.notes || "",
      volumeKg: derived.volumeKg,
      estimated1RM: derived.estimated1RM,
      estimatedCalories: derived.estimatedCalories,
    };
  }

  async function handleWorkoutSubmit(event) {
    event.preventDefault();
    if (!requireUnlocked()) {
      return;
    }

    try {
      const workout = buildWorkoutFromForm();
      const existingIndex = state.data.workouts.findIndex((item) => item.id === workout.id);
      const activeDate = workout.date;

      if (existingIndex >= 0) {
        state.data.workouts[existingIndex] = workout;
      } else {
        state.data.workouts.push(workout);
      }

      state.data.workouts = sortWorkouts(state.data.workouts).slice(-MAX_ENTRIES * 4);
      await persistVault();
      resetWorkoutForm(activeDate);
      renderDashboard();
      showStatus(existingIndex >= 0
        ? "Zapisano zmiany ćwiczenia. Trener adaptacyjny przeliczył kolejny plan."
        : "Dodano ćwiczenie do dziennika treningów. Trener adaptacyjny przeliczył kolejny plan.");
    } catch (error) {
      showStatus(error.message || "Nie udało się zapisać treningu.", true);
    }
  }

  function handleWorkoutTableAction(event) {
    const actionButton = event.target.closest("button[data-workout-id][data-workout-action]");
    if (!actionButton || !state.unlocked) {
      return;
    }

    const workoutId = actionButton.getAttribute("data-workout-id");
    const workout = state.data.workouts.find((item) => item.id === workoutId);
    if (!workout) {
      return;
    }

    const action = actionButton.getAttribute("data-workout-action");
    if (action === "history") {
      openExerciseHistory(workout.exerciseName, { scroll: true, status: true });
      return;
    }
    if (action === "edit") {
      startEditingWorkout(workout);
      return;
    }

    if (action === "delete") {
      deleteWorkout(workout);
    }
  }

  async function deleteWorkout(workout) {
    if (!window.confirm("Usunąć wybrane ćwiczenie z dziennika treningów?")) {
      return;
    }

    try {
      state.data.workouts = state.data.workouts.filter((item) => item.id !== workout.id);
      if (state.editingWorkoutId === workout.id) {
        resetWorkoutForm(workout.date);
      }
      await persistVault();
      renderDashboard();
      showStatus(`Usunięto ćwiczenie ${workout.exerciseName}.`);
    } catch (error) {
      showStatus(error.message || "Nie udało się usuńąć ćwiczenia.", true);
    }
  }

  function startEditingWorkout(workout) {
    state.editingWorkoutId = workout.id;
    elements.workoutDateInput.value = workout.date;
    if (elements.templateExecutionDateInput) {
      elements.templateExecutionDateInput.value = workout.date;
    }
    elements.exerciseNameInput.value = workout.exerciseName;
    elements.activityProfileInput.value = workout.activityProfile || "strength";
    elements.setsInput.value = toInputValue(workout.sets);
    elements.repsInput.value = toInputValue(workout.reps);
    elements.exerciseWeightInput.value = toInputValue(workout.weightKg);
    elements.distanceInput.value = toInputValue(workout.distanceKm);
    elements.elevationGainInput.value = toInputValue(workout.elevationGainM);
    elements.durationMinInput.value = toInputValue(workout.durationMin);
    elements.intensityInput.value = toInputValue(workout.intensityRpe);
    elements.workoutNotesInput.value = workout.notes || "";
    syncWorkoutFormMode();
    syncExerciseTemplateInput("workout");
    renderPostWorkoutCoach();
    elements.workoutForm.scrollIntoView({ behavior: "smooth", block: "start" });
    showStatus(`Wczytano ćwiczenie ${workout.exerciseName} do edycji.`);
  }

  function buildWorkoutFromForm() {
    const settings = normalizeData(state.data).settings;
    const date = elements.workoutDateInput.value;
    const exerciseName = sanitizePlainText(elements.exerciseNameInput.value, 80);
    if (!date) {
      throw new Error("Wybierz datę treningu.");
    }
    if (!exerciseName) {
      throw new Error("Podaj nazwę ćwiczenia.");
    }

    const activityProfile = resolveActivityProfileValue(elements.activityProfileInput.value, "strength");
    const exerciseMeta = resolveExerciseMeta({ exerciseName, activityProfile });
    const sets = exerciseMeta.loadMode === "cardio"
      ? parseOptionalNumber(elements.setsInput.value, { label: "Liczba serii", min: 1, max: 20, integer: true })
      : parseStrictNumber(elements.setsInput.value, { label: "Liczba serii", min: 1, max: 20, integer: true });
    const reps = exerciseMeta.loadMode === "cardio"
      ? parseOptionalNumber(elements.repsInput.value, { label: "Powtórzenia", min: 1, max: 50, integer: true })
      : parseStrictNumber(elements.repsInput.value, { label: "Powtórzenia", min: 1, max: 50, integer: true });
    const weightKg = parseOptionalNumber(elements.exerciseWeightInput.value, { label: "Ciężar", min: 0, max: 600 }) || 0;
    const distanceKm = parseOptionalNumber(elements.distanceInput.value, { label: "Dystans", min: 0, max: 300 });
    const elevationGainM = parseOptionalNumber(elements.elevationGainInput.value, { label: "Przewyższenie", min: 0, max: 5000 });
    const durationMin = parseOptionalNumber(elements.durationMinInput.value, { label: "Czas ćwiczenia", min: 5, max: 240 });
    const intensityRpe = parseOptionalNumber(elements.intensityInput.value, { label: "Intensywność RPE", min: 4, max: 10 });
    const currentWeight = getCurrentWeightForCalculations(settings, state.data.entries);
    const existingWorkout = state.editingWorkoutId
      ? state.data.workouts.find((item) => item.id === state.editingWorkoutId)
      : null;
    const derived = buildWorkoutDerivedMetrics({
      exerciseName,
      activityProfile,
      sets,
      reps,
      weightKg,
      distanceKm,
      elevationGainM,
      durationMin,
      intensityRpe,
    }, settings, currentWeight);

    return {
      id: state.editingWorkoutId || (window.crypto.randomUUID ? window.crypto.randomUUID() : `workout-${Date.now()}`),
      date,
      exerciseName,
      sets,
      reps,
      weightKg,
      activityProfile: derived.activityProfile,
      distanceKm: derived.distanceKm,
      elevationGainM: derived.elevationGainM,
      avgSpeedKmh: derived.avgSpeedKmh,
      paceMinKm: derived.paceMinKm,
      durationMin: derived.durationMin,
      intensityRpe,
      sessionDifficulty: existingWorkout && Number.isFinite(existingWorkout.sessionDifficulty) ? existingWorkout.sessionDifficulty : null,
      sessionFeedbackNotes: existingWorkout ? existingWorkout.sessionFeedbackNotes || "" : "",
      sessionFeedbackAt: existingWorkout ? existingWorkout.sessionFeedbackAt || "" : "",
      exerciseCategory: derived.exerciseCategory,
      loadMode: derived.loadMode,
      effectiveLoadKg: derived.effectiveLoadKg,
      notes: sanitizePlainText(elements.workoutNotesInput.value, 180),
      volumeKg: derived.volumeKg,
      estimated1RM: derived.estimated1RM,
      estimatedCalories: derived.estimatedCalories,
    };
  }

  function getSessionWorkoutsForDate(date, dataArg) {
    const data = normalizeData(dataArg || state.data);
    return data.workouts.filter((workout) => workout.date === date);
  }

  function getSessionFeedbackFromWorkouts(workouts) {
    const difficultyValues = (workouts || []).map((workout) => workout.sessionDifficulty).filter((value) => Number.isFinite(value));
    const notes = (workouts || [])
      .map((workout) => workout.sessionFeedbackNotes)
      .filter(Boolean)
      .slice(-1)[0] || "";
    const feedbackAt = (workouts || [])
      .map((workout) => workout.sessionFeedbackAt)
      .filter(Boolean)
      .sort()
      .pop() || "";
    return {
      difficulty: difficultyValues.length ? round(average(difficultyValues), 1) : NaN,
      notes,
      feedbackAt,
    };
  }

  function getPreviousSessionFeedbacks(workouts, date) {
    const grouped = new Map();
    (workouts || []).forEach((workout) => {
      if (!workout.date || workout.date >= date || !Number.isFinite(workout.sessionDifficulty)) {
        return;
      }
      const bucket = grouped.get(workout.date) || [];
      bucket.push(workout.sessionDifficulty);
      grouped.set(workout.date, bucket);
    });
    return Array.from(grouped.entries())
      .map(([sessionDate, values]) => ({
        date: sessionDate,
        difficulty: round(average(values), 1),
      }))
      .sort((first, second) => second.date.localeCompare(first.date));
  }

  function pickPrimaryWorkoutForSession(workouts) {
    if (!Array.isArray(workouts) || !workouts.length) {
      return null;
    }
    return workouts.slice().sort((first, second) => {
      const firstMeta = resolveExerciseMeta(first);
      const secondMeta = resolveExerciseMeta(second);
      const firstScore = (firstMeta.loadMode === "cardio" ? 40 : 60) +
        (Number(first.estimatedCalories) || 0) * 0.05 +
        (Number(first.volumeKg) || 0) * 0.002 +
        (Number(first.durationMin) || 0) * 0.25;
      const secondScore = (secondMeta.loadMode === "cardio" ? 40 : 60) +
        (Number(second.estimatedCalories) || 0) * 0.05 +
        (Number(second.volumeKg) || 0) * 0.002 +
        (Number(second.durationMin) || 0) * 0.25;
      return secondScore - firstScore;
    })[0] || workouts[0];
  }

  function buildNextWorkoutAdjustmentText(action, primaryWorkout) {
    if (!primaryWorkout) {
      return "Najpierw zapisz ćwiczenia z sesji, wtedy trener poda konkret dla kolejnego treningu.";
    }
    const meta = resolveExerciseMeta(primaryWorkout);
    if (action === "progress") {
      if (meta.loadMode === "cardio") {
        return Number.isFinite(primaryWorkout.distanceKm) && primaryWorkout.distanceKm > 0
          ? `${primaryWorkout.exerciseName}: dodaj około 0.3-0.5 km albo 5 minut, jeśli oddech i technika zostaną pod kontrolą.`
          : `${primaryWorkout.exerciseName}: dodaj 5-8 minut spokojnej pracy, bez skoku intensywności.`;
      }
      if (Number.isFinite(primaryWorkout.weightKg) && primaryWorkout.weightKg > 0) {
        return `${primaryWorkout.exerciseName}: sprobuj +1 powtórzenie w serii albo +2.5 kg, ale tylko przy podobnej technice.`;
      }
      return `${primaryWorkout.exerciseName}: dodaj 1-2 powtórzenia łącznie albo jedna bardzo spokojna serie techniczna.`;
    }
    if (action === "reduce") {
      if (meta.loadMode === "cardio") {
        return `${primaryWorkout.exerciseName}: następnym razem zostaw intensywność, ale skróć czas o 10-20% albo zrób spokojniejszą wersję.`;
      }
      return `${primaryWorkout.exerciseName}: obetnij 1 serię albo 5-10% ciężaru, jeśli nadal czujesz zmęczenie.`;
    }
    if (action === "deload") {
      return `${primaryWorkout.exerciseName}: zrób lżejszą wersję, około 60-70% normalnej objętości i bez serii blisko maksa.`;
    }
    return `${primaryWorkout.exerciseName}: powtórz podobne parametry. Celem kolejnej sesji jest jakość, niekoniecznie zmiana ciężaru.`;
  }

  function buildPostWorkoutDecision(date, difficulty, workouts, dataArg) {
    const normalized = normalizeData(dataArg || state.data);
    const sessionWorkouts = Array.isArray(workouts) ? workouts : getSessionWorkoutsForDate(date, normalized);
    const safeDifficulty = Number.isFinite(difficulty) ? difficulty : NaN;
    const averageRpe = round(average(sessionWorkouts.map((workout) => workout.intensityRpe)), 1);
    const effortSignal = Number.isFinite(safeDifficulty) && Number.isFinite(averageRpe)
      ? round((safeDifficulty * 0.7) + (averageRpe * 0.3), 1)
      : Number.isFinite(safeDifficulty)
        ? safeDifficulty
        : averageRpe;
    const latestEntry = getLatestEntryOnOrBefore(normalized.entries, date);
    const sleepHours = latestEntry && Number.isFinite(latestEntry.sleepHours) ? latestEntry.sleepHours : NaN;
    const previousFeedbacks = getPreviousSessionFeedbacks(normalized.workouts, date);
    const recentHighCount = previousFeedbacks.slice(0, 3).filter((item) => item.difficulty >= 8.5).length;
    const primaryWorkout = pickPrimaryWorkoutForSession(sessionWorkouts);
    const totalDuration = round(sessionWorkouts.reduce((sum, workout) => sum + (Number(workout.durationMin) || 0), 0), 0);
    const totalCalories = round(sessionWorkouts.reduce((sum, workout) => sum + (Number(workout.estimatedCalories) || 0), 0), 0);
    const lowSleep = Number.isFinite(sleepHours) && sleepHours < 6;
    const solidSleep = !Number.isFinite(sleepHours) || sleepHours >= 6.7;

    if (!sessionWorkouts.length) {
      return {
        available: false,
        statusLabel: "Brak sesji",
        tone: "warn",
        cards: [],
        items: ["Najpierw zapisz ćwiczenia dla wybranej daty, a potem oceń, jak ciężka była cała sesja."],
      };
    }

    if (!Number.isFinite(safeDifficulty)) {
      return {
        available: false,
        statusLabel: "Oceń sesję",
        tone: "warn",
        cards: [
          {
            label: "Sesja",
            value: `${sessionWorkouts.length} ćw.`,
            support: `${Number.isFinite(totalDuration) && totalDuration > 0 ? `${totalDuration} min` : "czas niepelny"} · ${Number.isFinite(totalCalories) && totalCalories > 0 ? `${totalCalories} kcal` : "kcal w trakcie"}.`,
            tone: "warn",
          },
        ],
        items: ["Wpisz ocenę 1-10 po treningu. 1-3 oznacza bardzo lekko, 4-7 normalnie, 8 ciężko, 9-10 bardzo ciężko."],
      };
    }

    let action = "hold";
    let label = "Utrzymaj plan";
    let tone = "good";
    let reason = "Sesja była w normalnym zakresie trudności, więc najlepsza decyzja to powtórzyć parametry i ocenić jakość wykonania.";

    if (safeDifficulty >= 9.2 || (Number.isFinite(averageRpe) && averageRpe >= 9.2)) {
      action = recentHighCount >= 1 || lowSleep ? "deload" : "reduce";
      label = action === "deload" ? "Zrób lżejszy kolejny trening" : "Nie dokładaj, lekko obetnij";
      tone = "risk";
      reason = recentHighCount >= 1
        ? "To kolejna bardzo ciężka sesja w ostatnim czasie. Rośnie ryzyko kumulacji zmęczenia, więc lepszy jest mały deload niż dokładanie."
        : "Sesja była bardzo ciężka. Nawet jeśli poszła dobrze, następny trening powinien najpierw potwierdzić regenerację.";
    } else if (safeDifficulty >= 8 || (Number.isFinite(averageRpe) && averageRpe >= 8.5)) {
      action = lowSleep ? "reduce" : "hold";
      label = lowSleep ? "Lżej przez regenerację" : "Utrzymaj bez dokładania";
      tone = "warn";
      reason = lowSleep
        ? "Trudna sesja i słaby sen to za dużo sygnałów ryzyka na agresywną progresję."
        : "Sesja była ciężka, ale nie alarmowa. Najrozsądniej utrzymać plan i nie dokładać bodźca na siłę.";
    } else if (safeDifficulty <= 3.5 && solidSleep && recentHighCount === 0) {
      action = "progress";
      label = "Dodaj mały krok";
      tone = "good";
      reason = "Sesja była wyraźnie lekka, a historia nie pokazuje ostatnio przeciążenia. Można dołożyć bardzo mały bodziec.";
    } else if (safeDifficulty <= 5 && Number.isFinite(averageRpe) && averageRpe <= 7.2 && solidSleep && recentHighCount === 0) {
      action = "progress";
      label = "Minimalna progresja";
      tone = "good";
      reason = "Ocena i RPE są spokojne. Dopuszczalny jest mały progres, ale bez skoku objętości.";
    }

    const adjustment = buildNextWorkoutAdjustmentText(action, primaryWorkout);
    const cards = [
      {
        label: "Trudność sesji",
        value: `${round(safeDifficulty, 1)}/10`,
        support: Number.isFinite(averageRpe)
          ? `Średnie RPE ćwiczeń: ${averageRpe}. Sygnał łączny: ${round(effortSignal, 1)}/10.`
          : `Sygnał łączny: ${round(effortSignal, 1)}/10. Dodaj RPE ćwiczeń, aby analiza była dokładniejsza.`,
        tone,
      },
      {
        label: "Decyzja AI",
        value: label,
        support: reason,
        tone,
      },
      {
        label: "Nastepny trening",
        value: action === "progress" ? "Maly progres" : action === "hold" ? "Bez zmian" : "Mniej bodzca",
        support: adjustment,
        tone,
      },
    ];
    const items = [
      reason,
      adjustment,
      Number.isFinite(sleepHours)
        ? `Sen z najbliższego wpisu dziennika: ${round(sleepHours, 1)} h. ${lowSleep ? "To obniża gotowość do dokładania." : "Nie blokuje progresji."}`
        : "Brakuje snu w dzienniku, więc decyzja mocniej opiera się na odczuciu sesji i RPE.",
    ];
    if (recentHighCount > 0) {
      items.push(`W ostatnich 3 ocenionych sesjach bylo ${recentHighCount} bardzo ciężkich. To sygnał, żeby nie dokładać zbyt szybko.`);
    }

    return {
      available: true,
      statusLabel: label,
      tone,
      action,
      cards,
      items,
    };
  }

  function renderPostWorkoutCoach() {
    if (!elements.postWorkoutDecisionCards || !elements.postWorkoutDecisionList || !elements.postWorkoutCoachStatus) {
      return;
    }
    const date = elements.workoutDateInput.value || toISODate(new Date());
    const workouts = getSessionWorkoutsForDate(date);
    const feedback = getSessionFeedbackFromWorkouts(workouts);

    if (Number.isFinite(feedback.difficulty)) {
      elements.postWorkoutDifficultyInput.value = toInputValue(feedback.difficulty);
    } else {
      elements.postWorkoutDifficultyInput.value = "";
    }
    elements.postWorkoutNotesInput.value = feedback.notes || "";

    const manualDifficulty = parseLooseNumber(elements.postWorkoutDifficultyInput.value);
    const decision = buildPostWorkoutDecision(date, Number.isFinite(manualDifficulty) ? manualDifficulty : feedback.difficulty, workouts, state.data);

    renderMetricCardCollection(
      elements.postWorkoutDecisionCards,
      state.unlocked ? decision.cards : [],
      state.unlocked
        ? "Zapisz ćwiczenia i ocenę sesji, aby zobaczyć decyzję na kolejny trening."
        : "Zaloguj się, aby korzystac z asystenta decyzji po treningu."
    );
    renderTextList(
      elements.postWorkoutDecisionList,
      state.unlocked ? decision.items : [],
      "Po ocenie sesji aplikacja powie, czy progresowac, utrzymać plan czy zejsc z bodzca."
    );

    if (!state.unlocked) {
      elements.postWorkoutCoachStatus.textContent = "Zablokowane";
      elements.postWorkoutCoachStatus.className = "status-pill status-locked";
      return;
    }
    const statusClass = decision.tone === "risk"
      ? "status-risk"
      : decision.tone === "warn"
        ? "status-warn"
        : "status-unlocked";
    elements.postWorkoutCoachStatus.textContent = decision.statusLabel;
    elements.postWorkoutCoachStatus.className = `status-pill ${statusClass}`;
  }

  async function handleSavePostWorkoutDecision() {
    if (!requireUnlocked()) {
      return;
    }
    try {
      const date = elements.workoutDateInput.value;
      if (!date) {
        throw new Error("Wybierz date treningu.");
      }
      const difficulty = parseStrictNumber(elements.postWorkoutDifficultyInput.value, {
        label: "Ocena trudnosci sesji",
        min: 1,
        max: 10,
        integer: true,
      });
      const notes = sanitizePlainText(elements.postWorkoutNotesInput.value, 180);
      const workouts = getSessionWorkoutsForDate(date);
      if (!workouts.length) {
        throw new Error("Najpierw zapisz przynajmniej jedno ćwiczenie dla tej daty.");
      }
      const workoutIds = new Set(workouts.map((workout) => workout.id));
      const feedbackAt = new Date().toISOString();
      state.data.workouts = state.data.workouts.map((workout) => workoutIds.has(workout.id)
        ? {
            ...workout,
            sessionDifficulty: difficulty,
            sessionFeedbackNotes: notes,
            sessionFeedbackAt: feedbackAt,
          }
        : workout
      );
      state.data.workouts = sortWorkouts(state.data.workouts.map(normalizeWorkout).filter(Boolean));
      await persistVault();
      renderDashboard();
      const decision = buildPostWorkoutDecision(date, difficulty, getSessionWorkoutsForDate(date), state.data);
      showStatus(`Zapisano ocenę sesji ${difficulty}/10. Decyzja AI: ${decision.statusLabel}.`);
    } catch (error) {
      showStatus(error.message || "Nie udało się zapisać oceny sesji.", true);
    }
  }

  async function handleClearPostWorkoutDecision() {
    if (!requireUnlocked()) {
      return;
    }
    try {
      const date = elements.workoutDateInput.value;
      if (!date) {
        throw new Error("Wybierz date treningu.");
      }
      const workouts = getSessionWorkoutsForDate(date);
      if (!workouts.length) {
        elements.postWorkoutDifficultyInput.value = "";
        elements.postWorkoutNotesInput.value = "";
        renderPostWorkoutCoach();
        return;
      }
      const workoutIds = new Set(workouts.map((workout) => workout.id));
      state.data.workouts = state.data.workouts.map((workout) => {
        if (!workoutIds.has(workout.id)) {
          return workout;
        }
        const { sessionDifficulty, sessionFeedbackNotes, sessionFeedbackAt, ...rest } = workout;
        return rest;
      });
      state.data.workouts = sortWorkouts(state.data.workouts.map(normalizeWorkout).filter(Boolean));
      elements.postWorkoutDifficultyInput.value = "";
      elements.postWorkoutNotesInput.value = "";
      await persistVault();
      renderDashboard();
      showStatus("Wyczyszczono ocenę sesji dla wybranej daty.");
    } catch (error) {
      showStatus(error.message || "Nie udało się wyczyścić oceny sesji.", true);
    }
  }

  function resetWorkoutForm(preserveDate) {
    const fallbackDate = sanitizePlainText(preserveDate, 20) || elements.workoutDateInput.value || toISODate(new Date());
    elements.workoutForm.reset();
    state.editingWorkoutId = null;
    elements.workoutDateInput.value = fallbackDate;
    if (elements.templateExecutionDateInput) {
      elements.templateExecutionDateInput.value = fallbackDate;
    }
    elements.activityProfileInput.value = "strength";
    syncWorkoutFormMode();
    syncExerciseTemplateInput("workout");
    renderPostWorkoutCoach();
  }

  function syncWorkoutFormMode() {
    const editing = Boolean(state.editingWorkoutId);
    elements.saveWorkoutButton.textContent = editing ? "Zapisz ćwiczenie" : "Dodaj ćwiczenie";
    elements.resetWorkoutButton.textContent = editing ? "Anuluj edycję treningu" : "Wyczyść trening";
  }

  function renderWorkoutTable(workouts) {
    elements.workoutBody.replaceChildren();
    if (state.unlocked) {
      const filteredWorkouts = filterWorkouts(workouts);
      if (workouts.length && !filteredWorkouts.length) {
        elements.workoutBody.appendChild(createEmptyTableRow("Brak aktywności treningowych pasujących do aktywnych filtrów.", 6));
        return;
      }
      workouts = filteredWorkouts;
    } else {
      elements.workoutFilterSummary.textContent = "Filtry aktywności uaktywnia się po zalogowaniu.";
    }

    if (!state.unlocked) {
      elements.workoutBody.appendChild(createEmptyTableRow("Zaloguj się, aby zobaczyć treningi.", 6));
      return;
    }

    if (!workouts.length) {
      elements.workoutBody.appendChild(createEmptyTableRow("Brak zapisanych ćwiczeń.", 6));
      return;
    }

    const settings = normalizeData(state.data).settings;
    const currentWeight = getCurrentWeightForCalculations(settings, state.data.entries);

    workouts.forEach((workout) => {
      const row = document.createElement("tr");
      row.appendChild(createCell(formatDisplayDate(workout.date)));
      row.appendChild(createCell(workout.exerciseName));
      row.appendChild(createCell(formatWorkoutPlan(workout)));
      row.appendChild(createCell(formatMetric(workout.durationMin, "min")));
      row.appendChild(createCell(formatMetric(getWorkoutCalories(workout, settings, currentWeight), "kcal")));

      const actionCell = document.createElement("td");
      const actionWrap = document.createElement("div");
      actionWrap.className = "table-actions";

      const editButton = document.createElement("button");
      editButton.type = "button";
      editButton.className = "edit-button";
      editButton.setAttribute("data-workout-id", workout.id);
      editButton.setAttribute("data-workout-action", "edit");
      editButton.textContent = "Edytuj";

      const historyButton = document.createElement("button");
      historyButton.type = "button";
      historyButton.className = "edit-button";
      historyButton.setAttribute("data-workout-id", workout.id);
      historyButton.setAttribute("data-workout-action", "history");
      historyButton.textContent = "Historia";

      const deleteButton = document.createElement("button");
      deleteButton.type = "button";
      deleteButton.className = "delete-button";
      deleteButton.setAttribute("data-workout-id", workout.id);
      deleteButton.setAttribute("data-workout-action", "delete");
      deleteButton.textContent = "Usuń";

      actionWrap.append(editButton, historyButton, deleteButton);
      actionCell.appendChild(actionWrap);
      row.appendChild(actionCell);

      elements.workoutBody.appendChild(row);
    });
  }

  function renderExerciseSummary(exerciseSummaries) {
    elements.exerciseSummaryBody.replaceChildren();
    if (state.unlocked) {
      const filteredExercises = filterExerciseSummaries(exerciseSummaries);
      if (exerciseSummaries.length && !filteredExercises.length) {
        elements.exerciseSummaryBody.appendChild(createEmptyTableRow("Brak ruchow lub aktywności pasujących do aktywnych filtrów.", 8));
        return;
      }
      exerciseSummaries = filteredExercises;
    } else {
      elements.exerciseFilterSummary.textContent = "Filtry ruchow uaktywnia się po zalogowaniu.";
    }

    if (!state.unlocked) {
      elements.exerciseSummaryBody.appendChild(createEmptyTableRow("Zaloguj się, aby zobaczyć statystyki ćwiczeń.", 8));
      return;
    }

    if (!exerciseSummaries.length) {
      elements.exerciseSummaryBody.appendChild(createEmptyTableRow("Dodaj pierwsze ćwiczenie, aby śledzić regularność, parametry i kalorie treningowe.", 8));
      return;
    }

    exerciseSummaries.forEach((item) => {
      const row = document.createElement("tr");
      row.appendChild(createCell(item.exerciseName));
      row.appendChild(createCell(formatDisplayDate(item.latestDate)));
      row.appendChild(createCell(item.latestLoadLabel || formatMetric(item.latestWeightKg, "kg")));
      row.appendChild(createCell(item.bestPerformanceLabel || formatMetric(item.bestEstimated1RM, "kg")));
      row.appendChild(createCell(formatMetric(item.sessions30Days, "")));
      row.appendChild(createCell(item.workload30DaysLabel || (item.sessions30Days ? `${item.sessions30Days} sesji` : "brak")));
      row.appendChild(createCell(formatMetric(item.calories30Days, "kcal")));

      const actionCell = document.createElement("td");
      const actionWrap = document.createElement("div");
      actionWrap.className = "table-actions";

      const historyButton = document.createElement("button");
      historyButton.type = "button";
      historyButton.className = "edit-button";
      historyButton.setAttribute("data-exercise-name", item.exerciseName);
      historyButton.setAttribute("data-exercise-action", "history");
      historyButton.textContent = "Historia";

      actionWrap.appendChild(historyButton);
      actionCell.appendChild(actionWrap);
      row.appendChild(actionCell);
      elements.exerciseSummaryBody.appendChild(row);
    });
  }
function renderExerciseHistory(exerciseHistory) {
    populateExerciseHistorySelect(exerciseHistory.availableExercises, exerciseHistory.selectedExerciseName);
    renderExerciseHistoryCards(exerciseHistory);
    renderExercisePrList(exerciseHistory);
    renderExerciseHistoryTable(exerciseHistory);
  }

  function populateExerciseHistorySelect(availableExercises, selectedExerciseName) {
    elements.exerciseHistorySelect.replaceChildren();

    const placeholder = document.createElement("option");
    placeholder.value = "";
    placeholder.textContent = availableExercises.length ? "Wybierz ćwiczenie" : "Brak zapisanych ćwiczeń";
    elements.exerciseHistorySelect.appendChild(placeholder);

    availableExercises.forEach((exerciseName) => {
      const option = document.createElement("option");
      option.value = exerciseName;
      option.textContent = exerciseName;
      elements.exerciseHistorySelect.appendChild(option);
    });

    if (selectedExerciseName && availableExercises.includes(selectedExerciseName)) {
      elements.exerciseHistorySelect.value = selectedExerciseName;
      state.selectedExerciseName = selectedExerciseName;
    } else {
      elements.exerciseHistorySelect.value = "";
      state.selectedExerciseName = selectedExerciseName || null;
    }
  }

  function renderExerciseHistoryCards(exerciseHistory) {
    elements.exerciseHistoryCards.replaceChildren();

    if (!state.unlocked) {
      elements.exerciseHistoryCards.appendChild(createMutedParagraph("Zaloguj się, aby śledzić historię pojedynczego ćwiczenia."));
      elements.exerciseHistorySummary.textContent = "Po zalogowaniu pojawi się tu szczegółowa analiza wybranego ruchu.";
      return;
    }

    if (!exerciseHistory.selectedExerciseName) {
      elements.exerciseHistoryCards.appendChild(createMutedParagraph("Dodaj ćwiczenia i wybierz konkretny ruch, aby zobaczyć jego PR-y i trend."));
      elements.exerciseHistorySummary.textContent = "Po zapisaniu ćwiczeń aplikacja pokaże tutaj pełną historię pojedynczego ruchu.";
      return;
    }

    elements.exerciseHistorySummary.textContent = exerciseHistory.summary;

    exerciseHistory.cards.forEach((card) => {
      const article = document.createElement("article");
      article.className = "metric-card";

      const label = document.createElement("span");
      label.className = "metric-label";
      label.textContent = card.label;

      const value = document.createElement("p");
      value.className = `metric-value ${card.tone ? `metric-tone-${card.tone}` : ""}`.trim();
      value.textContent = card.value;

      const support = document.createElement("p");
      support.className = "metric-support";
      support.textContent = card.support;

      article.append(label, value, support);
      elements.exerciseHistoryCards.appendChild(article);
    });
  }

  function renderExercisePrList(exerciseHistory) {
    elements.exercisePrList.replaceChildren();

    let items = [];
    if (!state.unlocked) {
      items = ["Zaloguj się, aby zobaczyć ostatnie rekordy i przełamania progresu."];
    } else if (!exerciseHistory.selectedExerciseName) {
      items = ["Wybierz ćwiczenie, aby aplikacja pokazała listę ostatnich PR-ów tego ruchu."];
    } else if (exerciseHistory.prEvents.length) {
      items = exerciseHistory.prEvents;
    } else {
      items = ["Brak nowych PR-ów do pokazania. Dodaj więcej sesji tego ćwiczenia, aby aplikacja wychwyciła kolejne rekordy."];
    }

    items.forEach((message) => {
      const item = document.createElement("li");
      item.textContent = message;
      elements.exercisePrList.appendChild(item);
    });
  }

    function renderExerciseHistoryTable(exerciseHistory) {
    elements.exerciseHistoryBody.replaceChildren();
    if (state.unlocked && exerciseHistory.selectedExerciseName && exerciseHistory.sessions.length) {
      const filteredSessions = filterExerciseHistorySessions(exerciseHistory.sessions);
      if (!filteredSessions.length) {
        elements.exerciseHistoryBody.appendChild(createEmptyTableRow("Brak sesji wybranego ruchu pasujących do aktywnych filtrów.", 7));
        return;
      }
      exerciseHistory = { ...exerciseHistory, sessions: filteredSessions };
    } else if (!state.unlocked) {
      elements.exerciseHistoryFilterSummary.textContent = "Filtry historii uaktywnia się po zalogowaniu.";
    } else if (!exerciseHistory.selectedExerciseName) {
      elements.exerciseHistoryFilterSummary.textContent = "Wybierz ruch, aby włączyć filtrowanie historii sesji.";
    }

    if (!state.unlocked) {
      elements.exerciseHistoryBody.appendChild(createEmptyTableRow("Zaloguj się, aby zobaczyć historię sesji dla wybranego ćwiczenia.", 7));
      return;
    }

    if (!exerciseHistory.selectedExerciseName) {
      elements.exerciseHistoryBody.appendChild(createEmptyTableRow("Wybierz ćwiczenie, aby przejrzeć jego ostatnie sesje.", 7));
      return;
    }

    if (!exerciseHistory.sessions.length) {
      elements.exerciseHistoryFilterSummary.textContent = "Brak zapisanych sesji dla wybranego ruchu.";
      elements.exerciseHistoryBody.appendChild(createEmptyTableRow("Brak sesji dla wybranego ćwiczenia.", 7));
      return;
    }

    exerciseHistory.sessions.forEach((session) => {
      const row = document.createElement("tr");
      row.appendChild(createCell(formatDisplayDate(session.date)));
      row.appendChild(createCell(session.planSummary));
      row.appendChild(createCell(session.primaryMetricLabel || session.topLoadLabel || formatMetric(session.topWeightKg, "kg")));
      row.appendChild(createCell(session.workloadLabel || formatSessionActivitySummary(session, { includeCalories: true })));
      row.appendChild(createCell(session.qualityMetricLabel || formatMetric(session.bestEstimated1RM, "kg")));
      row.appendChild(createCell(formatMetric(session.totalCalories, "kcal")));
      row.appendChild(createCell(session.notePreview || "brak"));
      elements.exerciseHistoryBody.appendChild(row);
    });
  }
function handleExerciseSummaryTableAction(event) {
    const actionButton = event.target.closest("button[data-exercise-name][data-exercise-action]");
    if (!actionButton || !state.unlocked) {
      return;
    }

    const exerciseName = actionButton.getAttribute("data-exercise-name");
    if (!exerciseName) {
      return;
    }

    const action = actionButton.getAttribute("data-exercise-action");
    if (action === "history") {
      openExerciseHistory(exerciseName, { scroll: true, status: true });
    }
  }

  function handleExerciseHistorySelection() {
    if (!state.unlocked) {
      return;
    }

    state.selectedExerciseName = sanitizePlainText(elements.exerciseHistorySelect.value, 80) || null;
    renderDashboard();
  }

  function openExerciseHistory(exerciseName, options) {
    const sanitizedName = sanitizePlainText(exerciseName, 80);
    if (!sanitizedName) {
      return;
    }

    state.selectedExerciseName = sanitizedName;
    setActiveTab("history", { scroll: false });
    renderDashboard();

    if (options && options.scroll) {
      elements.exerciseHistorySelect.scrollIntoView({ behavior: "smooth", block: "start" });
    }
    if (options && options.status) {
      showStatus(`Wybrano historię ćwiczenia ${sanitizedName}.`);
    }
  }

