      reps: reps ? Math.round(reps) : null,
      weightKg,
      distanceKm,
      elevationGainM,
      paceMinKm: Number.isFinite(paceMinKm)
        ? paceMinKm
        : Number.isFinite(distanceKm) && Number.isFinite(durationMin) && distanceKm > 0
          ? round(durationMin / distanceKm, 2)
          : null,
      avgSpeedKmh: Number.isFinite(avgSpeedKmh)
